export type Mode = 'chat' | 'live' | 'toolbox' | 'community';
export type UIStyle = 'modern' | 'glass' | 'brutal' | 'retro';
export type AccentColor = 'blue' | 'violet' | 'emerald' | 'rose' | 'amber';
export type FontSize = 'small' | 'normal' | 'large';

export type ModelType = 
  | 'cognix-rv2'      // gemini-3-flash-preview (Fast/Friendly)
  | 'clora-v1'       // gemini-3-pro-preview (Reasoning)
  | 'clorea-v2.5'    // gemini-flash-lite-latest (Lightweight)
  | 'arctic-x'       // gemini-3-pro-preview (Coding)
  | 'visualizer';    // gemini-2.5-flash-image

export interface Friend {
  id: string;
  name: string;
  avatar: string;
  status: 'online' | 'offline' | 'busy' | 'away';
}

export interface Deployment {
  id: string;
  title: string;
  code: string;
  timestamp: number;
}

export interface CommunityPost {
    id: string;
    author: string;
    authorId: string;
    content: string;
    timestamp: number;
    likedBy: string[];
    replies: any[];
    type: 'text' | 'image' | 'code';
}

export interface MemoryFact {
    id: string;
    category: 'preference' | 'project' | 'personal' | 'work';
    content: string;
    timestamp: string;
}

export interface ThemeColors {
    primary: string;
    primaryHover: string;
    text: string;
    textDark: string;
    bgSoft: string;
    darkBgSoft: string;
    border: string;
    ring: string;
    gradient: string;
}

export interface ChatPart {
  text?: string;
  inlineData?: {
    mimeType: string;
    data: string;
  };
  searchResults?: any[];
}

export interface ChatMessage {
  id: string;
  role: 'user' | 'model';
  parts: ChatPart[];
  isSearching?: boolean;
}

export interface ChatSession {
  id:string;
  title: string;
  messages: ChatMessage[];
  participants: string[]; 
}

import React, { useState, useEffect, useMemo } from 'react';
import { ChatView } from './components/ChatView';
import { LiveView } from './components/LiveView';
import { Sidebar } from './components/Sidebar';
import { CommunityView } from './components/CommunityView';
import { ToolboxView } from './components/ToolboxView';
import { MenuIcon, BotIcon, UserIcon, MicrophoneIcon } from './components/Icons';
import { SettingsModal } from './components/SettingsModal';
import type { ChatMessage, ChatSession, Mode, ThemeColors, ModelType, MemoryFact } from './types';

const THEME: ThemeColors = {
    primary: 'bg-black dark:bg-white',
    primaryHover: 'hover:opacity-90',
    text: 'text-black dark:text-white',
    textDark: 'text-white dark:text-black',
    bgSoft: 'bg-slate-50',
    darkBgSoft: 'dark:bg-slate-900',
    border: 'border-slate-200 dark:border-slate-800',
    ring: 'focus:ring-black dark:focus:ring-white',
    gradient: 'bg-black dark:bg-white'
};

const App: React.FC = () => {
  const [mode, setMode] = useState<Mode>('chat');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [activeModel, setActiveModel] = useState<ModelType>('cognix-rv2');
  const [systemInstruction, setSystemInstruction] = useState("Hey! I'm Cognix, your elite AI companion. I focus on precision and creative intelligence.");
  const [deploymentHtml, setDeploymentHtml] = useState<string | null>(null);

  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [chatHistory, setChatHistory] = useState<ChatSession[]>([]);
  const [activeChatId, setActiveChatId] = useState<string | null>(null);
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [memories, setMemories] = useState<MemoryFact[]>([]);

  const currentChat = useMemo(() => chatHistory.find(c => c.id === activeChatId), [chatHistory, activeChatId]);

  useEffect(() => {
    const savedHistory = localStorage.getItem('cognix_v8_history');
    if (savedHistory) setChatHistory(JSON.parse(savedHistory));

    const savedVault = localStorage.getItem('nexzi_vault');
    if (savedVault) setMemories(JSON.parse(savedVault));

    const themeSaved = localStorage.getItem('cognix_theme');
    if (themeSaved === 'dark') {
      setIsDarkMode(true);
      document.documentElement.classList.add('dark');
    }

    const params = new URLSearchParams(window.location.search);

    // Neural Handshake (Session Sharing)
    const handshake = params.get('handshake');
    if (handshake) {
      try {
        const decodedStr = decodeURIComponent(escape(atob(handshake)));
        const decoded = JSON.parse(decodedStr);
        const newId = 'collective-' + Date.now();
        const sharedChat: ChatSession = {
          id: newId,
          title: decoded.title || 'Shared Pulse',
          messages: decoded.messages || [],
          participants: ['You', 'Handshake Node']
        };
        setChatHistory(prev => [sharedChat, ...prev]);
        setActiveChatId(newId);
        setMode('chat');
      } catch (e) { console.error("Neural link handshake failed", e); }
    }

    // UI Deployment Loader
    const deployment = params.get('deployment');
    if (deployment) {
      try {
        const decoded = decodeURIComponent(escape(atob(deployment)));
        setDeploymentHtml(decoded);
      } catch (e) { console.error("Deployment asset failed to load", e); }
    }

    if (handshake || deployment) {
      window.history.replaceState({}, document.title, window.location.pathname);
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('cognix_v8_history', JSON.stringify(chatHistory));
  }, [chatHistory]);

  useEffect(() => {
    localStorage.setItem('nexzi_vault', JSON.stringify(memories));
  }, [memories]);

  useEffect(() => { 
    setMessages(currentChat ? currentChat.messages : []); 
  }, [currentChat?.id]);

  const handleUpdateMessages = (updater: (prev: ChatMessage[]) => ChatMessage[]) => {
    setMessages(prev => {
      const next = updater(prev);
      if (activeChatId) {
        setChatHistory(h => h.map(c => c.id === activeChatId ? { ...c, messages: next } : c));
      } else if (next.length > 0) {
        const newId = Date.now().toString();
        const firstUserMsg = next.find(m => m.role === 'user');
        const titleText = firstUserMsg?.parts.find(p => p.text)?.text;
        const title = titleText ? titleText.slice(0, 40) : 'New Pulse';
        setChatHistory([{ id: newId, title: title || 'New Pulse', messages: next, participants: ['You'] }, ...chatHistory]);
        setActiveChatId(newId);
      }
      return next;
    });
  };

  const handleNewChat = () => {
    setActiveChatId(null);
    setMessages([]);
    setMode('chat');
  };

  const toggleDarkMode = (dark: boolean) => {
    setIsDarkMode(dark);
    if (dark) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('cognix_theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('cognix_theme', 'light');
    }
  };

  return (
    <div className="h-full w-full flex bg-white dark:bg-slate-950 transition-colors duration-500 overflow-hidden font-sans">
      {deploymentHtml ? (
        <div className="fixed inset-0 z-[1000] bg-white dark:bg-black">
          <div className="absolute top-6 right-6 z-[1001]">
            <button onClick={() => setDeploymentHtml(null)} className="px-6 py-3 bg-black text-white dark:bg-white dark:text-black rounded-2xl font-black text-[10px] uppercase shadow-2xl transition-all active:scale-95">De-Infect Preview</button>
          </div>
          <iframe srcDoc={deploymentHtml} className="w-full h-full border-none" />
        </div>
      ) : null}

      <Sidebar 
        chatHistory={chatHistory} 
        activeChatId={activeChatId} 
        mode={mode}
        onSetMode={setMode}
        onSelectChat={(id) => { setActiveChatId(id); setMode('chat'); }}
        onNewChat={handleNewChat}
        onDeleteChat={(id) => { 
          setChatHistory(h => h.filter(c => c.id !== id)); 
          if(activeChatId === id) handleNewChat(); 
        }}
        isSidebarOpen={isSidebarOpen}
        isSidebarCollapsed={isSidebarCollapsed}
        onToggleCollapse={() => setIsSidebarCollapsed(!isSidebarCollapsed)}
        onClose={() => setIsSidebarOpen(false)}
      />

      <div className={`flex-1 flex flex-col h-full relative overflow-hidden transition-all duration-300 ${isSidebarCollapsed ? 'lg:pl-0' : ''}`}>
        <header className="h-14 sm:h-16 flex items-center justify-between px-4 sm:px-8 z-50 bg-white/80 dark:bg-slate-900/80 backdrop-blur-2xl border-b border-slate-100 dark:border-slate-800 transition-colors">
          <div className="flex items-center gap-4">
            <button onClick={() => {
              if (window.innerWidth < 1024) setIsSidebarOpen(true);
              else setIsSidebarCollapsed(!isSidebarCollapsed);
            }} className="p-2 -ml-2 text-slate-900 dark:text-white transition-all hover:bg-slate-100 dark:hover:bg-slate-800 rounded-lg active:scale-90">
              <MenuIcon className="w-5 h-5"/>
            </button>
            <div className="flex items-center gap-3">
              <BotIcon className="w-7 h-7 cursor-pointer transition-transform hover:scale-105" onClick={handleNewChat} />
              <div className="flex flex-col">
                <span className="text-[13px] font-black text-slate-900 dark:text-white tracking-tight uppercase leading-none italic">{mode.toUpperCase()}</span>
                <span className="text-[8px] font-black text-slate-400 uppercase tracking-widest leading-none mt-0.5">V11.2</span>
              </div>
            </div>
          </div>

          <div className="flex items-center gap-3">
            <button 
              onClick={() => setMode(mode === 'live' ? 'chat' : 'live')}
              className={`w-9 h-9 flex items-center justify-center rounded-xl transition-all shadow-sm border ${mode === 'live' ? 'bg-black text-white dark:bg-white dark:text-black border-black dark:border-white animate-pulse' : 'bg-slate-50 dark:bg-slate-800/50 text-slate-400 border-slate-200 dark:border-slate-700 hover:text-black dark:hover:text-white'}`}
              title="Voice Protocol"
            >
              <MicrophoneIcon className="w-4 h-4" />
            </button>
            <button 
              onClick={() => setIsSettingsOpen(true)}
              className="w-9 h-9 flex items-center justify-center bg-slate-50 dark:bg-slate-800/50 rounded-xl text-slate-400 hover:text-black dark:hover:text-white transition-all shadow-sm border border-slate-200 dark:border-slate-700"
            >
              <UserIcon className="w-4 h-4" />
            </button>
          </div>
        </header>

        <main className="flex-1 relative overflow-hidden h-full">
           {mode === 'chat' && (
              <ChatView 
                messages={messages} 
                setMessages={(val) => {
                  if (typeof val === 'function') handleUpdateMessages(val as any);
                  else handleUpdateMessages(() => val as any);
                }} 
                systemInstruction={systemInstruction} 
                model={activeModel} 
                setActiveModel={setActiveModel} 
                participants={['You']}
                onAddParticipant={() => {}}
                currentChat={currentChat}
                isSidebarCollapsed={isSidebarCollapsed}
                memories={memories}
              />
           )}
           {mode === 'live' && <LiveView />}
           {mode === 'toolbox' && <ToolboxView theme={THEME} model={activeModel} />}
           {mode === 'community' && <CommunityView theme={THEME} model={activeModel} />}
        </main>
      </div>

      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)} 
        isDarkMode={isDarkMode}
        setIsDarkMode={toggleDarkMode}
        systemInstruction={systemInstruction} 
        setSystemInstruction={setSystemInstruction}
        memories={memories}
        setMemories={setMemories}
        onClearHistory={() => { 
          setChatHistory([]); 
          setMessages([]); 
          setActiveChatId(null); 
          setIsSettingsOpen(false); 
          localStorage.removeItem('cognix_v8_history');
        }}
      />
    </div>
  );
}

export default App;

import React, { useState, useRef, useEffect, useCallback } from 'react';
import type { ChatMessage, ChatPart, ModelType, ChatSession, MemoryFact } from '../types';
import { GoogleGenAI } from "@google/genai";
import { SendIcon, ImageIcon, BotIcon, UserIcon, UsersIcon, SparklesIcon, BoltIcon, BrainIcon, CodeIcon } from './Icons';

interface ChatViewProps {
  messages: ChatMessage[];
  setMessages: React.Dispatch<React.SetStateAction<ChatMessage[]>>;
  systemInstruction: string;
  model: ModelType;
  setActiveModel: (m: ModelType) => void;
  participants: string[];
  onAddParticipant: (name: string) => void;
  currentChat?: ChatSession;
  isSidebarCollapsed?: boolean;
  memories?: MemoryFact[];
}

export const ChatView: React.FC<ChatViewProps> = ({ 
  messages, setMessages, systemInstruction, model, setActiveModel, participants, onAddParticipant, currentChat, isSidebarCollapsed, memories = []
}) => {
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isSearchEnabled, setIsSearchEnabled] = useState(false);
  const [selectedImage, setSelectedImage] = useState<{ data: string; mimeType: string } | null>(null);
  const [showModelMenu, setShowModelMenu] = useState(false);
  const [copiedLink, setCopiedLink] = useState(false);

  const containerRef = useRef<HTMLDivElement>(null);
  const fileRef = useRef<HTMLInputElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  const hasMessages = messages.length > 0;

  useEffect(() => {
    if (containerRef.current) {
      containerRef.current.scrollTop = containerRef.current.scrollHeight;
    }
  }, [messages, isLoading]);

  const generateShareLink = () => {
    const data = {
      title: currentChat?.title || 'Shared Pulse',
      messages: messages.slice(-15) 
    };
    try {
        const b64 = btoa(unescape(encodeURIComponent(JSON.stringify(data))));
        const url = `${window.location.origin}${window.location.pathname}?handshake=${b64}`;
        navigator.clipboard.writeText(url);
        setCopiedLink(true);
        setTimeout(() => setCopiedLink(false), 2000);
    } catch(e) { console.error("Sharing sequence failed", e); }
  };

  const handleSend = useCallback(async () => {
    const trimmedInput = input.trim();
    if ((!trimmedInput && !selectedImage) || isLoading) return;

    const parts: ChatPart[] = [];
    if (selectedImage) parts.push({ inlineData: { mimeType: selectedImage.mimeType, data: selectedImage.data } });
    if (trimmedInput) parts.push({ text: trimmedInput });

    const userMsg: ChatMessage = { id: Date.now().toString(), role: 'user', parts };
    const botMsgId = (Date.now() + 1).toString();
    const botPlaceholder: ChatMessage = { id: botMsgId, role: 'model', parts: [{ text: '' }], isSearching: isSearchEnabled };

    setMessages(prev => [...prev, userMsg, botPlaceholder]);
    setInput('');
    setSelectedImage(null);
    setIsLoading(true);

    if (textareaRef.current) { textareaRef.current.style.height = 'auto'; }

    try {
      const apiKey = process.env.API_KEY;
      if (!apiKey) throw new Error("API Key missing");
      const ai = new GoogleGenAI({ apiKey });

      const vaultContext = memories.length > 0 
        ? "\n\nPERSONAL CONTEXT (MEMORY VAULT):\n" + memories.map(m => `- ${m.content}`).join('\n')
        : "";

      let modelInstruction = "";
      let targetModelId = "";

      // Model personality routing
      switch(model) {
        case 'cognix-rv2':
          targetModelId = 'gemini-3-flash-preview';
          modelInstruction = "You are CognixRv2. Be fast, very friendly, and use emojis. ";
          break;
        case 'clora-v1':
          targetModelId = 'gemini-3-pro-preview';
          modelInstruction = "You are CloraV1. Focus on complex reasoning, deep analysis, and high-precision problem solving. ";
          break;
        case 'clorea-v2.5':
          targetModelId = 'gemini-flash-lite-latest';
          modelInstruction = "You are CloreaV2.5, a lightweight efficient assistant for rapid responses and simple tasks. ";
          break;
        case 'arctic-x':
          targetModelId = 'gemini-3-pro-preview';
          modelInstruction = "You are ArcticX, a world-class software engineer and technical architect. Provide clean, efficient code and technical depth. ";
          break;
        default:
          targetModelId = 'gemini-3-flash-preview';
      }

      const finalInstruction = systemInstruction + vaultContext + "\n\n" + modelInstruction;

      // Detect image generation intent
      if (/draw|image|generate an image|create an image|show me an image/i.test(trimmedInput)) {
        targetModelId = 'gemini-2.5-flash-image';
      }

      const history = messages.slice(-10).map(m => ({
        role: m.role,
        parts: m.parts.map(p => p.text ? { text: p.text } : { inlineData: p.inlineData })
      }));

      const res = await ai.models.generateContent({
        model: targetModelId,
        contents: [...history, { role: 'user', parts: parts as any }],
        config: { 
          systemInstruction: finalInstruction,
          tools: isSearchEnabled ? [{ googleSearch: {} }] : [] 
        }
      });

      const resParts: ChatPart[] = res.candidates?.[0]?.content?.parts.map(p => {
        if (p.text) return { text: p.text };
        if (p.inlineData) return { inlineData: { mimeType: p.inlineData.mimeType, data: p.inlineData.data } };
        return { text: "" };
      }).filter(p => p.text !== "" || p.inlineData) || [{ text: "No output generated." }];

      setMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, parts: resParts, isSearching: false } : m));
    } catch (e) {
      setMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, parts: [{ text: "Neural link timeout. Please retry or check your uplink connection." }], isSearching: false } : m));
    } finally {
      setIsLoading(false);
    }
  }, [input, selectedImage, isLoading, messages, systemInstruction, model, isSearchEnabled, setMessages, memories]);

  const modelOptions = [
    { id: 'cognix-rv2', label: 'CognixRv2', desc: 'Fast, friendly & emoji-rich', icon: <BoltIcon className="w-4 h-4"/>, tag: 'Default' },
    { id: 'clora-v1', label: 'CloraV1', desc: 'Deep reasoning for hard tasks', icon: <SparklesIcon className="w-4 h-4"/>, tag: 'Pro' },
    { id: 'clorea-v2.5', label: 'CloreaV2.5', desc: 'Lightweight & ultra-fast', icon: <BrainIcon className="w-4 h-4"/>, tag: 'Lite' },
    { id: 'arctic-x', label: 'ArcticX', desc: 'Coding & architecture specialist', icon: <CodeIcon className="w-4 h-4"/>, tag: 'Dev' }
  ];

  const activeModelData = modelOptions.find(m => m.id === model) || modelOptions[0];

  return (
    <div className="h-full flex flex-col bg-white dark:bg-[#020617] relative overflow-hidden transition-colors duration-300">

      <div 
        ref={containerRef} 
        className={`flex-1 overflow-y-auto px-4 sm:px-6 md:px-12 lg:px-32 scroll-smooth transition-all custom-scrollbar ${
          hasMessages ? 'pb-32 pt-6' : 'flex flex-col items-center justify-center min-h-[80dvh] pb-48'
        }`}
      >
        {!hasMessages ? (
          <div className="w-full max-w-xl mx-auto flex flex-col items-center animate-slide-up text-center select-none pointer-events-none">
             <h2 className="text-2xl sm:text-4xl font-black text-slate-900 dark:text-white tracking-tighter mb-1 leading-tight">Ready for connection.</h2>
             <p className="text-[9px] font-black uppercase tracking-[0.3em] text-slate-400">Node Alpha 11.2 Uplink Active</p>
          </div>
        ) : (
          <div className="max-w-2xl mx-auto space-y-6 w-full pb-10">
            {messages.map((m, idx) => (
              <div key={m.id} className={`flex gap-3 ${m.role === 'user' ? 'flex-row-reverse' : 'flex-row'} animate-slide-up`}>
                <div className={`w-7 h-7 shrink-0 rounded-lg flex items-center justify-center shadow-sm border ${m.role === 'user' ? 'bg-slate-900 border-slate-900 text-white' : 'bg-slate-50 dark:bg-slate-800 border-slate-200 dark:border-slate-700'}`}>
                   {m.role === 'user' ? <UserIcon className="w-3.5 h-3.5"/> : <BotIcon className="w-full h-full p-1"/>}
                </div>
                <div className={`flex flex-col gap-1.5 max-w-[90%] sm:max-w-[80%] ${m.role === 'user' ? 'items-end' : 'items-start'}`}>
                  {m.parts.map((p, i) => (
                    <div key={i} className={`px-4 py-3 text-[14.5px] font-medium leading-relaxed ${m.role === 'user' ? 'bg-slate-100 dark:bg-slate-800 text-slate-900 dark:text-slate-100 rounded-2xl rounded-tr-sm shadow-sm' : 'bg-transparent text-slate-900 dark:text-slate-100'}`}>
                      {p.inlineData && <img src={`data:${p.inlineData.mimeType};base64,${p.inlineData.data}`} className="max-h-[300px] w-full object-contain mb-3 rounded-xl shadow-lg border dark:border-slate-700" alt="Generated Visual" />}
                      {p.text ? <div className="whitespace-pre-wrap">{p.text}</div> : (idx === messages.length - 1 && isLoading && m.role === 'model' && <div className="flex gap-1 py-1.5"><div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce"></div><div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce delay-100"></div><div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce delay-200"></div></div>)}
                    </div>
                  ))}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      <div className={`fixed left-0 right-0 p-3 sm:p-4 z-[60] pointer-events-none transition-all duration-300 ${isSidebarCollapsed ? 'lg:pl-16' : 'lg:pl-[240px]'} ${hasMessages ? 'bottom-0' : 'bottom-12 sm:bottom-24'}`}>
        <div className="max-w-xl mx-auto pointer-events-auto">
          <div className="relative bg-white dark:bg-[#0d111c] border border-slate-200 dark:border-slate-700 rounded-3xl p-1.5 sm:p-2 shadow-[0_15px_35px_-10px_rgba(0,0,0,0.15)] dark:shadow-[0_20px_40px_-10px_rgba(0,0,0,0.4)]">

            <div className="flex items-center gap-1.5 px-2 mb-1.5">
               <button onClick={() => setShowModelMenu(true)} className="flex items-center gap-1.5 py-1 px-2.5 text-slate-700 dark:text-slate-300 font-bold text-[10px] uppercase tracking-wider hover:bg-slate-100 dark:hover:bg-slate-800 rounded-lg transition-all border border-slate-100 dark:border-slate-800">
                  {activeModelData.icon} {activeModelData.label} <span className="text-slate-400">▾</span>
               </button>
               <button onClick={() => setIsSearchEnabled(!isSearchEnabled)} className={`flex items-center gap-1.5 py-1 px-2.5 text-[9px] font-black uppercase tracking-wider rounded-lg border transition-all ${isSearchEnabled ? 'bg-blue-50 dark:bg-blue-900/20 border-blue-200 dark:border-blue-800 text-blue-600' : 'bg-transparent border-transparent text-slate-400 hover:text-slate-600'}`}>
                  LIVE SEARCH
               </button>
            </div>

            {selectedImage && <div className="px-2 pb-2 flex items-center gap-2 animate-fade-in"><div className="relative w-10 h-10 rounded-lg overflow-hidden border border-slate-200 dark:border-slate-700"><img src={`data:${selectedImage.mimeType};base64,${selectedImage.data}`} className="w-full h-full object-cover" /><button onClick={() => setSelectedImage(null)} className="absolute top-0 right-0 bg-red-600 text-white w-4 h-4 flex items-center justify-center rounded-bl-md text-[8px] font-bold">×</button></div></div>}

            <div className="flex items-center gap-1">
                <button onClick={() => fileRef.current?.click()} className="w-9 h-9 shrink-0 flex items-center justify-center text-slate-400 hover:text-slate-900 dark:hover:text-white rounded-xl transition-all"><ImageIcon className="w-5 h-5" /><input type="file" ref={fileRef} className="hidden" accept="image/*" onChange={(e) => { const f = e.target.files?.[0]; if (f) { const r = new FileReader(); r.onloadend = () => setSelectedImage({ data: (r.result as string).split(',')[1], mimeType: f.type }); r.readAsDataURL(f); } }} /></button>
                <textarea ref={textareaRef} value={input} onChange={e => { setInput(e.target.value); e.target.style.height = 'auto'; e.target.style.height = Math.min(e.target.scrollHeight, 150) + 'px'; }} onKeyDown={e => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSend())} placeholder="Message Cognix..." className="flex-1 bg-transparent border-none outline-none resize-none py-2 text-[15px] text-slate-900 dark:text-white placeholder-slate-400 font-medium max-h-[150px] min-h-[36px] custom-scrollbar" rows={1} />
                <button onClick={handleSend} disabled={isLoading || (!input.trim() && !selectedImage)} className="w-9 h-9 bg-slate-900 dark:bg-white text-white dark:text-black rounded-full flex items-center justify-center shadow-md disabled:opacity-20 active:scale-95 transition-all"><SendIcon className="w-4 h-4" /></button>
            </div>
          </div>
        </div>
      </div>

      {showModelMenu && (
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm z-[100] flex items-end sm:items-center justify-center p-0 sm:p-4" onClick={() => setShowModelMenu(false)}>
          <div className="bg-white dark:bg-[#0f172a] w-full max-w-[340px] rounded-t-3xl sm:rounded-2xl p-2 shadow-2xl animate-slide-up border border-slate-200 dark:border-slate-800" onClick={e => e.stopPropagation()}>
            <div className="flex flex-col gap-1">
               {modelOptions.map((opt) => (
                 <button 
                  key={opt.id} 
                  onClick={() => { setActiveModel(opt.id as ModelType); setShowModelMenu(false); }} 
                  className={`w-full flex items-start gap-3 p-3 rounded-xl transition-all text-left group ${model === opt.id ? 'bg-slate-50 dark:bg-slate-800' : 'hover:bg-slate-50 dark:hover:bg-slate-800/40'}`}
                 >
                    <div className={`mt-0.5 p-1.5 rounded-lg transition-all ${model === opt.id ? 'text-blue-600 bg-blue-50 dark:bg-blue-900/30' : 'text-slate-400'}`}>
                      {opt.icon}
                    </div>
                    <div className="flex-1">
                      <div className="flex items-center gap-2">
                        <span className={`text-[13px] font-bold tracking-tight ${model === opt.id ? 'text-slate-900 dark:text-white' : 'text-slate-600 dark:text-slate-400'}`}>{opt.label}</span>
                        {opt.tag && <span className="px-1.5 py-0.5 rounded text-[7px] font-black uppercase tracking-wider bg-slate-200 dark:bg-slate-700 text-slate-500">{opt.tag}</span>}
                      </div>
                      <p className="text-[10px] text-slate-500 dark:text-slate-500 font-medium leading-tight">{opt.desc}</p>
                    </div>
                 </button>
               ))}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

