      )}
      <aside className={`fixed lg:static inset-y-0 left-0 z-[70] transition-all duration-400 cubic-bezier(0.16, 1, 0.3, 1) h-full bg-white dark:bg-[#0b0f1a] border-r border-slate-100 dark:border-slate-800 flex flex-col
        ${isSidebarOpen ? 'translate-x-0 shadow-xl' : '-translate-x-full lg:translate-x-0'}
        ${isSidebarCollapsed ? 'w-0 lg:w-16 overflow-hidden' : 'w-[240px]'}
      `}>
        <div className={`p-4 flex flex-col h-full ${isSidebarCollapsed ? 'items-center px-1' : ''}`}>
           <div className={`flex items-center gap-2 mb-8 select-none group cursor-pointer px-2 ${isSidebarCollapsed ? 'justify-center' : ''}`} onClick={onNewChat}>
              <BotIcon className="w-6.5 h-6.5 shadow-sm rounded-full transition-all group-hover:scale-105" />
              {!isSidebarCollapsed && (
                <h2 className="text-xl font-semibold tracking-tight text-black dark:text-white leading-none">CognixAI</h2>
              )}
           </div>

           <div className="space-y-4 mb-8">
              <div>
                {!isSidebarCollapsed && <h3 className="text-[10px] font-semibold text-slate-400 uppercase tracking-widest px-2 mb-2">Workspace</h3>}
                <nav className="space-y-0.5">
                  <NavItem m="chat" icon={<SparklesIcon />} label="Conversations" />
                  <NavItem m="toolbox" icon={<svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth="2.5"><path d="M19.428 15.428a2 2 0 00-1.022-.547l-2.387-.477a6 6 0 00-3.86.517l-.628.288a2 2 0 01-1.647 0l-.628-.288a6 6 0 00-3.86-.517l-2.387.477a2 2 0 00-1.022.547V18.5a2 2 0 001.106 1.789l2.387 1.193a4 4 0 001.789.418h4.818a4 4 0 001.789-.418l2.387-1.193a2 2 0 001.106-1.789v-3.072zM4.5 9V5.25A2.25 2.25 0 016.75 3h10.5A2.25 2.25 0 0119.5 5.25V9"/></svg>} label="Toolbox" />
                  <NavItem m="community" icon={<UsersIcon />} label="Collective" />
                </nav>
              </div>
           </div>

           <button 
             onClick={() => { onNewChat(); if(window.innerWidth < 1024) onClose(); }}
             className={`w-full flex items-center justify-center gap-2 px-3 py-3 bg-slate-900 dark:bg-white text-white dark:text-black rounded-xl font-semibold text-[13px] transition-all active:scale-[0.98] hover:opacity-90 mb-6 shadow-sm ${isSidebarCollapsed ? 'px-0 w-11 mx-auto' : ''}`}
           >
             {isSidebarCollapsed ? <SparklesIcon className="w-4 h-4" /> : <span>New Chat</span>}
           </button>

           {!isSidebarCollapsed && (
             <div className="flex-1 flex flex-col min-h-0">
                <div className="flex items-center justify-between px-2 mb-3">
