                        >
                          <TrashIcon className="w-3.5 h-3.5" />
                        </button>
                      </div>
                    ))
                  )}
                </div>
             </div>
           )}

           <div className={`pt-4 border-t border-slate-100 dark:border-slate-800 mt-auto ${isSidebarCollapsed ? 'px-0' : ''}`}>
              {!isSidebarCollapsed ? (
                <div className="flex flex-col gap-2 p-3 rounded-xl bg-slate-50 dark:bg-slate-900/50">
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-2">
                      <div className="w-2 h-2 rounded-full bg-blue-500"></div>
                      <span className="text-[10px] font-semibold text-slate-500 uppercase tracking-wider">System Online</span>
                    </div>
                    <span className="text-[9px] font-semibold text-slate-400">V11.2</span>
                  </div>
                </div>
              ) : (
                <div className="flex justify-center">
                  <div className="w-2 h-2 rounded-full bg-blue-500"></div>
                </div>
              )}
           </div>
        </div>
      </aside>
    </>
  );
};

import React, { useState, useRef, useEffect, useCallback } from 'react';
import type { ChatMessage, ChatPart, ModelType, ChatSession, MemoryFact } from '../types';
import { GoogleGenAI } from "@google/genai";
import { SendIcon, ImageIcon, BotIcon, UserIcon, UsersIcon, SparklesIcon, BoltIcon, BrainIcon, CodeIcon } from './Icons';

interface ChatViewProps {
  messages: ChatMessage[];
  setMessages: React.Dispatch<React.SetStateAction<ChatMessage[]>>;
  systemInstruction: string;
  model: ModelType;
  setActiveModel: (m: ModelType) => void;
  participants: string[];
  onAddParticipant: (name: string) => void;
  currentChat?: ChatSession;
  isSidebarCollapsed?: boolean;
  memories?: MemoryFact[];
}

export const ChatView: React.FC<ChatViewProps> = ({ 
  messages, setMessages, systemInstruction, model, setActiveModel, participants, onAddParticipant, currentChat, isSidebarCollapsed, memories = []
}) => {
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isSearchEnabled, setIsSearchEnabled] = useState(false);
  const [selectedImage, setSelectedImage] = useState<{ data: string; mimeType: string } | null>(null);
  const [showModelMenu, setShowModelMenu] = useState(false);
  const [copiedLink, setCopiedLink] = useState(false);

  const containerRef = useRef<HTMLDivElement>(null);
  const fileRef = useRef<HTMLInputElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  const hasMessages = messages.length > 0;

  useEffect(() => {
    if (containerRef.current) {
      containerRef.current.scrollTop = containerRef.current.scrollHeight;
    }
  }, [messages, isLoading]);

  const handleSend = useCallback(async () => {
    const trimmedInput = input.trim();
    if ((!trimmedInput && !selectedImage) || isLoading) return;

    const parts: ChatPart[] = [];
    if (selectedImage) parts.push({ inlineData: { mimeType: selectedImage.mimeType, data: selectedImage.data } });
    if (trimmedInput) parts.push({ text: trimmedInput });

    const userMsg: ChatMessage = { id: Date.now().toString(), role: 'user', parts };
    const botMsgId = (Date.now() + 1).toString();
    const botPlaceholder: ChatMessage = { id: botMsgId, role: 'model', parts: [{ text: '' }], isSearching: isSearchEnabled };

    setMessages(prev => [...prev, userMsg, botPlaceholder]);
    setInput('');
    setSelectedImage(null);
    setIsLoading(true);

    if (textareaRef.current) { textareaRef.current.style.height = 'auto'; }

    try {
      const apiKey = process.env.API_KEY;
      if (!apiKey) throw new Error("API Key missing");
      const ai = new GoogleGenAI({ apiKey });

      const vaultContext = memories.length > 0 
        ? "\n\nCONTEXT FROM VAULT:\n" + memories.map(m => `- ${m.content}`).join('\n')
        : "";

      let modelInstruction = "";
      let targetModelId = "";

      // Model personality routing with strict plain-text instructions
      switch(model) {
        case 'cognix-rv2':
          targetModelId = 'gemini-3-flash-preview';
          modelInstruction = "Role: CognixAI. Tone: Helpful and concise. IMPORTANT: DO NOT USE BOLD SYMBOLS (*** or **). Use plain text. ";
          break;
        case 'clora-v1':
          targetModelId = 'gemini-3-pro-preview';
          modelInstruction = "Role: CloraV1. Tone: Deep reasoning. IMPORTANT: DO NOT USE BOLD SYMBOLS (*** or **). Use plain text. ";
          break;
        case 'clorea-v2.5':
          targetModelId = 'gemini-flash-lite-latest';
          modelInstruction = "Role: CloreaV2.5. Tone: Rapid assistant. IMPORTANT: DO NOT USE BOLD SYMBOLS (*** or **). Use plain text. ";
          break;
        case 'arctic-x':
          targetModelId = 'gemini-3-pro-preview';
          modelInstruction = "Role: ArcticX. Tone: Technical architect. IMPORTANT: DO NOT USE BOLD SYMBOLS (*** or **). Use plain text. ";
          break;
        default:
          targetModelId = 'gemini-3-flash-preview';
      }

      const finalInstruction = systemInstruction + vaultContext + "\n\n" + modelInstruction;

      if (/draw|image|generate an image|create an image|show me an image/i.test(trimmedInput)) {
        targetModelId = 'gemini-2.5-flash-image';
      }

      const history = messages.slice(-10).map(m => ({
        role: m.role,
        parts: m.parts.map(p => p.text ? { text: p.text } : { inlineData: p.inlineData })
      }));

      const res = await ai.models.generateContent({
        model: targetModelId,
        contents: [...history, { role: 'user', parts: parts as any }],
        config: { 
          systemInstruction: finalInstruction,
          tools: isSearchEnabled ? [{ googleSearch: {} }] : [] 
        }
      });

      const resParts: ChatPart[] = res.candidates?.[0]?.content?.parts.map(p => {
        if (p.text) return { text: p.text };
        if (p.inlineData) return { inlineData: { mimeType: p.inlineData.mimeType, data: p.inlineData.data } };
        return { text: "" };
      }).filter(p => p.text !== "" || p.inlineData) || [{ text: "No output generated." }];

      setMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, parts: resParts, isSearching: false } : m));
    } catch (e) {
      setMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, parts: [{ text: "Neural link timeout. Please retry." }], isSearching: false } : m));
    } finally {
      setIsLoading(false);
    }
  }, [input, selectedImage, isLoading, messages, systemInstruction, model, isSearchEnabled, setMessages, memories]);

  const modelOptions = [
    { id: 'cognix-rv2', label: 'CognixRv2', desc: 'Fast and reliable', icon: <BoltIcon className="w-5 h-5"/>, tag: 'Default' },
    { id: 'clora-v1', label: 'CloraV1', desc: 'Reasoning engine', icon: <SparklesIcon className="w-5 h-5"/>, tag: 'Pro' },
    { id: 'clorea-v2.5', label: 'CloreaV2.5', desc: 'Lightweight and fast', icon: <BrainIcon className="w-5 h-5"/>, tag: 'Lite' },
    { id: 'arctic-x', label: 'ArcticX', desc: 'Technical specialist', icon: <CodeIcon className="w-5 h-5"/>, tag: 'Dev' }
  ];

  const activeModelData = modelOptions.find(m => m.id === model) || modelOptions[0];

  return (
    <div className="h-full flex flex-col bg-white dark:bg-[#020617] relative overflow-hidden transition-colors duration-300">

      <div 
        ref={containerRef} 
        className={`flex-1 overflow-y-auto px-4 sm:px-6 md:px-12 lg:px-48 scroll-smooth transition-all custom-scrollbar ${
          hasMessages ? 'pb-40 pt-8' : 'flex flex-col items-center justify-center min-h-[80dvh] pb-48'
        }`}
      >
        {!hasMessages ? (
          <div className="w-full max-w-2xl mx-auto flex flex-col items-center animate-slide-up text-center select-none pointer-events-none">
             <h2 className="text-4xl sm:text-5xl font-semibold text-slate-900 dark:text-white tracking-tight mb-4 leading-tight">How can I help you?</h2>
             <p className="text-[12px] font-semibold uppercase tracking-[0.3em] text-slate-400">CognixAI Uplink Active</p>
          </div>
        ) : (
          <div className="max-w-4xl mx-auto space-y-8 w-full pb-10">
            {messages.map((m, idx) => (
              <div key={m.id} className={`flex gap-5 ${m.role === 'user' ? 'flex-row-reverse' : 'flex-row'} animate-slide-up`}>
                <div className={`w-10 h-10 shrink-0 rounded-xl flex items-center justify-center shadow-md border ${m.role === 'user' ? 'bg-slate-900 border-slate-900 text-white' : 'bg-slate-50 dark:bg-slate-800 border-slate-200 dark:border-slate-700'}`}>
                   {m.role === 'user' ? <UserIcon className="w-5 h-5"/> : <BotIcon className="w-full h-full p-2"/>}
                </div>
                <div className={`flex flex-col gap-2.5 max-w-[90%] sm:max-w-[88%] ${m.role === 'user' ? 'items-end' : 'items-start'}`}>
                  {m.parts.map((p, i) => (
                    <div key={i} className={`px-6 py-4 text-[17px] sm:text-[18px] font-medium leading-relaxed ${m.role === 'user' ? 'bg-slate-100 dark:bg-slate-800 text-slate-900 dark:text-slate-100 rounded-3xl rounded-tr-sm shadow-sm' : 'bg-transparent text-slate-900 dark:text-slate-100'}`}>
                      {p.inlineData && <img src={`data:${p.inlineData.mimeType};base64,${p.inlineData.data}`} className="max-h-[500px] w-full object-contain mb-5 rounded-2xl shadow-xl border dark:border-slate-700" alt="Output" />}
                      {p.text ? <div className="whitespace-pre-wrap">{p.text}</div> : (idx === messages.length - 1 && isLoading && m.role === 'model' && <div className="flex gap-2 py-3"><div className="w-2.5 h-2.5 bg-blue-500 rounded-full animate-bounce"></div><div className="w-2.5 h-2.5 bg-blue-500 rounded-full animate-bounce delay-100"></div><div className="w-2.5 h-2.5 bg-blue-500 rounded-full animate-bounce delay-200"></div></div>)}
                    </div>
                  ))}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      <div className={`fixed left-0 right-0 p-4 sm:p-6 z-[60] pointer-events-none transition-all duration-300 ${isSidebarCollapsed ? 'lg:pl-16' : 'lg:pl-[240px]'} ${hasMessages ? 'bottom-0' : 'bottom-12 sm:bottom-24'}`}>
        <div className="max-w-3xl mx-auto pointer-events-auto">
          <div className="relative bg-white dark:bg-[#0d111c] border border-slate-200 dark:border-slate-700 rounded-[2rem] p-3 sm:p-4 shadow-[0_20px_50px_-15px_rgba(0,0,0,0.2)] dark:shadow-[0_25px_60px_-15px_rgba(0,0,0,0.5)]">

            <div className="flex items-center gap-2 px-3 mb-3">
               <button onClick={() => setShowModelMenu(true)} className="flex items-center gap-2.5 py-2 px-4 text-slate-700 dark:text-slate-300 font-semibold text-[12px] uppercase tracking-wider hover:bg-slate-100 dark:hover:bg-slate-800 rounded-xl transition-all border border-slate-100 dark:border-slate-800 shadow-sm">
                  {activeModelData.icon} {activeModelData.label} <span className="text-slate-400 opacity-50">▾</span>
               </button>
               <button onClick={() => setIsSearchEnabled(!isSearchEnabled)} className={`flex items-center gap-2 py-2 px-4 text-[11px] font-semibold uppercase tracking-wider rounded-xl border transition-all ${isSearchEnabled ? 'bg-blue-50 dark:bg-blue-900/20 border-blue-200 dark:border-blue-800 text-blue-600' : 'bg-transparent border-transparent text-slate-400 hover:text-slate-600'}`}>
                  Live Search
               </button>
            </div>

            {selectedImage && <div className="px-3 pb-4 flex items-center gap-3 animate-fade-in"><div className="relative w-16 h-16 rounded-xl overflow-hidden border border-slate-200 dark:border-slate-700 shadow-md"><img src={`data:${selectedImage.mimeType};base64,${selectedImage.data}`} className="w-full h-full object-cover" /><button onClick={() => setSelectedImage(null)} className="absolute top-0 right-0 bg-red-600 text-white w-6 h-6 flex items-center justify-center rounded-bl-lg text-[12px] font-bold shadow-sm">×</button></div></div>}

            <div className="flex items-center gap-2.5">
                <button onClick={() => fileRef.current?.click()} className="w-12 h-12 shrink-0 flex items-center justify-center text-slate-400 hover:text-slate-900 dark:hover:text-white rounded-2xl transition-all hover:bg-slate-50 dark:hover:bg-slate-800"><ImageIcon className="w-6 h-6" /><input type="file" ref={fileRef} className="hidden" accept="image/*" onChange={(e) => { const f = e.target.files?.[0]; if (f) { const r = new FileReader(); r.onloadend = () => setSelectedImage({ data: (r.result as string).split(',')[1], mimeType: f.type }); r.readAsDataURL(f); } }} /></button>
                <textarea ref={textareaRef} value={input} onChange={e => { setInput(e.target.value); e.target.style.height = 'auto'; e.target.style.height = Math.min(e.target.scrollHeight, 200) + 'px'; }} onKeyDown={e => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSend())} placeholder="Message Cognix..." className="flex-1 bg-transparent border-none outline-none resize-none py-3 text-[17px] sm:text-[18px] text-slate-900 dark:text-white placeholder-slate-400 font-medium max-h-[200px] min-h-[52px] custom-scrollbar leading-relaxed" rows={1} />
                <button onClick={handleSend} disabled={isLoading || (!input.trim() && !selectedImage)} className="w-12 h-12 bg-slate-900 dark:bg-white text-white dark:text-black rounded-full flex items-center justify-center shadow-lg disabled:opacity-20 active:scale-90 transition-all"><SendIcon className="w-6 h-6" /></button>
            </div>
          </div>
        </div>
      </div>

      {showModelMenu && (
        <div className="fixed inset-0 bg-black/40 backdrop-blur-md z-[100] flex items-end sm:items-center justify-center p-0 sm:p-4" onClick={() => setShowModelMenu(false)}>
          <div className="bg-white dark:bg-[#0f172a] w-full max-w-[380px] rounded-t-[2.5rem] sm:rounded-3xl p-4 shadow-2xl animate-slide-up border border-slate-200 dark:border-slate-800" onClick={e => e.stopPropagation()}>
            <div className="flex flex-col gap-2">
               <h3 className="px-3 py-2 text-[10px] font-bold text-slate-400 uppercase tracking-[0.2em] mb-1">Select Engine</h3>
               {modelOptions.map((opt) => (
                 <button 
                  key={opt.id} 
                  onClick={() => { setActiveModel(opt.id as ModelType); setShowModelMenu(false); }} 
                  className={`w-full flex items-start gap-4 p-4 rounded-2xl transition-all text-left group ${model === opt.id ? 'bg-slate-100 dark:bg-slate-800 shadow-sm' : 'hover:bg-slate-50 dark:hover:bg-slate-800/40'}`}
                 >
                    <div className={`mt-0.5 p-2.5 rounded-xl transition-all ${model === opt.id ? 'text-blue-600 bg-blue-50 dark:bg-blue-900/30' : 'text-slate-400'}`}>
                      {opt.icon}
                    </div>
                    <div className="flex-1">
                      <div className="flex items-center gap-2">
                        <span className={`text-[15px] font-semibold tracking-tight ${model === opt.id ? 'text-slate-900 dark:text-white' : 'text-slate-600 dark:text-slate-400'}`}>{opt.label}</span>
                        {opt.tag && <span className="px-2 py-0.5 rounded-md text-[9px] font-semibold uppercase tracking-wider bg-slate-200 dark:bg-slate-700 text-slate-500">{opt.tag}</span>}
                      </div>
                      <p className="text-[12px] text-slate-500 dark:text-slate-500 font-medium leading-snug mt-0.5">{opt.desc}</p>
                    </div>
                 </button>
               ))}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { ChatView } from './components/ChatView';
import { LiveView } from './components/LiveView';
import { Sidebar } from './components/Sidebar';
import { CommunityView } from './components/CommunityView';
import { ToolboxView } from './components/ToolboxView';
import { MenuIcon, BotIcon, UserIcon, MicrophoneIcon } from './components/Icons';
import { SettingsModal } from './components/SettingsModal';
import type { ChatMessage, ChatSession, Mode, ThemeColors, ModelType, MemoryFact } from './types';

const THEME: ThemeColors = {
    primary: 'bg-black dark:bg-white',
    primaryHover: 'hover:opacity-90',
    text: 'text-black dark:text-white',
    textDark: 'text-white dark:text-black',
    bgSoft: 'bg-slate-50',
    darkBgSoft: 'dark:bg-slate-900',
    border: 'border-slate-200 dark:border-slate-800',
    ring: 'focus:ring-black dark:focus:ring-white',
    gradient: 'bg-black dark:bg-white'
};

const App: React.FC = () => {
  const [mode, setMode] = useState<Mode>('chat');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [activeModel, setActiveModel] = useState<ModelType>('cognix-rv2');
  const [systemInstruction, setSystemInstruction] = useState("I am CognixAI, an assistant created by Shashwat Ranjan Jha. IMPORTANT: Do not use bold markdown symbols like '***' or '**'. Use plain text for everything. Avoid fancy formatting.");
  const [deploymentHtml, setDeploymentHtml] = useState<string | null>(null);

  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [chatHistory, setChatHistory] = useState<ChatSession[]>([]);
  const [activeChatId, setActiveChatId] = useState<string | null>(null);
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [memories, setMemories] = useState<MemoryFact[]>([]);

  const currentChat = useMemo(() => chatHistory.find(c => c.id === activeChatId), [chatHistory, activeChatId]);

  useEffect(() => {
    const savedHistory = localStorage.getItem('cognix_v8_history');
    if (savedHistory) setChatHistory(JSON.parse(savedHistory));

    const savedVault = localStorage.getItem('nexzi_vault');
    if (savedVault) setMemories(JSON.parse(savedVault));

    const themeSaved = localStorage.getItem('cognix_theme');
    if (themeSaved === 'dark') {
      setIsDarkMode(true);
      document.documentElement.classList.add('dark');
    }

    const params = new URLSearchParams(window.location.search);

    const handshake = params.get('handshake');
    if (handshake) {
      try {
        const decodedStr = decodeURIComponent(escape(atob(handshake)));
        const decoded = JSON.parse(decodedStr);
        const newId = 'collective-' + Date.now();
        const sharedChat: ChatSession = {
          id: newId,
          title: decoded.title || 'Shared Pulse',
          messages: decoded.messages || [],
          participants: ['You', 'Handshake Node']
        };
        setChatHistory(prev => [sharedChat, ...prev]);
        setActiveChatId(newId);
        setMode('chat');
      } catch (e) { console.error("Neural link handshake failed", e); }
    }

    const deployment = params.get('deployment');
    if (deployment) {
      try {
        const decoded = decodeURIComponent(escape(atob(deployment)));
        setDeploymentHtml(decoded);
      } catch (e) { console.error("Deployment asset failed to load", e); }
    }

    if (handshake || deployment) {
      window.history.replaceState({}, document.title, window.location.pathname);
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('cognix_v8_history', JSON.stringify(chatHistory));
  }, [chatHistory]);

  useEffect(() => {
    localStorage.setItem('nexzi_vault', JSON.stringify(memories));
  }, [memories]);

  useEffect(() => { 
    setMessages(currentChat ? currentChat.messages : []); 
  }, [currentChat?.id]);

  const handleUpdateMessages = (updater: (prev: ChatMessage[]) => ChatMessage[]) => {
    setMessages(prev => {
      const next = updater(prev);
      if (activeChatId) {
        setChatHistory(h => h.map(c => c.id === activeChatId ? { ...c, messages: next } : c));
      } else if (next.length > 0) {
        const newId = Date.now().toString();
        const firstUserMsg = next.find(m => m.role === 'user');
        const titleText = firstUserMsg?.parts.find(p => p.text)?.text;
        const title = titleText ? titleText.slice(0, 40) : 'New Pulse';
        setChatHistory([{ id: newId, title: title || 'New Pulse', messages: next, participants: ['You'] }, ...chatHistory]);
        setActiveChatId(newId);
      }
      return next;
    });
  };

  const handleNewChat = () => {
    setActiveChatId(null);
    setMessages([]);
    setMode('chat');
  };

  const toggleDarkMode = (dark: boolean) => {
    setIsDarkMode(dark);
    if (dark) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('cognix_theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('cognix_theme', 'light');
    }
  };

  return (
    <div className="h-full w-full flex bg-white dark:bg-slate-950 transition-colors duration-500 overflow-hidden font-sans">
      {deploymentHtml ? (
        <div className="fixed inset-0 z-[1000] bg-white dark:bg-black">
          <div className="absolute top-6 right-6 z-[1001]">
            <button onClick={() => setDeploymentHtml(null)} className="px-6 py-3 bg-black text-white dark:bg-white dark:text-black rounded-2xl font-semibold text-[10px] uppercase shadow-2xl transition-all active:scale-95">De-Infect Preview</button>
          </div>
          <iframe srcDoc={deploymentHtml} className="w-full h-full border-none" />
        </div>
      ) : null}

      <Sidebar 
        chatHistory={chatHistory} 
        activeChatId={activeChatId} 
        mode={mode}
        onSetMode={setMode}
        onSelectChat={(id) => { setActiveChatId(id); setMode('chat'); }}
        onNewChat={handleNewChat}
        onDeleteChat={(id) => { 
          setChatHistory(h => h.filter(c => c.id !== id)); 
          if(activeChatId === id) handleNewChat(); 
        }}
        isSidebarOpen={isSidebarOpen}
        isSidebarCollapsed={isSidebarCollapsed}
        onToggleCollapse={() => setIsSidebarCollapsed(!isSidebarCollapsed)}
        onClose={() => setIsSidebarOpen(false)}
      />

      <div className={`flex-1 flex flex-col h-full relative overflow-hidden transition-all duration-300 ${isSidebarCollapsed ? 'lg:pl-0' : ''}`}>
        <header className="h-16 sm:h-20 flex items-center justify-between px-6 sm:px-10 z-50 bg-white/80 dark:bg-slate-900/80 backdrop-blur-2xl border-b border-slate-100 dark:border-slate-800 transition-colors">
          <div className="flex items-center gap-5">
            <button onClick={() => {
              if (window.innerWidth < 1024) setIsSidebarOpen(true);
              else setIsSidebarCollapsed(!isSidebarCollapsed);
            }} className="p-2.5 -ml-2 text-slate-900 dark:text-white transition-all hover:bg-slate-100 dark:hover:bg-slate-800 rounded-xl active:scale-90">
              <MenuIcon className="w-6 h-6"/>
            </button>
            <div className="flex items-center gap-4">
              <BotIcon className="w-9 h-9 cursor-pointer transition-transform hover:scale-105" onClick={handleNewChat} />
              <div className="flex flex-col">
                <span className="text-[16px] font-semibold text-slate-900 dark:text-white tracking-tight uppercase leading-none">CognixAI</span>
                <span className="text-[9px] font-semibold text-slate-400 uppercase tracking-widest leading-none mt-1">{mode.toUpperCase()} MODE</span>
              </div>
            </div>
          </div>

          <div className="flex items-center gap-4">
            <button 
              onClick={() => setMode(mode === 'live' ? 'chat' : 'live')}
              className={`w-10 h-10 flex items-center justify-center rounded-xl transition-all shadow-sm border ${mode === 'live' ? 'bg-black text-white dark:bg-white dark:text-black border-black dark:border-white animate-pulse' : 'bg-slate-50 dark:bg-slate-800/50 text-slate-400 border-slate-200 dark:border-slate-700 hover:text-black dark:hover:text-white'}`}
              title="Voice Protocol"
            >
              <MicrophoneIcon className="w-5 h-5" />
            </button>
            <button 
              onClick={() => setIsSettingsOpen(true)}
              className="w-10 h-10 flex items-center justify-center bg-slate-50 dark:bg-slate-800/50 rounded-xl text-slate-400 hover:text-black dark:hover:text-white transition-all shadow-sm border border-slate-200 dark:border-slate-700"
            >
              <UserIcon className="w-5 h-5" />
            </button>
          </div>
        </header>

        <main className="flex-1 relative overflow-hidden h-full">
           {mode === 'chat' && (
              <ChatView 
                messages={messages} 
                setMessages={(val) => {
                  if (typeof val === 'function') handleUpdateMessages(val as any);
                  else handleUpdateMessages(() => val as any);
                }} 
                systemInstruction={systemInstruction} 
                model={activeModel} 
                setActiveModel={setActiveModel} 
                participants={['You']}
                onAddParticipant={() => {}}
                currentChat={currentChat}
                isSidebarCollapsed={isSidebarCollapsed}
                memories={memories}
              />
           )}
           {mode === 'live' && <LiveView />}
           {mode === 'toolbox' && <ToolboxView theme={THEME} model={activeModel} />}
           {mode === 'community' && <CommunityView theme={THEME} model={activeModel} />}
        </main>
      </div>

      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)} 
        isDarkMode={isDarkMode}
        setIsDarkMode={toggleDarkMode}
        systemInstruction={systemInstruction} 
        setSystemInstruction={setSystemInstruction}
        memories={memories}
        setMemories={setMemories}
        onClearHistory={() => { 
          setChatHistory([]); 
          setMessages([]); 
          setActiveChatId(null); 
          setIsSettingsOpen(false); 
          localStorage.removeItem('cognix_v8_history');
        }}
      />
    </div>
  );
}

export default App;

import React from 'react';
import type { ChatSession, Mode } from '../types';
import { BotIcon, TrashIcon, SparklesIcon, UsersIcon } from './Icons';

interface SidebarProps {
  chatHistory: ChatSession[];
  activeChatId: string | null;
  mode: Mode;
  onSetMode: (mode: Mode) => void;
  onSelectChat: (id: string) => void;
  onNewChat: () => void;
  onDeleteChat: (id: string) => void;
  isSidebarOpen: boolean;
  isSidebarCollapsed: boolean;
  onToggleCollapse: () => void;
  onClose: () => void;
}

