          `}
      >
          <span className={`shrink-0 transition-transform ${isActive ? 'scale-100' : 'group-hover:scale-105 opacity-70 group-hover:opacity-100'}`}>
            {React.isValidElement(icon) ? React.cloneElement(icon as React.ReactElement<any>, { className: 'w-5 h-5' }) : icon}
          </span>
          {!isSidebarCollapsed && <span className="text-[15px] font-medium tracking-tight">{label}</span>}
      </button>
    );
  };

  return (
    <>
      {isSidebarOpen && (
        <div className="fixed inset-0 bg-black/10 backdrop-blur-sm z-[60] lg:hidden transition-opacity duration-300" onClick={onClose} />
      )}
      <aside className={`fixed lg:static inset-y-0 left-0 z-[70] transition-all duration-400 cubic-bezier(0.16, 1, 0.3, 1) h-full bg-white dark:bg-[#0b0f1a] border-r border-slate-100 dark:border-slate-800 flex flex-col
        ${isSidebarOpen ? 'translate-x-0 shadow-xl' : '-translate-x-full lg:translate-x-0'}
        ${isSidebarCollapsed ? 'w-0 lg:w-16 overflow-hidden' : 'w-[280px]'}
