        <div className={`p-5 flex flex-col h-full ${isSidebarCollapsed ? 'items-center px-1' : ''}`}>
           <div className={`flex items-center gap-3 mb-10 select-none group cursor-pointer px-2 ${isSidebarCollapsed ? 'justify-center' : ''}`} onClick={onNewChat}>
              <BotIcon className="w-8 h-8 shadow-md rounded-2xl transition-all group-hover:scale-105" />
              {!isSidebarCollapsed && (
                <h2 className="text-2xl font-semibold tracking-tight text-black dark:text-white leading-none">CognixAI</h2>
