                <nav className="space-y-1">
                  <NavItem m="chat" icon={<SparklesIcon />} label="Conversations" />
                  <NavItem m="toolbox" icon={<svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth="2.5"><path d="M19.428 15.428a2 2 0 00-1.022-.547l-2.387-.477a6 6 0 00-3.86.517l-.628.288a2 2 0 01-1.647 0l-.628-.288a6 6 0 00-3.86-.517l-2.387.477a2 2 0 00-1.022.547V18.5a2 2 0 001.106 1.789l2.387 1.193a4 4 0 001.789.418h4.818a4 4 0 001.789-.418l2.387-1.193a2 2 0 001.106-1.789v-3.072zM4.5 9V5.25A2.25 2.25 0 016.75 3h10.5A2.25 2.25 0 0119.5 5.25V9"/></svg>} label="Toolbox" />
                  <NavItem m="community" icon={<UsersIcon />} label="Collective" />
                </nav>
              </div>
           </div>

           <button 
             onClick={() => { onNewChat(); if(window.innerWidth < 1024) onClose(); }}
             className={`w-full flex items-center justify-center gap-3 px-4 py-3.5 bg-slate-900 dark:bg-white text-white dark:text-black rounded-2xl font-semibold text-[14px] transition-all active:scale-[0.98] hover:opacity-90 mb-8 shadow-md ${isSidebarCollapsed ? 'px-0 w-12 mx-auto' : ''}`}
