             {isSidebarCollapsed ? <SparklesIcon className="w-5 h-5" /> : <span>New Chat</span>}
           </button>

           {!isSidebarCollapsed && (
             <div className="flex-1 flex flex-col min-h-0">
                <div className="flex items-center justify-between px-3 mb-4">
                  <h3 className="text-[11px] font-semibold text-slate-400 uppercase tracking-widest">Recent Activity</h3>
