                <div className="flex-1 overflow-y-auto space-y-1 pr-1 -mr-1 scrollbar-hide pb-8">
                  {chatHistory.length === 0 ? (
                    <div className="px-5 py-10 text-center border border-dashed border-slate-100 dark:border-slate-800 rounded-2xl">
                      <p className="text-[12px] text-slate-400 font-medium">History empty</p>
                    </div>
                  ) : (
                    chatHistory.map((chat) => (
                      <div key={chat.id} className="group relative">
                        <button 
                          onClick={() => { onSelectChat(chat.id); onSetMode('chat'); if(window.innerWidth < 1024) onClose(); }}
                          className={`w-full text-left px-4 py-3 rounded-xl transition-all flex items-center justify-between
                            ${activeChatId === chat.id && mode === 'chat' 
                              ? 'bg-slate-50 dark:bg-slate-800/80 text-black dark:text-white font-semibold' 
                              : 'text-slate-500 hover:text-black dark:hover:text-white hover:bg-slate-50/50 dark:hover:bg-slate-800/20'}
                          `}
                        >
                          <span className="text-[14px] truncate w-full tracking-tight font-medium">{chat.title}</span>
                        </button>
                        <button 
                          onClick={(e) => { e.stopPropagation(); onDeleteChat(chat.id); }}
                          className="absolute right-2 top-1/2 -translate-y-1/2 p-2 opacity-0 group-hover:opacity-100 text-slate-400 hover:text-red-500 transition-all"
                        >
                          <TrashIcon className="w-4 h-4" />
                        </button>
                      </div>
                    ))
                  )}
                </div>
             </div>
           )}

           <div className={`pt-5 border-t border-slate-100 dark:border-slate-800 mt-auto ${isSidebarCollapsed ? 'px-0' : ''}`}>
              {!isSidebarCollapsed ? (
                <div className="flex flex-col gap-2.5 p-4 rounded-2xl bg-slate-50 dark:bg-slate-900/50">
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-2.5">
                      <div className="w-2.5 h-2.5 rounded-full bg-blue-500 animate-pulse"></div>
                      <span className="text-[11px] font-semibold text-slate-500 uppercase tracking-widest">System Online</span>
                    </div>
                    <span className="text-[10px] font-semibold text-slate-400">V11.2</span>
                  </div>
                </div>
              ) : (
                <div className="flex justify-center">
                  <div className="w-2.5 h-2.5 rounded-full bg-blue-500"></div>
                </div>
              )}
           </div>
        </div>
      </aside>
    </>
  );
};

