                         <button onClick={() => setTab('profile')} className={`flex-1 py-2 px-3 rounded-lg text-[10px] font-bold uppercase tracking-widest transition-all ${tab === 'profile' ? 'bg-white dark:bg-slate-800 text-black dark:text-white shadow-sm' : 'text-slate-500'}`}>Profile</button>
                    </div>
                    <button onClick={onClose} className="p-2 text-slate-400 hover:text-black dark:hover:text-white transition-all text-2xl leading-none">&times;</button>
                </div>

                <div className="p-6 space-y-8 overflow-y-auto max-h-[70vh] custom-scrollbar">
                    {tab === 'prefs' && (
                        <>
                            <section>
                                <div className="flex items-center gap-2 mb-4">
                                    <BoltIcon className="w-4 h-4 text-slate-400" />
                                    <h3 className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Interface Mode</h3>
                                </div>
                                <div className="flex gap-2">
                                    <button onClick={() => setIsDarkMode(false)} className={`flex-1 py-3 px-4 rounded-xl border transition-all text-xs font-bold ${!isDarkMode ? 'border-black dark:border-white bg-black dark:bg-white text-white dark:text-black shadow-lg' : 'border-slate-100 dark:border-slate-800 text-slate-500'}`}>Light</button>
                                    <button onClick={() => setIsDarkMode(true)} className={`flex-1 py-3 px-4 rounded-xl border transition-all text-xs font-bold ${isDarkMode ? 'border-white bg-white text-black shadow-lg' : 'border-slate-100 dark:border-slate-800 text-slate-500'}`}>Dark</button>
                                </div>
                            </section>

                            <section>
                                <div className="flex items-center gap-2 mb-4">
                                    <PencilIcon className="w-4 h-4 text-slate-400" />
                                    <h3 className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Global Directives</h3>
                                </div>
                                <textarea 
                                    value={systemInstruction}
                                    onChange={(e) => setSystemInstruction(e.target.value)}
                                    className="w-full p-4 bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 rounded-2xl text-sm text-black dark:text-white outline-none min-h-[140px] resize-none font-medium leading-relaxed focus:border-blue-500 transition-all"
                                    placeholder="Set persistent system prompt..."
                                />
                                <p className="text-[10px] text-slate-400 mt-2 font-medium">These instructions persist across all neural models.</p>
                            </section>

                            <section className="pt-4 flex items-center justify-between border-t border-slate-100 dark:border-slate-900">
                                 <button onClick={onClearHistory} className="flex items-center gap-2 text-red-600 text-[10px] font-bold uppercase tracking-widest hover:bg-red-50 dark:hover:bg-red-950/20 px-4 py-2 rounded-xl transition-all">
                                     <TrashIcon className="w-4 h-4"/> Purge Neural State
                                 </button>
                                 <span className="text-[10px] font-bold text-slate-400">Node v11.2 (BETA)</span>
                            </section>
                        </>
                    )}

                    {tab === 'vault' && (
                        <div className="space-y-6">
                            <header className="flex items-center justify-between">
                                <div className="flex items-center gap-2">
                                    <BrainIcon className="w-4 h-4 text-slate-400" />
                                    <h3 className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Neural Memory Vault</h3>
                                </div>
                                <button 
                                    onClick={() => {
                                        const fact = prompt("Input new persistent data fragment:");
                                        if (fact) setMemories([{ id: Date.now().toString(), content: fact, category: 'personal', timestamp: new Date().toLocaleDateString() }, ...memories]);
                                    }}
                                    className="text-[10px] font-bold text-black dark:text-white bg-slate-100 dark:bg-slate-800 px-4 py-2 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-200 transition-all"
                                >
                                    + Memorize Fact
                                </button>
                            </header>

                            <div className="space-y-3">
                                {memories.length === 0 ? (
                                    <div className="text-center py-16 border-2 border-dashed border-slate-100 dark:border-slate-800 rounded-3xl">
                                        <SparklesIcon className="w-8 h-8 text-slate-200 dark:text-slate-800 mx-auto mb-3" />
                                        <p className="text-xs font-bold uppercase tracking-widest text-slate-300">Memory sectors are empty</p>
                                    </div>
                                ) : (
                                    memories.map(m => (
                                        <div key={m.id} className="p-4 bg-slate-50 dark:bg-slate-900 rounded-2xl border border-slate-200 dark:border-slate-800 group relative transition-all hover:border-slate-400">
                                            {editingId === m.id ? (
                                                <input 
                                                    autoFocus
                                                    defaultValue={m.content}
                                                    onBlur={(e) => {
                                                        setMemories(prev => prev.map(fact => fact.id === m.id ? { ...fact, content: e.target.value } : fact));
                                                        setEditingId(null);
                                                    }}
                                                    className="w-full bg-transparent text-sm font-medium outline-none text-black dark:text-white"
                                                />
                                            ) : (
                                                <p className="text-sm font-medium pr-12 text-slate-800 dark:text-slate-200 leading-relaxed">{m.content}</p>
                                            )}
                                            <div className="absolute right-3 top-1/2 -translate-y-1/2 flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                                <button onClick={() => setEditingId(m.id)} className="p-2 text-slate-400 hover:text-black dark:hover:text-white"><PencilIcon className="w-4 h-4"/></button>
                                                <button onClick={() => setMemories(prev => prev.filter(f => f.id !== m.id))} className="p-2 text-slate-400 hover:text-red-600"><TrashIcon className="w-4 h-4"/></button>
                                            </div>
                                        </div>
                                    ))
                                )}
                            </div>
                        </div>
                    )}

                    {tab === 'profile' && (
                        <div className="space-y-6">
                            <div className="flex items-center gap-3 mb-6 p-4 bg-slate-50 dark:bg-slate-900 rounded-3xl border border-slate-100 dark:border-slate-800">
                                <div className="w-14 h-14 rounded-2xl bg-blue-600 flex items-center justify-center text-white text-xl font-bold shadow-lg">
                                    {profile.fullName[0]}
                                </div>
                                <div>
                                    <h4 className="text-base font-bold text-slate-900 dark:text-white">{profile.fullName}</h4>
                                    <p className="text-[10px] font-bold text-blue-500 uppercase tracking-widest">{profile.neuralLinkID}</p>
                                </div>
                            </div>

                            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                                <ProfileField label="Full Name" value={profile.fullName} onChange={(v) => handleProfileChange('fullName', v)} />
                                <ProfileField label="Link ID" value={profile.neuralLinkID} onChange={(v) => handleProfileChange('neuralLinkID', v)} />
                                <ProfileField label="Profession" value={profile.profession} onChange={(v) => handleProfileChange('profession', v)} />
                                <ProfileSelect label="Logic Style" value={profile.logicStyle} options={['Analytic', 'Creative']} onChange={(v) => handleProfileChange('logicStyle', v as any)} />
                                <ProfileSelect label="Verbal Density" value={profile.verbalDensity} options={['Concise', 'Detailed']} onChange={(v) => handleProfileChange('verbalDensity', v as any)} />
                                <ProfileField label="Primary Language" value={profile.primaryLanguage} onChange={(v) => handleProfileChange('primaryLanguage', v)} />
                                <ProfileField label="Sync Timezone" value={profile.timezone} onChange={(v) => handleProfileChange('timezone', v)} />
                                <ProfileSelect label="Ethics Protocol" value={profile.ethicsLevel} options={['Standard', 'Strict', 'Dynamic']} onChange={(v) => handleProfileChange('ethicsLevel', v as any)} />
                                <ProfileSelect label="Input Protocol" value={profile.interactionProtocol} options={['Text Only', 'Hybrid', 'Voice Priority']} onChange={(v) => handleProfileChange('interactionProtocol', v as any)} />
                                <ProfileField label="UI Accent" value={profile.accentColor} onChange={(v) => handleProfileChange('accentColor', v)} />
                            </div>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

const ProfileField: React.FC<{ label: string, value: string, onChange: (v: string) => void }> = ({ label, value, onChange }) => (
