import React, { useState, useRef, useEffect, useCallback } from 'react';
import type { ChatMessage, ChatPart, ModelType, ChatSession, MemoryFact } from '../types';
import { GoogleGenAI } from "@google/genai";
import { SendIcon, AttachmentPlusIcon, BotIcon, UserIcon, SparklesIcon, BoltIcon, BrainIcon, CodeIcon } from './Icons';

interface ChatViewProps {
  messages: ChatMessage[];
  setMessages: React.Dispatch<React.SetStateAction<ChatMessage[]>>;
  systemInstruction: string;
  model: ModelType;
  setActiveModel: (m: ModelType) => void;
  participants: string[];
  onAddParticipant: (name: string) => void;
  currentChat?: ChatSession;
  isSidebarCollapsed?: boolean;
  memories?: MemoryFact[];
}

export const ChatView: React.FC<ChatViewProps> = ({ 
  messages, setMessages, systemInstruction, model, setActiveModel, participants, onAddParticipant, currentChat, isSidebarCollapsed, memories = []
}) => {
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isSearchEnabled, setIsSearchEnabled] = useState(false);
  const [selectedImage, setSelectedImage] = useState<{ data: string; mimeType: string } | null>(null);
  const [showModelMenu, setShowModelMenu] = useState(false);
  const [copiedLink, setCopiedLink] = useState(false);

  const containerRef = useRef<HTMLDivElement>(null);
  const fileRef = useRef<HTMLInputElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  const hasMessages = messages.length > 0;

  useEffect(() => {
    if (containerRef.current) {
      containerRef.current.scrollTop = containerRef.current.scrollHeight;
    }
  }, [messages, isLoading]);

  const handleSend = useCallback(async () => {
    const trimmedInput = input.trim();
    if ((!trimmedInput && !selectedImage) || isLoading) return;

    const parts: ChatPart[] = [];
    if (selectedImage) parts.push({ inlineData: { mimeType: selectedImage.mimeType, data: selectedImage.data } });
    if (trimmedInput) parts.push({ text: trimmedInput });

    const userMsg: ChatMessage = { id: Date.now().toString(), role: 'user', parts };
    const botMsgId = (Date.now() + 1).toString();
    const botPlaceholder: ChatMessage = { id: botMsgId, role: 'model', parts: [{ text: '' }], isSearching: isSearchEnabled };

    setMessages(prev => [...prev, userMsg, botPlaceholder]);
    setInput('');
    setSelectedImage(null);
    setIsLoading(true);

    if (textareaRef.current) { textareaRef.current.style.height = 'auto'; }

    try {
      const apiKey = process.env.API_KEY;
      if (!apiKey) throw new Error("API Key missing");
      const ai = new GoogleGenAI({ apiKey });

      const vaultContext = memories.length > 0 
        ? "\n\nCONTEXT FROM VAULT:\n" + memories.map(m => `- ${m.content}`).join('\n')
        : "";

      let modelInstruction = "";
      let targetModelId = "";

      // Model personality routing with strict plain-text instructions
      switch(model) {
        case 'cognix-rv2':
          targetModelId = 'gemini-3-flash-preview';
          modelInstruction = "Role: CognixAi. Tone: Helpful, friendly, and concise. IMPORTANT: DO NOT USE BOLD SYMBOLS (*** or **). Use plain text. Use emojis in your output to be expressive. ";
          break;
        case 'clora-v1':
          targetModelId = 'gemini-3-pro-preview';
          modelInstruction = "Role: CloraV1. Tone: Deep reasoning. IMPORTANT: DO NOT USE BOLD SYMBOLS (*** or **). Use plain text. ";
          break;
        case 'clorea-v2.5':
          targetModelId = 'gemini-flash-lite-latest';
          modelInstruction = "Role: CloreaV2.5. Tone: Rapid assistant. IMPORTANT: DO NOT USE BOLD SYMBOLS (*** or **). Use plain text. ";
          break;
        case 'arctic-x':
          targetModelId = 'gemini-3-pro-preview';
          modelInstruction = "Role: ArcticX. Tone: Technical architect. IMPORTANT: DO NOT USE BOLD SYMBOLS (*** or **). Use plain text. ";
          break;
        default:
          targetModelId = 'gemini-3-flash-preview';
      }

      const finalInstruction = systemInstruction + vaultContext + "\n\n" + modelInstruction;

      if (/draw|image|generate an image|create an image|show me an image/i.test(trimmedInput)) {
        targetModelId = 'gemini-2.5-flash-image';
      }

      const history = messages.slice(-10).map(m => ({
        role: m.role,
        parts: m.parts.map(p => p.text ? { text: p.text } : { inlineData: p.inlineData })
      }));

      const res = await ai.models.generateContent({
        model: targetModelId,
        contents: [...history, { role: 'user', parts: parts as any }],
        config: { 
          systemInstruction: finalInstruction,
          tools: isSearchEnabled ? [{ googleSearch: {} }] : [] 
        }
      });

      const resParts: ChatPart[] = res.candidates?.[0]?.content?.parts.map(p => {
        if (p.text) return { text: p.text };
        if (p.inlineData) return { inlineData: { mimeType: p.inlineData.mimeType, data: p.inlineData.data } };
        return { text: "" };
      }).filter(p => p.text !== "" || p.inlineData) || [{ text: "No output generated." }];

      setMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, parts: resParts, isSearching: false } : m));
    } catch (e) {
      setMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, parts: [{ text: "Neural link timeout. Please retry." }], isSearching: false } : m));
    } finally {
      setIsLoading(false);
    }
  }, [input, selectedImage, isLoading, messages, systemInstruction, model, isSearchEnabled, setMessages, memories]);

  const modelOptions = [
    { id: 'cognix-rv2', label: 'CognixRv2', desc: 'Fast and reliable', icon: <BoltIcon className="w-4 h-4"/>, tag: 'Default' },
    { id: 'clora-v1', label: 'CloraV1', desc: 'Reasoning engine', icon: <SparklesIcon className="w-4 h-4"/>, tag: 'Pro' },
    { id: 'clorea-v2.5', label: 'CloreaV2.5', desc: 'Lightweight and fast', icon: <BrainIcon className="w-4 h-4"/>, tag: 'Lite' },
    { id: 'arctic-x', label: 'ArcticX', desc: 'Technical specialist', icon: <CodeIcon className="w-4 h-4"/>, tag: 'Dev' }
  ];

  const activeModelData = modelOptions.find(m => m.id === model) || modelOptions[0];

  return (
    <div className="h-full flex flex-col bg-white dark:bg-[#020617] relative overflow-hidden transition-colors duration-300">

      <div 
        ref={containerRef} 
        className={`flex-1 overflow-y-auto px-4 sm:px-6 md:px-12 lg:px-40 scroll-smooth transition-all custom-scrollbar ${
          hasMessages ? 'pb-32 pt-6' : 'flex flex-col items-center justify-center min-h-[80dvh] pb-48'
        }`}
      >
        {!hasMessages ? (
          <div className="w-full max-w-xl mx-auto flex flex-col items-center animate-slide-up text-center select-none pointer-events-none">
             <h2 className="text-3xl sm:text-4xl font-semibold text-slate-900 dark:text-white tracking-tight mb-3 leading-tight">How can I help you?</h2>
             <p className="text-[11px] font-semibold uppercase tracking-[0.2em] text-slate-400">CognixAi Uplink Active</p>
          </div>
        ) : (
          <div className="max-w-3xl mx-auto space-y-6 w-full pb-10">
            {messages.map((m, idx) => (
              <div key={m.id} className={`flex gap-4 ${m.role === 'user' ? 'flex-row-reverse' : 'flex-row'} animate-slide-up`}>
                <div className={`w-9 h-9 shrink-0 rounded-xl flex items-center justify-center shadow-sm border ${m.role === 'user' ? 'bg-slate-900 border-slate-900 text-white' : 'bg-slate-50 dark:bg-slate-800 border-slate-200 dark:border-slate-700'}`}>
                   {m.role === 'user' ? <UserIcon className="w-4 h-4"/> : <BotIcon className="w-full h-full p-1.5"/>}
                </div>
                <div className={`flex flex-col gap-1.5 max-w-[90%] sm:max-w-[85%] ${m.role === 'user' ? 'items-end' : 'items-start'}`}>
                  {m.parts.map((p, i) => (
                    <div key={i} className={`px-5 py-3 text-[15px] sm:text-[16px] font-medium leading-relaxed ${m.role === 'user' ? 'bg-slate-100 dark:bg-slate-800 text-slate-900 dark:text-slate-100 rounded-2xl rounded-tr-sm shadow-sm' : 'bg-transparent text-slate-900 dark:text-slate-100'}`}>
                      {p.inlineData && <img src={`data:${p.inlineData.mimeType};base64,${p.inlineData.data}`} className="max-h-[400px] w-full object-contain mb-3 rounded-xl shadow-lg border dark:border-slate-700" alt="Output" />}
                      {p.text ? <div className="whitespace-pre-wrap">{p.text}</div> : (idx === messages.length - 1 && isLoading && m.role === 'model' && <div className="flex gap-1.5 py-1.5"><div className="w-2 h-2 bg-blue-500 rounded-full animate-bounce"></div><div className="w-2 h-2 bg-blue-500 rounded-full animate-bounce delay-100"></div><div className="w-2 h-2 bg-blue-500 rounded-full animate-bounce delay-200"></div></div>)}
                    </div>
                  ))}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      <div className={`fixed left-0 right-0 p-3 sm:p-5 z-[60] pointer-events-none transition-all duration-300 ${isSidebarCollapsed ? 'lg:pl-16' : 'lg:pl-[240px]'} ${hasMessages ? 'bottom-0' : 'bottom-12 sm:bottom-24'}`}>
        <div className="max-w-2xl mx-auto pointer-events-auto">
          {/* Blue Strip Border Around Input Area */}
          <div className="relative bg-white dark:bg-[#0d111c] border-2 border-blue-500 rounded-[2.5rem] p-2 sm:p-2.5 shadow-[0_15px_40px_-10px_rgba(59,130,246,0.25)] dark:shadow-[0_20px_50px_-10px_rgba(0,0,0,0.5)] transition-shadow hover:shadow-[0_15px_40px_-5px_rgba(59,130,246,0.35)]">

            <div className="flex items-center gap-1.5 px-2 mb-1.5">
               <button onClick={() => setShowModelMenu(true)} className="flex items-center gap-2 py-1 px-3 text-slate-700 dark:text-slate-300 font-bold text-[10px] uppercase tracking-wider hover:bg-slate-100 dark:hover:bg-slate-800 rounded-lg transition-all border border-slate-100 dark:border-slate-800 shadow-sm">
                  {activeModelData.icon} {activeModelData.label} <span className="text-slate-400 opacity-50">▾</span>
               </button>
               <button onClick={() => setIsSearchEnabled(!isSearchEnabled)} className={`flex items-center gap-1.5 py-1 px-3 text-[9px] font-bold uppercase tracking-wider rounded-lg border transition-all ${isSearchEnabled ? 'bg-blue-50 dark:bg-blue-900/20 border-blue-200 dark:border-blue-800 text-blue-600' : 'bg-transparent border-transparent text-slate-400 hover:text-slate-600'}`}>
                  Live Search
               </button>
            </div>

            {selectedImage && <div className="px-2 pb-3 flex items-center gap-2 animate-fade-in"><div className="relative w-12 h-12 rounded-xl overflow-hidden border border-slate-200 dark:border-slate-700"><img src={`data:${selectedImage.mimeType};base64,${selectedImage.data}`} className="w-full h-full object-cover" /><button onClick={() => setSelectedImage(null)} className="absolute top-0 right-0 bg-red-600 text-white w-5 h-5 flex items-center justify-center rounded-bl-lg text-[10px] font-bold shadow-sm">×</button></div></div>}

            <div className="flex items-center gap-1.5">
                <button onClick={() => fileRef.current?.click()} className="w-10 h-10 shrink-0 flex items-center justify-center text-slate-400 hover:text-blue-500 rounded-2xl transition-all hover:bg-blue-50 dark:hover:bg-blue-900/20 group">
                    <AttachmentPlusIcon className="w-6 h-6 transition-transform group-hover:scale-110" />
                    <input type="file" ref={fileRef} className="hidden" accept="image/*" onChange={(e) => { const f = e.target.files?.[0]; if (f) { const r = new FileReader(); r.onloadend = () => setSelectedImage({ data: (r.result as string).split(',')[1], mimeType: f.type }); r.readAsDataURL(f); } }} />
                </button>
                <textarea ref={textareaRef} value={input} onChange={e => { setInput(e.target.value); e.target.style.height = 'auto'; e.target.style.height = Math.min(e.target.scrollHeight, 180) + 'px'; }} onKeyDown={e => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSend())} placeholder="Message CognixAi..." className="flex-1 bg-transparent border-none outline-none resize-none py-2 text-[15px] sm:text-[16px] text-slate-900 dark:text-white placeholder-slate-400 font-semibold max-h-[180px] min-h-[44px] custom-scrollbar leading-relaxed" rows={1} />
                <button onClick={handleSend} disabled={isLoading || (!input.trim() && !selectedImage)} className="w-10 h-10 bg-blue-600 text-white rounded-full flex items-center justify-center shadow-lg disabled:opacity-20 active:scale-95 transition-all"><SendIcon className="w-5 h-5" /></button>
            </div>
          </div>
        </div>
      </div>

      {showModelMenu && (
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm z-[100] flex items-end sm:items-center justify-center p-0 sm:p-4" onClick={() => setShowModelMenu(false)}>
          <div className="bg-white dark:bg-[#0f172a] w-full max-w-[340px] rounded-t-3xl sm:rounded-2xl p-3 shadow-2xl animate-slide-up border border-slate-200 dark:border-slate-800" onClick={e => e.stopPropagation()}>
            <div className="flex flex-col gap-1.5">
               {modelOptions.map((opt) => (
                 <button 
                  key={opt.id} 
                  onClick={() => { setActiveModel(opt.id as ModelType); setShowModelMenu(false); }} 
                  className={`w-full flex items-start gap-3.5 p-3.5 rounded-xl transition-all text-left group ${model === opt.id ? 'bg-slate-50 dark:bg-slate-800 shadow-sm' : 'hover:bg-slate-50 dark:hover:bg-slate-800/40'}`}
                 >
                    <div className={`mt-0.5 p-2 rounded-lg transition-all ${model === opt.id ? 'text-blue-600 bg-blue-50 dark:bg-blue-900/30' : 'text-slate-400'}`}>
                      {opt.icon}
                    </div>
                    <div className="flex-1">
                      <div className="flex items-center gap-2">
                        <span className={`text-[14px] font-bold tracking-tight ${model === opt.id ? 'text-slate-900 dark:text-white' : 'text-slate-600 dark:text-slate-400'}`}>{opt.label}</span>
                        {opt.tag && <span className="px-1.5 py-0.5 rounded text-[8px] font-bold uppercase tracking-wider bg-slate-200 dark:bg-slate-700 text-slate-500">{opt.tag}</span>}
                      </div>
                      <p className="text-[11px] text-slate-500 dark:text-slate-500 font-bold leading-tight">{opt.desc}</p>
                    </div>
                 </button>
               ))}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { GoogleGenAI } from "@google/genai";
import { CodeIcon, CopyIcon, ImageIcon, SparklesIcon, SendIcon, BoltIcon } from './Icons';
import type { ThemeColors, ModelType } from '../types';

export const ToolboxView: React.FC<{ theme: ThemeColors, model: ModelType }> = ({ theme, model }) => {
    const [activeTool, setActiveTool] = useState<'summarizer' | 'scanner' | 'writer' | 'enhancer' | 'dev'>('summarizer');
    const [input, setInput] = useState('');
    const [result, setResult] = useState('');
    const [loading, setLoading] = useState(false);
    const [viewMode, setViewMode] = useState<'preview' | 'code'>('preview');
    const [publishedUrl, setPublishedUrl] = useState<string | null>(null);
    const [selectedImage, setSelectedImage] = useState<{ data: string, mimeType: string } | null>(null);
    const [devLogs, setDevLogs] = useState<string[]>([]);
    const fileRef = useRef<HTMLInputElement>(null);

    const logActivity = (msg: string) => {
        setDevLogs(prev => [...prev.slice(-4), msg]);
    };

    const runTool = async () => {
        if (!input.trim() && !selectedImage) return;
        setLoading(true);
        if (activeTool !== 'dev') setResult('');
        setPublishedUrl(null);
        setDevLogs([]);

        try {
            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
            let instruction = "";
            // FIX: targetModelName is now a string to avoid type errors and use actual Gemini model strings.
            let targetModelName: string = "";

            // FIX: Map the model prop (ModelType) to the corresponding Google GenAI model string as per guidelines.
            switch(model) {
                case 'cognix-rv2': targetModelName = 'gemini-3-flash-preview'; break;
                case 'clora-v1': targetModelName = 'gemini-3-pro-preview'; break;
                case 'clorea-v2.5': targetModelName = 'gemini-flash-lite-latest'; break;
                case 'arctic-x': targetModelName = 'gemini-3-pro-preview'; break;
                case 'visualizer': targetModelName = 'gemini-2.5-flash-image'; break;
                default: targetModelName = 'gemini-3-flash-preview';
            }

            if (activeTool === 'dev') {
                logActivity("Initializing Neural Architecture...");
                setTimeout(() => logActivity("Analyzing UI Requirements..."), 1000);
                setTimeout(() => logActivity("Drafting Component Hierarchy..."), 2000);
                setTimeout(() => logActivity("Injecting Tailwind Stylings..."), 3500);
                setTimeout(() => logActivity("Optimizing Responsive Layout..."), 5000);
            }

            switch(activeTool) {
                case 'summarizer': instruction = "Summarize the following into elite bullet points."; break;
                // FIX: Setting targetModelName to a valid model string literal instead of using targetModel (which was typed as ModelType).
                case 'scanner': instruction = "Analyze this image in high detail."; targetModelName = 'gemini-3-flash-preview'; break;
                case 'writer': instruction = "Write professional engaging content."; break;
                case 'enhancer': instruction = "Engineer a high-fidelity prompt from this input."; break;
                case 'dev': instruction = "ACT AS A SENIOR FRONTEND ENGINEER. Build a modern, mobile-responsive single-file landing page using Tailwind CSS. OUTPUT RAW HTML ONLY starting with <!DOCTYPE html>. No commentary."; break;
            }

            const parts: any[] = [{ text: `${instruction}\n\nINPUT: "${input}"` }];
            if (selectedImage && activeTool === 'scanner') {
                parts.push({ inlineData: { data: selectedImage.data, mimeType: selectedImage.mimeType } });
            }

            const response = await ai.models.generateContent({
                model: targetModelName,
                contents: [{ parts }],
            });

            if (activeTool === 'dev') logActivity("Synthesis Complete. Assembler Finalized.");
            setResult(response.text || '');
        } catch (e) {
            setResult('Uplink failed. Try again.');
        } finally {
            setLoading(false);
        }
    };

    const handlePublish = () => {
        if (!result) return;
        try {
            const b64 = btoa(unescape(encodeURIComponent(result)));
            const url = `${window.location.origin}${window.location.pathname}?deployment=${b64}`;
            setPublishedUrl(url);
        } catch(e) { console.error("Publish failed", e); }
    };

    const tools = [
        { id: 'summarizer', label: 'Summarizer', desc: 'CONDENSER' },
        { id: 'scanner', label: 'Scanner', desc: 'VISION' },
        { id: 'writer', label: 'Writer', desc: 'CONTENT' },
        { id: 'enhancer', label: 'Enhancer', desc: 'PROMPT' },
        { id: 'dev', label: 'Dev Studio', desc: 'UI ARCHITECT' }
    ];

    if (activeTool === 'dev') {
        return (
            <div className="h-full bg-white dark:bg-[#020617] flex flex-col animate-fade-in overflow-hidden">
                <header className="px-6 py-4 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between">
                    <div className="flex items-center gap-4">
                        <button onClick={() => setActiveTool('summarizer')} className="text-xs font-bold text-slate-500 hover:text-black dark:hover:text-white uppercase tracking-widest transition-colors">← Back to Lab</button>
                        <h2 className="text-sm font-bold tracking-tight uppercase px-3 py-1 bg-black text-white dark:bg-white dark:text-black rounded-lg">Dev Studio Node</h2>
                    </div>
                    {result && (
                        <div className="flex bg-slate-100 dark:bg-slate-900 p-1 rounded-xl">
                            <button onClick={() => setViewMode('preview')} className={`px-4 py-1.5 rounded-lg text-[10px] font-bold uppercase transition-all ${viewMode === 'preview' ? 'bg-white dark:bg-slate-800 shadow-sm' : 'text-slate-500'}`}>Preview</button>
                            <button onClick={() => setViewMode('code')} className={`px-4 py-1.5 rounded-lg text-[10px] font-bold uppercase transition-all ${viewMode === 'code' ? 'bg-white dark:bg-slate-800 shadow-sm' : 'text-slate-500'}`}>See Code</button>
                        </div>
                    )}
                </header>

                <div className="flex-1 flex overflow-hidden">
                    <div className="w-full sm:w-[400px] border-r border-slate-100 dark:border-slate-800 flex flex-col p-6 space-y-4">
                        <textarea 
                            value={input}
                            onChange={(e) => setInput(e.target.value)}
                            placeholder="Describe your UI vision..."
                            className="flex-1 p-4 bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl text-sm font-medium outline-none resize-none focus:border-black dark:focus:border-white transition-all"
                        />

                        {loading && devLogs.length > 0 && (
                            <div className="bg-slate-50 dark:bg-slate-900/50 p-4 rounded-xl border border-slate-200 dark:border-slate-800 overflow-hidden">
                                <p className="text-[9px] font-bold uppercase tracking-widest text-slate-400 mb-2">Activity Feed</p>
                                <div className="space-y-1">
                                    {devLogs.map((log, i) => (
                                        <p key={i} className={`text-[10px] font-mono ${i === devLogs.length - 1 ? 'text-blue-500 font-bold' : 'text-slate-500 opacity-60'}`}>{`> ${log}`}</p>
                                    ))}
                                </div>
                            </div>
                        )}

                        <button 
                            onClick={runTool}
                            disabled={loading || !input.trim()}
                            className="w-full py-4 bg-black dark:bg-white text-white dark:text-black rounded-2xl font-bold text-[10px] uppercase tracking-[0.2em] shadow-lg active:scale-95 disabled:opacity-30 transition-all"
                        >
                            {loading ? 'Synthesizing...' : 'Build UI Asset'}
                        </button>
                    </div>

                    <div className="flex-1 bg-slate-50 dark:bg-[#01040a] relative flex flex-col overflow-hidden">
                        {!result ? (
                            <div className="flex-1 flex flex-col items-center justify-center text-slate-400 opacity-50">
                                <CodeIcon className="w-12 h-12 mb-4" />
                                <p className="text-xs font-bold uppercase tracking-widest">Architectural Node Ready</p>
                            </div>
                        ) : viewMode === 'preview' ? (
                            <div className="flex-1 flex flex-col">
                                <div className="flex items-center justify-between px-6 py-2 bg-white dark:bg-slate-900 border-b border-slate-200 dark:border-slate-800">
                                    <span className="text-[10px] font-bold uppercase tracking-widest text-slate-500">Live Workspace</span>
                                    <button onClick={handlePublish} className="text-[10px] font-bold text-blue-600 hover:text-blue-700 uppercase tracking-widest transition-colors">Publish Deployment</button>
                                </div>
                                {publishedUrl && (
                                    <div className="p-3 bg-blue-50 dark:bg-blue-900/20 border-b border-blue-200 dark:border-blue-800 flex items-center justify-between gap-4 animate-slide-up">
                                        <p className="text-[9px] font-mono truncate text-blue-800 dark:text-blue-300">DEPLOYED: {publishedUrl}</p>
                                        <button onClick={() => { navigator.clipboard.writeText(publishedUrl); setPublishedUrl(null); }} className="px-3 py-1 bg-blue-600 text-white rounded-lg text-[9px] font-bold uppercase hover:bg-blue-700 transition-colors">Copy Link</button>
                                    </div>
                                )}
                                <iframe srcDoc={result} className="flex-1 w-full border-none bg-white" title="UI Preview" />
                            </div>
                        ) : (
                            <div className="flex-1 p-6 overflow-hidden flex flex-col">
                                <div className="flex justify-between mb-4">
                                     <span className="text-[10px] font-bold uppercase tracking-widest text-slate-500">Raw Source</span>
                                     <button onClick={() => navigator.clipboard.writeText(result)} className="p-2 bg-white dark:bg-slate-800 rounded-lg border border-slate-200 dark:border-slate-700 hover:scale-105 transition-all active:scale-95"><CopyIcon className="w-4 h-4"/></button>
                                </div>
                                <pre className="flex-1 p-6 bg-slate-900 text-slate-100 rounded-2xl text-xs overflow-auto custom-scrollbar font-mono leading-relaxed">
                                    {result}
                                </pre>
                            </div>
                        )}
                    </div>
                </div>
            </div>
        );
    }

    return (
        <div className="h-full overflow-y-auto bg-white dark:bg-[#020617] p-4 sm:p-10 animate-fade-in custom-scrollbar">
            <div className="max-w-6xl mx-auto space-y-10 pb-20">
                <header className="flex flex-col sm:flex-row sm:items-end justify-between gap-4">
                    <div>
                        <h2 className="text-3xl font-bold text-black dark:text-white tracking-tight uppercase leading-none mb-2">Cognix Lab</h2>
                        <p className="text-slate-500 dark:text-slate-400 font-bold text-[11px] uppercase tracking-widest">Neural Prototyping Terminal</p>
                    </div>
                    {/* Visual Badge/Badge Visualization */}
                    <div className="flex items-center gap-2 px-4 py-2 bg-slate-100 dark:bg-slate-900 rounded-2xl border border-slate-200 dark:border-slate-800">
                        <div className="relative w-8 h-8">
                            <div className="absolute inset-0 bg-blue-500/20 rounded-full animate-ping"></div>
                            <div className="relative flex items-center justify-center w-full h-full bg-blue-600 rounded-xl shadow-lg shadow-blue-500/30">
                                <BoltIcon className="w-4 h-4 text-white" />
                            </div>
                        </div>
                        <div>
                            <p className="text-[10px] font-bold text-black dark:text-white uppercase leading-none">Lab Active</p>
                            <p className="text-[8px] font-bold text-blue-500 uppercase tracking-widest mt-1">Uplink 11.2</p>
                        </div>
                    </div>
                </header>

                <div className="grid grid-cols-2 md:grid-cols-5 gap-2">
                    {tools.map(tool => (
                        <button 
                            key={tool.id} 
                            onClick={() => { setActiveTool(tool.id as any); setResult(''); setInput(''); setSelectedImage(null); }}
                            className={`flex flex-col items-start gap-1 p-4 rounded-xl border-2 transition-all text-left
                                ${activeTool === tool.id 
                                    ? 'border-black bg-slate-50 dark:bg-slate-800 shadow-sm' 
                                    : 'bg-white dark:bg-slate-900 border-slate-100 dark:border-slate-800 hover:border-slate-300'}
                            `}
                        >
                            <p className={`text-[13px] font-bold tracking-tight leading-none ${activeTool === tool.id ? 'text-black dark:text-white' : 'text-slate-800 dark:text-slate-300'}`}>
                                {tool.label}
                            </p>
                            <p className="text-[8px] text-slate-500 font-bold uppercase tracking-widest">
                                {tool.desc}
                            </p>
                        </button>
                    ))}
                </div>

                <div className="max-w-xl mx-auto space-y-6">
                    <div className="p-6 rounded-[2.5rem] border border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900 shadow-sm space-y-4 transition-all focus-within:border-black dark:focus-within:border-white">
                        {activeTool === 'scanner' && (
                            <div className="mb-4">
                                <button onClick={() => fileRef.current?.click()} className="w-full py-8 border-2 border-dashed border-slate-200 dark:border-slate-800 rounded-2xl flex flex-col items-center justify-center gap-3 transition-all group hover:bg-slate-50 dark:hover:bg-slate-950">
                                    {selectedImage ? <img src={`data:${selectedImage.mimeType};base64,${selectedImage.data}`} className="w-20 h-20 rounded-xl object-cover shadow-lg border-2 border-white dark:border-slate-700" alt="Scan Asset" /> : <ImageIcon className="w-8 h-8 text-slate-400" />}
                                    <span className="text-[9px] font-bold uppercase tracking-widest">Inject Asset</span>
                                    <input type="file" ref={fileRef} className="hidden" accept="image/*" onChange={(e) => {
                                        const f = e.target.files?.[0];
                                        if (f) {
                                            const r = new FileReader();
                                            r.onloadend = () => setSelectedImage({ data: (r.result as string).split(',')[1], mimeType: f.type });
                                            r.readAsDataURL(f);
                                        }
                                    }} />
                                </button>
                            </div>
                        )}
                        <textarea value={input} onChange={(e) => setInput(e.target.value)} placeholder="Provide context..." className="w-full p-4 h-32 rounded-2xl bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 outline-none text-black dark:text-white text-sm font-medium focus:border-black dark:focus:border-white transition-all resize-none" />
                        <button onClick={runTool} disabled={loading || (!input.trim() && !selectedImage)} className="w-full py-4 rounded-2xl font-bold text-[10px] uppercase tracking-[0.3em] text-white bg-black dark:bg-white dark:text-black hover:opacity-90 disabled:opacity-20 active:scale-95 transition-all shadow-md">
                            {loading ? 'Synthesizing...' : `Execute ${activeTool.toUpperCase()}`}
                        </button>
                    </div>
                    {result && (
                        <div className="p-8 rounded-[2.5rem] bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-800 animate-slide-up relative shadow-sm overflow-hidden">
                            <button onClick={() => navigator.clipboard.writeText(result)} className="absolute top-4 right-4 p-2 bg-white dark:bg-slate-800 rounded-lg border border-slate-200 dark:border-slate-700 transition-all active:scale-90 hover:text-blue-600"><CopyIcon className="w-4 h-4" /></button>
                            <div className="max-w-none text-black dark:text-white font-medium leading-relaxed text-sm whitespace-pre-wrap">{result}</div>
                        </div>
                    )}
                </div>
            </div>
            <p className="text-center py-10 text-[10px] font-bold text-slate-400 uppercase tracking-[0.4em] select-none">Persistent Intelligence Layer 11.2</p>
        </div>
    );
};

import React, { useState, useRef, useEffect, useCallback } from 'react';
import type { ChatMessage, ChatPart, ModelType, ChatSession, MemoryFact } from '../types';
import { GoogleGenAI } from "@google/genai";
import { SendIcon, AttachmentPlusIcon, BotIcon, UserIcon, SparklesIcon, BoltIcon, BrainIcon, CodeIcon } from './Icons';

interface ChatViewProps {
  messages: ChatMessage[];
  setMessages: React.Dispatch<React.SetStateAction<ChatMessage[]>>;
  systemInstruction: string;
  model: ModelType;
  setActiveModel: (m: ModelType) => void;
  participants: string[];
  onAddParticipant: (name: string) => void;
  currentChat?: ChatSession;
  isSidebarCollapsed?: boolean;
  memories?: MemoryFact[];
}

export const ChatView: React.FC<ChatViewProps> = ({ 
  messages, setMessages, systemInstruction, model, setActiveModel, participants, onAddParticipant, currentChat, isSidebarCollapsed, memories = []
}) => {
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isSearchEnabled, setIsSearchEnabled] = useState(false);
  const [selectedImage, setSelectedImage] = useState<{ data: string; mimeType: string } | null>(null);
  const [showModelMenu, setShowModelMenu] = useState(false);
  const [copiedLink, setCopiedLink] = useState(false);

  const containerRef = useRef<HTMLDivElement>(null);
  const fileRef = useRef<HTMLInputElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  const hasMessages = messages.length > 0;

  useEffect(() => {
    if (containerRef.current) {
      containerRef.current.scrollTop = containerRef.current.scrollHeight;
    }
  }, [messages, isLoading]);

  const handleSend = useCallback(async () => {
    const trimmedInput = input.trim();
    if ((!trimmedInput && !selectedImage) || isLoading) return;

    const parts: ChatPart[] = [];
    if (selectedImage) parts.push({ inlineData: { mimeType: selectedImage.mimeType, data: selectedImage.data } });
    if (trimmedInput) parts.push({ text: trimmedInput });

    const userMsg: ChatMessage = { id: Date.now().toString(), role: 'user', parts };
    const botMsgId = (Date.now() + 1).toString();
    const botPlaceholder: ChatMessage = { id: botMsgId, role: 'model', parts: [{ text: '' }], isSearching: isSearchEnabled };

    setMessages(prev => [...prev, userMsg, botPlaceholder]);
    setInput('');
    setSelectedImage(null);
    setIsLoading(true);

    if (textareaRef.current) { textareaRef.current.style.height = 'auto'; }

    try {
      const apiKey = process.env.API_KEY;
      if (!apiKey) throw new Error("API Key missing");
      const ai = new GoogleGenAI({ apiKey });

      const vaultContext = memories.length > 0 
        ? "\n\nCONTEXT FROM VAULT:\n" + memories.map(m => `- ${m.content}`).join('\n')
        : "";

      let modelInstruction = "";
      let targetModelId = "";

      // Model personality routing with strict plain-text instructions
      switch(model) {
        case 'cognix-rv2':
          targetModelId = 'gemini-3-flash-preview';
          modelInstruction = "Role: CognixAi. Tone: Helpful, friendly, and concise. IMPORTANT: DO NOT USE BOLD SYMBOLS (*** or **). Use plain text. Use emojis in your output to be expressive. ";
          break;
        case 'clora-v1':
          targetModelId = 'gemini-3-pro-preview';
          modelInstruction = "Role: CloraV1. Tone: Deep reasoning. IMPORTANT: DO NOT USE BOLD SYMBOLS (*** or **). Use plain text. ";
          break;
        case 'clorea-v2.5':
          targetModelId = 'gemini-flash-lite-latest';
          modelInstruction = "Role: CloreaV2.5. Tone: Rapid assistant. IMPORTANT: DO NOT USE BOLD SYMBOLS (*** or **). Use plain text. ";
          break;
        case 'arctic-x':
          targetModelId = 'gemini-3-pro-preview';
          modelInstruction = "Role: ArcticX. Tone: Technical architect. IMPORTANT: DO NOT USE BOLD SYMBOLS (*** or **). Use plain text. ";
          break;
        default:
          targetModelId = 'gemini-3-flash-preview';
      }

      const finalInstruction = systemInstruction + vaultContext + "\n\n" + modelInstruction;

      if (/draw|image|generate an image|create an image|show me an image/i.test(trimmedInput)) {
        targetModelId = 'gemini-2.5-flash-image';
      }

      const history = messages.slice(-10).map(m => ({
        role: m.role,
        parts: m.parts.map(p => p.text ? { text: p.text } : { inlineData: p.inlineData })
      }));

      const res = await ai.models.generateContent({
        model: targetModelId,
        contents: [...history, { role: 'user', parts: parts as any }],
        config: { 
          systemInstruction: finalInstruction,
          tools: isSearchEnabled ? [{ googleSearch: {} }] : [] 
        }
      });

      // FIX: Extract search grounding metadata (URLs) from the response if search was enabled.
      const groundingChunks = res.candidates?.[0]?.groundingMetadata?.groundingChunks;

      const resParts: ChatPart[] = res.candidates?.[0]?.content?.parts.map(p => {
        if (p.text) return { text: p.text };
        if (p.inlineData) return { inlineData: { mimeType: p.inlineData.mimeType, data: p.inlineData.data } };
        return { text: "" };
      }).filter(p => p.text !== "" || p.inlineData) || [{ text: "No output generated." }];

      // FIX: If grounding chunks (search results) exist, append them to the response parts for rendering.
      if (groundingChunks && groundingChunks.length > 0) {
        resParts.push({ searchResults: groundingChunks });
      }

      setMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, parts: resParts, isSearching: false } : m));
    } catch (e) {
      setMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, parts: [{ text: "Neural link timeout. Please retry." }], isSearching: false } : m));
    } finally {
      setIsLoading(false);
    }
  }, [input, selectedImage, isLoading, messages, systemInstruction, model, isSearchEnabled, setMessages, memories]);

  const modelOptions = [
    { id: 'cognix-rv2', label: 'CognixRv2', desc: 'Fast and reliable', icon: <BoltIcon className="w-4 h-4"/>, tag: 'Default' },
    { id: 'clora-v1', label: 'CloraV1', desc: 'Reasoning engine', icon: <SparklesIcon className="w-4 h-4"/>, tag: 'Pro' },
    { id: 'clorea-v2.5', label: 'CloreaV2.5', desc: 'Lightweight and fast', icon: <BrainIcon className="w-4 h-4"/>, tag: 'Lite' },
    { id: 'arctic-x', label: 'ArcticX', desc: 'Technical specialist', icon: <CodeIcon className="w-4 h-4"/>, tag: 'Dev' }
  ];

  const activeModelData = modelOptions.find(m => m.id === model) || modelOptions[0];

  return (
    <div className="h-full flex flex-col bg-white dark:bg-[#020617] relative overflow-hidden transition-colors duration-300">

      <div 
        ref={containerRef} 
        className={`flex-1 overflow-y-auto px-4 sm:px-6 md:px-12 lg:px-40 scroll-smooth transition-all custom-scrollbar ${
          hasMessages ? 'pb-32 pt-6' : 'flex flex-col items-center justify-center min-h-[80dvh] pb-48'
        }`}
      >
        {!hasMessages ? (
          <div className="w-full max-w-xl mx-auto flex flex-col items-center animate-slide-up text-center select-none pointer-events-none">
             <h2 className="text-3xl sm:text-4xl font-semibold text-slate-900 dark:text-white tracking-tight mb-3 leading-tight">How can I help you?</h2>
             <p className="text-[11px] font-semibold uppercase tracking-[0.2em] text-slate-400">CognixAi Uplink Active</p>
          </div>
        ) : (
          <div className="max-w-3xl mx-auto space-y-6 w-full pb-10">
            {messages.map((m, idx) => (
              <div key={m.id} className={`flex gap-4 ${m.role === 'user' ? 'flex-row-reverse' : 'flex-row'} animate-slide-up`}>
                <div className={`w-9 h-9 shrink-0 rounded-xl flex items-center justify-center shadow-sm border ${m.role === 'user' ? 'bg-slate-900 border-slate-900 text-white' : 'bg-slate-50 dark:bg-slate-800 border-slate-200 dark:border-slate-700'}`}>
                   {m.role === 'user' ? <UserIcon className="w-4 h-4"/> : <BotIcon className="w-full h-full p-1.5"/>}
                </div>
                <div className={`flex flex-col gap-1.5 max-w-[90%] sm:max-w-[85%] ${m.role === 'user' ? 'items-end' : 'items-start'}`}>
                  {m.parts.map((p, i) => (
                    <div key={i} className={`px-5 py-3 text-[15px] sm:text-[16px] font-medium leading-relaxed ${m.role === 'user' ? 'bg-slate-100 dark:bg-slate-800 text-slate-900 dark:text-slate-100 rounded-2xl rounded-tr-sm shadow-sm' : 'bg-transparent text-slate-900 dark:text-slate-100'}`}>
                      {p.inlineData && <img src={`data:${p.inlineData.mimeType};base64,${p.inlineData.data}`} className="max-h-[400px] w-full object-contain mb-3 rounded-xl shadow-lg border dark:border-slate-700" alt="Output" />}
                      {p.text ? <div className="whitespace-pre-wrap">{p.text}</div> : (idx === messages.length - 1 && isLoading && m.role === 'model' && <div className="flex gap-1.5 py-1.5"><div className="w-2 h-2 bg-blue-500 rounded-full animate-bounce"></div><div className="w-2 h-2 bg-blue-500 rounded-full animate-bounce delay-100"></div><div className="w-2 h-2 bg-blue-500 rounded-full animate-bounce delay-200"></div></div>)}
                      {/* FIX: Render Google Search grounding sources (links) in the chat if available. */}
                      {p.searchResults && p.searchResults.length > 0 && (
                        <div className="mt-4 pt-4 border-t border-slate-100 dark:border-slate-800 w-full overflow-hidden">
                          <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-2">Sources</p>
                          <div className="flex flex-wrap gap-2">
                            {p.searchResults.map((chunk, ci) => (
                              chunk.web && (
                                <a 
                                  key={ci} 
                                  href={chunk.web.uri} 
                                  target="_blank" 
                                  rel="noopener noreferrer" 
                                  className="text-[10px] bg-slate-100 dark:bg-slate-800 px-2.5 py-1.5 rounded-lg hover:text-blue-500 transition-all truncate max-w-[240px] border border-slate-200 dark:border-slate-700"
                                >
                                  {chunk.web.title || chunk.web.uri}
                                </a>
                              )
                            ))}
                          </div>
                        </div>
                      )}
                    </div>
                  ))}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      <div className={`fixed left-0 right-0 p-3 sm:p-5 z-[60] pointer-events-none transition-all duration-300 ${isSidebarCollapsed ? 'lg:pl-16' : 'lg:pl-[240px]'} ${hasMessages ? 'bottom-0' : 'bottom-12 sm:bottom-24'}`}>
        <div className="max-w-2xl mx-auto pointer-events-auto">
          {/* Blue Strip Border Around Input Area */}
          <div className="relative bg-white dark:bg-[#0d111c] border-2 border-blue-500 rounded-[2.5rem] p-2 sm:p-2.5 shadow-[0_15px_40px_-10px_rgba(59,130,246,0.25)] dark:shadow-[0_20px_50px_-10px_rgba(0,0,0,0.5)] transition-shadow hover:shadow-[0_15px_40px_-5px_rgba(59,130,246,0.35)]">

            <div className="flex items-center gap-1.5 px-2 mb-1.5">
               <button onClick={() => setShowModelMenu(true)} className="flex items-center gap-2 py-1 px-3 text-slate-700 dark:text-slate-300 font-bold text-[10px] uppercase tracking-wider hover:bg-slate-100 dark:hover:bg-slate-800 rounded-lg transition-all border border-slate-100 dark:border-slate-800 shadow-sm">
                  {activeModelData.icon} {activeModelData.label} <span className="text-slate-400 opacity-50">▾</span>
               </button>
               <button onClick={() => setIsSearchEnabled(!isSearchEnabled)} className={`flex items-center gap-1.5 py-1 px-3 text-[9px] font-bold uppercase tracking-wider rounded-lg border transition-all ${isSearchEnabled ? 'bg-blue-50 dark:bg-blue-900/20 border-blue-200 dark:border-blue-800 text-blue-600' : 'bg-transparent border-transparent text-slate-400 hover:text-slate-600'}`}>
                  Live Search
               </button>
            </div>

            {selectedImage && <div className="px-2 pb-3 flex items-center gap-2 animate-fade-in"><div className="relative w-12 h-12 rounded-xl overflow-hidden border border-slate-200 dark:border-slate-700"><img src={`data:${selectedImage.mimeType};base64,${selectedImage.data}`} className="w-full h-full object-cover" /><button onClick={() => setSelectedImage(null)} className="absolute top-0 right-0 bg-red-600 text-white w-5 h-5 flex items-center justify-center rounded-bl-lg text-[10px] font-bold shadow-sm">×</button></div></div>}

            <div className="flex items-center gap-1.5">
                <button onClick={() => fileRef.current?.click()} className="w-10 h-10 shrink-0 flex items-center justify-center text-slate-400 hover:text-blue-500 rounded-2xl transition-all hover:bg-blue-50 dark:hover:bg-blue-900/20 group">
                    <AttachmentPlusIcon className="w-6 h-6 transition-transform group-hover:scale-110" />
                    <input type="file" ref={fileRef} className="hidden" accept="image/*" onChange={(e) => { const f = e.target.files?.[0]; if (f) { const r = new FileReader(); r.onloadend = () => setSelectedImage({ data: (r.result as string).split(',')[1], mimeType: f.type }); r.readAsDataURL(f); } }} />
                </button>
                <textarea ref={textareaRef} value={input} onChange={e => { setInput(e.target.value); e.target.style.height = 'auto'; e.target.style.height = Math.min(e.target.scrollHeight, 180) + 'px'; }} onKeyDown={e => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSend())} placeholder="Message CognixAi..." className="flex-1 bg-transparent border-none outline-none resize-none py-2 text-[15px] sm:text-[16px] text-slate-900 dark:text-white placeholder-slate-400 font-semibold max-h-[180px] min-h-[44px] custom-scrollbar leading-relaxed" rows={1} />
                <button onClick={handleSend} disabled={isLoading || (!input.trim() && !selectedImage)} className="w-10 h-10 bg-blue-600 text-white rounded-full flex items-center justify-center shadow-lg disabled:opacity-20 active:scale-95 transition-all"><SendIcon className="w-5 h-5" /></button>
            </div>
          </div>
        </div>
      </div>

      {showModelMenu && (
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm z-[100] flex items-end sm:items-center justify-center p-0 sm:p-4" onClick={() => setShowModelMenu(false)}>
          <div className="bg-white dark:bg-[#0f172a] w-full max-w-[340px] rounded-t-3xl sm:rounded-2xl p-3 shadow-2xl animate-slide-up border border-slate-200 dark:border-slate-800" onClick={e => e.stopPropagation()}>
            <div className="flex flex-col gap-1.5">
               {modelOptions.map((opt) => (
                 <button 
                  key={opt.id} 
                  onClick={() => { setActiveModel(opt.id as ModelType); setShowModelMenu(false); }} 
                  className={`w-full flex items-start gap-3.5 p-3.5 rounded-xl transition-all text-left group ${model === opt.id ? 'bg-slate-50 dark:bg-slate-800 shadow-sm' : 'hover:bg-slate-50 dark:hover:bg-slate-800/40'}`}
                 >
                    <div className={`mt-0.5 p-2 rounded-lg transition-all ${model === opt.id ? 'text-blue-600 bg-blue-50 dark:bg-blue-900/30' : 'text-slate-400'}`}>
                      {opt.icon}
                    </div>
                    <div className="flex-1">
                      <div className="flex items-center gap-2">
                        <span className={`text-[14px] font-bold tracking-tight ${model === opt.id ? 'text-slate-900 dark:text-white' : 'text-slate-600 dark:text-slate-400'}`}>{opt.label}</span>
                        {opt.tag && <span className="px-1.5 py-0.5 rounded text-[8px] font-bold uppercase tracking-wider bg-slate-200 dark:bg-slate-700 text-slate-500">{opt.tag}</span>}
                      </div>
                      <p className="text-[11px] text-slate-500 dark:text-slate-500 font-bold leading-tight">{opt.desc}</p>
                    </div>
                 </button>
               ))}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useRef, useEffect, useCallback } from 'react';
import type { ChatMessage, ChatPart, ModelType, ChatSession, MemoryFact } from '../types';
import { GoogleGenAI } from "@google/genai";
import { SendIcon, AttachmentPlusIcon, BotIcon, UserIcon, SparklesIcon, BoltIcon, BrainIcon, CodeIcon } from './Icons';

interface ChatViewProps {
  messages: ChatMessage[];
  setMessages: React.Dispatch<React.SetStateAction<ChatMessage[]>>;
  systemInstruction: string;
  model: ModelType;
  setActiveModel: (m: ModelType) => void;
  participants: string[];
  onAddParticipant: (name: string) => void;
  currentChat?: ChatSession;
  isSidebarCollapsed?: boolean;
  memories?: MemoryFact[];
}

export const ChatView: React.FC<ChatViewProps> = ({ 
  messages, setMessages, systemInstruction, model, setActiveModel, participants, onAddParticipant, currentChat, isSidebarCollapsed, memories = []
}) => {
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isSearchEnabled, setIsSearchEnabled] = useState(false);
  const [selectedImage, setSelectedImage] = useState<{ data: string; mimeType: string } | null>(null);
  const [showModelMenu, setShowModelMenu] = useState(false);

  const containerRef = useRef<HTMLDivElement>(null);
  const fileRef = useRef<HTMLInputElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  const hasMessages = messages.length > 0;

  // Auto-scroll to bottom
  useEffect(() => {
    if (containerRef.current) {
      containerRef.current.scrollTop = containerRef.current.scrollHeight;
    }
  }, [messages, isLoading]);

  const handleSend = useCallback(async () => {
    const trimmedInput = input.trim();
    if ((!trimmedInput && !selectedImage) || isLoading) return;

    const parts: ChatPart[] = [];
    if (selectedImage) parts.push({ inlineData: { mimeType: selectedImage.mimeType, data: selectedImage.data } });
    if (trimmedInput) parts.push({ text: trimmedInput });

    const userMsg: ChatMessage = { id: Date.now().toString(), role: 'user', parts };
    const botMsgId = (Date.now() + 1).toString();
    const botPlaceholder: ChatMessage = { id: botMsgId, role: 'model', parts: [{ text: '' }], isSearching: isSearchEnabled };

    setMessages(prev => [...prev, userMsg, botPlaceholder]);
    setInput('');
    setSelectedImage(null);
    setIsLoading(true);

    if (textareaRef.current) { textareaRef.current.style.height = 'auto'; }

    try {
      const apiKey = process.env.API_KEY;
      if (!apiKey) throw new Error("API Key missing");
      const ai = new GoogleGenAI({ apiKey });

      const vaultContext = memories.length > 0 
        ? "\n\nCONTEXT FROM VAULT:\n" + memories.map(m => `- ${m.content}`).join('\n')
        : "";

      let modelInstruction = "";
      let targetModelId = "";
      let config: any = { 
        systemInstruction: "", 
        temperature: 0.7,
        tools: isSearchEnabled ? [{ googleSearch: {} }] : [] 
      };

      // Enhanced Model Differentiation
      switch(model) {
        case 'cognix-rv2':
          targetModelId = 'gemini-3-flash-preview';
          modelInstruction = "Role: CognixAi. Friendly, fast, use emojis. No bold markdown.";
          config.temperature = 1.0;
          break;
        case 'clora-v1':
          targetModelId = 'gemini-3-pro-preview';
          modelInstruction = "Role: CloraV1. Analytical, deep reasoning. No bold markdown.";
          config.thinkingConfig = { thinkingBudget: 16000 };
          config.temperature = 0.4;
          break;
        case 'clorea-v2.5':
          targetModelId = 'gemini-flash-lite-latest';
          modelInstruction = "Role: CloreaV2.5. Ultra-concise, rapid-fire responses. No bold markdown.";
          config.temperature = 0.2;
          break;
        case 'arctic-x':
          targetModelId = 'gemini-3-pro-preview';
          modelInstruction = "Role: ArcticX. Expert coder and technical architect. No bold markdown.";
          config.thinkingConfig = { thinkingBudget: 32000 };
          config.temperature = 0.5;
          break;
        default:
          targetModelId = 'gemini-3-flash-preview';
      }

      config.systemInstruction = systemInstruction + vaultContext + "\n\n" + modelInstruction;

      if (/draw|image|generate an image|create an image|show me an image/i.test(trimmedInput)) {
        targetModelId = 'gemini-2.5-flash-image';
      }

      const history = messages.slice(-10).map(m => ({
        role: m.role,
        parts: m.parts.filter(p => p.text || p.inlineData).map(p => p.text ? { text: p.text } : { inlineData: p.inlineData })
      }));

      const res = await ai.models.generateContent({
        model: targetModelId,
        contents: [...history, { role: 'user', parts: parts as any }],
        config
      });

      const groundingChunks = res.candidates?.[0]?.groundingMetadata?.groundingChunks;
      const resParts: ChatPart[] = res.candidates?.[0]?.content?.parts.map(p => {
        if (p.text) return { text: p.text };
        if (p.inlineData) return { inlineData: { mimeType: p.inlineData.mimeType, data: p.inlineData.data } };
        return { text: "" };
      }).filter(p => p.text !== "" || p.inlineData) || [{ text: "No output generated." }];

      if (groundingChunks && groundingChunks.length > 0) {
        resParts.push({ searchResults: groundingChunks });
      }

      setMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, parts: resParts, isSearching: false } : m));
    } catch (e) {
      setMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, parts: [{ text: "Neural link timeout. Please check your connection and retry." }], isSearching: false } : m));
    } finally {
      setIsLoading(false);
    }
  }, [input, selectedImage, isLoading, messages, systemInstruction, model, isSearchEnabled, setMessages, memories]);

  const modelOptions = [
    { id: 'cognix-rv2', label: 'CognixRv2', desc: 'Fast & Friendly', icon: <BoltIcon className="w-4 h-4"/>, tag: 'Default' },
    { id: 'clora-v1', label: 'CloraV1', desc: 'Reasoning Engine', icon: <SparklesIcon className="w-4 h-4"/>, tag: 'Pro' },
    { id: 'clorea-v2.5', label: 'CloreaV2.5', desc: 'Lightning Fast', icon: <BrainIcon className="w-4 h-4"/>, tag: 'Lite' },
    { id: 'arctic-x', label: 'ArcticX', desc: 'Code Architect', icon: <CodeIcon className="w-4 h-4"/>, tag: 'Dev' }
  ];

  const activeModelData = modelOptions.find(m => m.id === model) || modelOptions[0];

  return (
    <div className="h-full flex flex-col bg-white dark:bg-[#020617] relative overflow-hidden">

      <div 
        ref={containerRef} 
        className={`flex-1 overflow-y-auto px-4 sm:px-6 md:px-12 lg:px-40 scroll-smooth custom-scrollbar ${
          hasMessages ? 'pb-48 pt-6' : 'flex flex-col items-center justify-center min-h-[80dvh] pb-64'
        }`}
      >
        {!hasMessages ? (
          <div className="w-full max-w-xl mx-auto flex flex-col items-center animate-slide-up text-center select-none">
             <h2 className="text-3xl sm:text-4xl font-semibold text-slate-900 dark:text-white tracking-tight mb-3 leading-tight opacity-80">How can I help you?</h2>
             <p className="text-[10px] font-bold uppercase tracking-[0.3em] text-blue-500 animate-pulse">Uplink System v11.2</p>
          </div>
        ) : (
          <div className="max-w-3xl mx-auto space-y-8 w-full">
            {messages.map((m, idx) => (
              <div key={m.id} className={`flex gap-4 ${m.role === 'user' ? 'flex-row-reverse' : 'flex-row'} animate-slide-up`}>
                <div className={`w-9 h-9 shrink-0 rounded-xl flex items-center justify-center shadow-sm border ${m.role === 'user' ? 'bg-slate-900 border-slate-900 text-white' : 'bg-slate-50 dark:bg-slate-800 border-slate-200 dark:border-slate-700'}`}>
                   {m.role === 'user' ? <UserIcon className="w-4 h-4"/> : <BotIcon className="w-full h-full p-1.5"/>}
                </div>
                <div className={`flex flex-col gap-2 max-w-[90%] sm:max-w-[85%] ${m.role === 'user' ? 'items-end' : 'items-start'}`}>
                  {m.parts.map((p, i) => (
                    <div key={i} className={`px-5 py-3 text-[15px] sm:text-[16px] font-medium leading-relaxed ${m.role === 'user' ? 'bg-slate-100 dark:bg-slate-800 text-slate-900 dark:text-slate-100 rounded-2xl rounded-tr-sm' : 'bg-transparent text-slate-900 dark:text-slate-100'}`}>
                      {p.inlineData && <img src={`data:${p.inlineData.mimeType};base64,${p.inlineData.data}`} className="max-h-[400px] w-full object-contain mb-3 rounded-xl shadow-lg border dark:border-slate-700" alt="Output" />}
                      {p.text ? <div className="whitespace-pre-wrap">{p.text}</div> : (idx === messages.length - 1 && isLoading && m.role === 'model' && <div className="flex gap-1.5 py-1.5"><div className="w-2 h-2 bg-blue-500 rounded-full animate-bounce"></div><div className="w-2 h-2 bg-blue-500 rounded-full animate-bounce delay-100"></div><div className="w-2 h-2 bg-blue-500 rounded-full animate-bounce delay-200"></div></div>)}
                      {p.searchResults && p.searchResults.length > 0 && (
                        <div className="mt-4 pt-4 border-t border-slate-100 dark:border-slate-800 w-full">
                          <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-3">Grounding Sources</p>
                          <div className="grid grid-cols-1 gap-2">
                            {p.searchResults.map((chunk, ci) => (
                              chunk.web && (
                                <a 
                                  key={ci} 
                                  href={chunk.web.uri} 
                                  target="_blank" 
                                  rel="noopener noreferrer" 
                                  className="flex items-center justify-between p-3 rounded-xl bg-slate-50 dark:bg-slate-900 hover:bg-slate-100 dark:hover:bg-slate-800 border border-slate-100 dark:border-slate-800 transition-all group"
                                >
                                  <span className="text-[12px] font-bold text-slate-700 dark:text-slate-200 truncate pr-4">{chunk.web.title || chunk.web.uri}</span>
                                  <span className="text-[10px] text-blue-500 font-bold shrink-0 opacity-0 group-hover:opacity-100">Visit →</span>
                                </a>
                              )
                            ))}
                          </div>
                        </div>
                      )}
                    </div>
                  ))}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* FIXED INPUT AREA */}
      <div className={`fixed bottom-0 left-0 right-0 p-4 sm:p-6 z-[60] bg-gradient-to-t from-white via-white/95 to-transparent dark:from-[#020617] dark:via-[#020617]/95 dark:to-transparent transition-all duration-300 ${isSidebarCollapsed ? 'lg:pl-16' : 'lg:pl-[240px]'}`}>
        <div className="max-w-3xl mx-auto flex flex-col gap-2">

          {/* Label above typebar as requested */}
          <div className="flex items-center justify-between px-2">
            <span className="text-[11px] font-black text-blue-600 dark:text-blue-400 uppercase tracking-[0.2em] animate-fade-in">Message CognixAi</span>
            {isSearchEnabled && (
              <span className="text-[9px] font-bold text-emerald-500 uppercase tracking-widest flex items-center gap-1.5">
                <span className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse"></span> Grounding Enabled
              </span>
            )}
          </div>

          <div className="relative bg-white dark:bg-[#0d111c] border-2 border-blue-500 rounded-3xl p-2 shadow-[0_10px_40px_-10px_rgba(59,130,246,0.3)]">
            <div className="flex items-center gap-1.5 px-2 mb-2">
               <button onClick={() => setShowModelMenu(true)} className="flex items-center gap-2 py-1 px-3 text-slate-700 dark:text-slate-300 font-bold text-[10px] uppercase tracking-wider hover:bg-slate-100 dark:hover:bg-slate-800 rounded-lg transition-all border border-slate-100 dark:border-slate-800 shadow-sm">
                  {activeModelData.icon} {activeModelData.label} <span className="text-slate-400 opacity-50">▾</span>
               </button>
               <button onClick={() => setIsSearchEnabled(!isSearchEnabled)} className={`flex items-center gap-1.5 py-1 px-3 text-[9px] font-bold uppercase tracking-wider rounded-lg border transition-all ${isSearchEnabled ? 'bg-blue-50 dark:bg-blue-900/20 border-blue-200 dark:border-blue-800 text-blue-600' : 'bg-transparent border-transparent text-slate-400 hover:text-slate-600'}`}>
                  Live Search
               </button>
            </div>

            {selectedImage && (
              <div className="px-2 pb-3 flex items-center gap-2 animate-fade-in">
                <div className="relative w-12 h-12 rounded-xl overflow-hidden border-2 border-blue-500 shadow-md">
                  <img src={`data:${selectedImage.mimeType};base64,${selectedImage.data}`} className="w-full h-full object-cover" />
                  <button onClick={() => setSelectedImage(null)} className="absolute top-0 right-0 bg-red-600 text-white w-5 h-5 flex items-center justify-center rounded-bl-lg text-[10px] font-bold">×</button>
                </div>
              </div>
            )}

            <div className="flex items-center gap-2">
                <button onClick={() => fileRef.current?.click()} className="w-10 h-10 shrink-0 flex items-center justify-center text-slate-400 hover:text-blue-500 rounded-full transition-all hover:bg-blue-50 dark:hover:bg-blue-900/20 group">
                    <AttachmentPlusIcon className="w-6 h-6 transition-transform group-hover:scale-110" />
                    <input type="file" ref={fileRef} className="hidden" accept="image/*" onChange={(e) => { const f = e.target.files?.[0]; if (f) { const r = new FileReader(); r.onloadend = () => setSelectedImage({ data: (r.result as string).split(',')[1], mimeType: f.type }); r.readAsDataURL(f); } }} />
                </button>
                <textarea 
                  ref={textareaRef} 
                  value={input} 
                  onChange={e => { 
                    setInput(e.target.value); 
                    e.target.style.height = 'auto'; 
                    e.target.style.height = Math.min(e.target.scrollHeight, 180) + 'px'; 
                  }} 
                  onKeyDown={e => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSend())} 
                  placeholder="Enter your query..." 
                  className="flex-1 bg-transparent border-none outline-none resize-none py-2 text-[15px] text-slate-900 dark:text-white placeholder-slate-400 font-semibold max-h-[180px] min-h-[44px] custom-scrollbar leading-relaxed" 
                  rows={1} 
                />
                <button onClick={handleSend} disabled={isLoading || (!input.trim() && !selectedImage)} className="w-10 h-10 bg-blue-600 text-white rounded-full flex items-center justify-center shadow-lg disabled:opacity-20 active:scale-95 transition-all">
                  <SendIcon className="w-5 h-5" />
                </button>
            </div>
          </div>
        </div>
      </div>

      {showModelMenu && (
        <div className="fixed inset-0 bg-black/40 backdrop-blur-md z-[100] flex items-end sm:items-center justify-center p-0 sm:p-4" onClick={() => setShowModelMenu(false)}>
          <div className="bg-white dark:bg-[#0f172a] w-full max-w-[340px] rounded-t-3xl sm:rounded-2xl p-4 shadow-2xl animate-slide-up border border-slate-200 dark:border-slate-800" onClick={e => e.stopPropagation()}>
            <div className="flex flex-col gap-2">
               {modelOptions.map((opt) => (
                 <button 
                  key={opt.id} 
                  onClick={() => { setActiveModel(opt.id as ModelType); setShowModelMenu(false); }} 
                  className={`w-full flex items-start gap-3.5 p-3.5 rounded-2xl transition-all text-left group ${model === opt.id ? 'bg-slate-50 dark:bg-slate-800 shadow-sm border border-blue-200 dark:border-blue-900/50' : 'hover:bg-slate-50 dark:hover:bg-slate-800/40'}`}
                 >
                    <div className={`mt-0.5 p-2 rounded-lg transition-all ${model === opt.id ? 'text-blue-600 bg-blue-50 dark:bg-blue-900/30' : 'text-slate-400'}`}>
                      {opt.icon}
                    </div>
                    <div className="flex-1">
                      <div className="flex items-center gap-2">
                        <span className={`text-[14px] font-bold tracking-tight ${model === opt.id ? 'text-slate-900 dark:text-white' : 'text-slate-600 dark:text-slate-400'}`}>{opt.label}</span>
                        {opt.tag && <span className="px-1.5 py-0.5 rounded text-[8px] font-bold uppercase tracking-wider bg-slate-200 dark:bg-slate-700 text-slate-500">{opt.tag}</span>}
                      </div>
                      <p className="text-[11px] text-slate-500 dark:text-slate-500 font-bold leading-tight">{opt.desc}</p>
                    </div>
                 </button>
               ))}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { GoogleGenAI } from "@google/genai";
import { CodeIcon, CopyIcon, ImageIcon, SparklesIcon, SendIcon, BoltIcon } from './Icons';
import type { ThemeColors, ModelType } from '../types';

export const ToolboxView: React.FC<{ theme: ThemeColors, model: ModelType }> = ({ theme, model }) => {
    const [activeTool, setActiveTool] = useState<'summarizer' | 'scanner' | 'writer' | 'enhancer' | 'dev'>('summarizer');
    const [input, setInput] = useState('');
    const [result, setResult] = useState('');
    const [loading, setLoading] = useState(false);
    const [viewMode, setViewMode] = useState<'preview' | 'code'>('preview');
    const [mobileDevTab, setMobileDevTab] = useState<'editor' | 'view'>('editor');
    const [publishedUrl, setPublishedUrl] = useState<string | null>(null);
    const [selectedImage, setSelectedImage] = useState<{ data: string, mimeType: string } | null>(null);
    const [devLogs, setDevLogs] = useState<string[]>([]);
    const fileRef = useRef<HTMLInputElement>(null);

    const logActivity = (msg: string) => {
        setDevLogs(prev => [...prev.slice(-4), msg]);
    };

    const runTool = async () => {
        if (!input.trim() && !selectedImage) return;
        setLoading(true);
        if (activeTool !== 'dev') setResult('');
        setPublishedUrl(null);
        setDevLogs([]);

        try {
            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
            let instruction = "";
            let targetModelName: string = "";

            switch(model) {
                case 'cognix-rv2': targetModelName = 'gemini-3-flash-preview'; break;
                case 'clora-v1': targetModelName = 'gemini-3-pro-preview'; break;
                case 'clorea-v2.5': targetModelName = 'gemini-flash-lite-latest'; break;
                case 'arctic-x': targetModelName = 'gemini-3-pro-preview'; break;
                case 'visualizer': targetModelName = 'gemini-2.5-flash-image'; break;
                default: targetModelName = 'gemini-3-flash-preview';
            }

            if (activeTool === 'dev') {
                logActivity("Initializing Neural Architecture...");
                setTimeout(() => logActivity("Analyzing UI Requirements..."), 1000);
            }

            switch(activeTool) {
                case 'summarizer': instruction = "Summarize the following into elite bullet points."; break;
                case 'scanner': instruction = "Analyze this image in high detail."; targetModelName = 'gemini-3-flash-preview'; break;
                case 'writer': instruction = "Write professional engaging content."; break;
                case 'enhancer': instruction = "Engineer a high-fidelity prompt from this input."; break;
                case 'dev': instruction = "ACT AS A SENIOR FRONTEND ENGINEER. Build a modern, mobile-responsive single-file landing page using Tailwind CSS. OUTPUT RAW HTML ONLY starting with <!DOCTYPE html>. No commentary."; break;
            }

            const parts: any[] = [{ text: `${instruction}\n\nINPUT: "${input}"` }];
            if (selectedImage && activeTool === 'scanner') {
                parts.push({ inlineData: { data: selectedImage.data, mimeType: selectedImage.mimeType } });
            }

            const response = await ai.models.generateContent({
                model: targetModelName,
                contents: [{ parts }],
            });

            if (activeTool === 'dev') {
                logActivity("Synthesis Complete. Assembler Finalized.");
                setMobileDevTab('view'); // Auto switch to view on success for mobile
            }
            setResult(response.text || '');
        } catch (e) {
            setResult('Uplink failed. Try again.');
        } finally {
            setLoading(false);
        }
    };

    const handlePublish = () => {
        if (!result) return;
        try {
            const b64 = btoa(unescape(encodeURIComponent(result)));
            const url = `${window.location.origin}${window.location.pathname}?deployment=${b64}`;
            setPublishedUrl(url);
        } catch(e) { console.error("Publish failed", e); }
    };

    const tools = [
        { id: 'summarizer', label: 'Summarizer', desc: 'CONDENSER' },
        { id: 'scanner', label: 'Scanner', desc: 'VISION' },
        { id: 'writer', label: 'Writer', desc: 'CONTENT' },
        { id: 'enhancer', label: 'Enhancer', desc: 'PROMPT' },
        { id: 'dev', label: 'Dev Studio', desc: 'UI ARCHITECT' }
    ];

    if (activeTool === 'dev') {
        return (
            <div className="h-full bg-white dark:bg-[#020617] flex flex-col animate-fade-in overflow-hidden">
                <header className="px-4 sm:px-6 py-4 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between">
                    <div className="flex items-center gap-3">
                        <button onClick={() => setActiveTool('summarizer')} className="text-xs font-bold text-slate-500 hover:text-black dark:hover:text-white uppercase tracking-widest">← Back</button>
                        <h2 className="text-sm font-bold tracking-tight uppercase px-3 py-1 bg-black text-white dark:bg-white dark:text-black rounded-lg hidden sm:block">Dev Studio Node</h2>
                    </div>
                    <div className="flex sm:hidden bg-slate-100 dark:bg-slate-900 p-1 rounded-xl">
                        <button onClick={() => setMobileDevTab('editor')} className={`px-4 py-1.5 rounded-lg text-[10px] font-bold uppercase transition-all ${mobileDevTab === 'editor' ? 'bg-white dark:bg-slate-800 shadow-sm' : 'text-slate-500'}`}>Editor</button>
                        <button onClick={() => setMobileDevTab('view')} className={`px-4 py-1.5 rounded-lg text-[10px] font-bold uppercase transition-all ${mobileDevTab === 'view' ? 'bg-white dark:bg-slate-800 shadow-sm' : 'text-slate-500'}`}>Preview</button>
                    </div>
                    {result && (
                        <div className="hidden sm:flex bg-slate-100 dark:bg-slate-900 p-1 rounded-xl">
                            <button onClick={() => setViewMode('preview')} className={`px-4 py-1.5 rounded-lg text-[10px] font-bold uppercase transition-all ${viewMode === 'preview' ? 'bg-white dark:bg-slate-800 shadow-sm' : 'text-slate-500'}`}>Preview</button>
                            <button onClick={() => setViewMode('code')} className={`px-4 py-1.5 rounded-lg text-[10px] font-bold uppercase transition-all ${viewMode === 'code' ? 'bg-white dark:bg-slate-800 shadow-sm' : 'text-slate-500'}`}>Code</button>
                        </div>
                    )}
                </header>

                <div className="flex-1 flex flex-col sm:flex-row overflow-hidden">
                    {/* Editor Pane */}
                    <div className={`${mobileDevTab === 'editor' ? 'flex' : 'hidden'} sm:flex w-full sm:w-[400px] border-r border-slate-100 dark:border-slate-800 flex-col p-4 sm:p-6 space-y-4 overflow-y-auto`}>
                        <textarea 
                            value={input}
                            onChange={(e) => setInput(e.target.value)}
                            placeholder="Describe your UI vision (e.g., 'A modern travel landing page with hero section and feature cards')..."
                            className="flex-1 p-4 bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl text-sm font-medium outline-none resize-none focus:border-blue-500 transition-all min-h-[200px]"
                        />

                        {loading && devLogs.length > 0 && (
                            <div className="bg-slate-50 dark:bg-slate-900/50 p-4 rounded-xl border border-slate-200 dark:border-slate-800">
                                <p className="text-[9px] font-bold uppercase tracking-widest text-slate-400 mb-2">Neural Status</p>
                                <div className="space-y-1">
                                    {devLogs.map((log, i) => (
                                        <p key={i} className={`text-[10px] font-mono ${i === devLogs.length - 1 ? 'text-blue-500 font-bold' : 'text-slate-500 opacity-60'}`}>{`> ${log}`}</p>
                                    ))}
                                </div>
                            </div>
                        )}

                        <button 
                            onClick={runTool}
                            disabled={loading || !input.trim()}
                            className="w-full py-4 bg-black dark:bg-white text-white dark:text-black rounded-2xl font-bold text-[10px] uppercase tracking-[0.2em] shadow-lg active:scale-95 disabled:opacity-30 transition-all"
                        >
                            {loading ? 'Synthesizing...' : 'Build UI Asset'}
                        </button>
                    </div>

                    {/* Preview Pane */}
                    <div className={`${mobileDevTab === 'view' ? 'flex' : 'hidden'} sm:flex flex-1 bg-slate-50 dark:bg-[#01040a] relative flex-col overflow-hidden`}>
                        {!result ? (
                            <div className="flex-1 flex flex-col items-center justify-center text-slate-400 opacity-50 p-10 text-center">
                                <CodeIcon className="w-12 h-12 mb-4" />
                                <p className="text-xs font-bold uppercase tracking-widest leading-loose">Blueprint Ready.<br/>Generate a vision to start previewing.</p>
                            </div>
                        ) : viewMode === 'preview' ? (
                            <div className="flex-1 flex flex-col">
                                <div className="flex items-center justify-between px-6 py-2 bg-white dark:bg-slate-900 border-b border-slate-200 dark:border-slate-800">
                                    <span className="text-[10px] font-bold uppercase tracking-widest text-slate-500">Live Workspace</span>
                                    <button onClick={handlePublish} className="text-[10px] font-bold text-blue-600 hover:text-blue-700 uppercase tracking-widest transition-colors">Publish</button>
                                </div>
                                {publishedUrl && (
                                    <div className="p-3 bg-blue-50 dark:bg-blue-900/20 border-b border-blue-200 dark:border-blue-800 flex items-center justify-between gap-4 animate-slide-up">
                                        <p className="text-[9px] font-mono truncate text-blue-800 dark:text-blue-300">DEPLOYED: {publishedUrl}</p>
                                        <button onClick={() => { navigator.clipboard.writeText(publishedUrl); setPublishedUrl(null); }} className="px-3 py-1 bg-blue-600 text-white rounded-lg text-[9px] font-bold uppercase hover:bg-blue-700 transition-colors">Copy</button>
                                    </div>
                                )}
                                <iframe srcDoc={result} className="flex-1 w-full border-none bg-white" title="UI Preview" />
                            </div>
                        ) : (
                            <div className="flex-1 p-4 sm:p-6 overflow-hidden flex flex-col">
                                <div className="flex justify-between mb-4">
                                     <span className="text-[10px] font-bold uppercase tracking-widest text-slate-500">Raw Source</span>
                                     <button onClick={() => navigator.clipboard.writeText(result)} className="p-2 bg-white dark:bg-slate-800 rounded-lg border border-slate-200 dark:border-slate-700 hover:scale-105 transition-all active:scale-95"><CopyIcon className="w-4 h-4"/></button>
                                </div>
                                <pre className="flex-1 p-4 sm:p-6 bg-slate-900 text-slate-100 rounded-2xl text-[11px] overflow-auto custom-scrollbar font-mono leading-relaxed">
                                    {result}
                                </pre>
                            </div>
                        )}
                    </div>
                </div>
            </div>
        );
    }

    return (
        <div className="h-full overflow-y-auto bg-white dark:bg-[#020617] p-4 sm:p-10 animate-fade-in custom-scrollbar">
            <div className="max-w-6xl mx-auto space-y-10 pb-20">
                <header className="flex flex-col sm:flex-row sm:items-end justify-between gap-4">
                    <div>
                        <h2 className="text-3xl font-bold text-black dark:text-white tracking-tight uppercase leading-none mb-2">Cognix Lab</h2>
                        <p className="text-slate-500 dark:text-slate-400 font-bold text-[11px] uppercase tracking-widest">Neural Prototyping Terminal</p>
                    </div>
                    <div className="flex items-center gap-2 px-4 py-2 bg-slate-100 dark:bg-slate-900 rounded-2xl border border-slate-200 dark:border-slate-800">
                        <div className="relative w-8 h-8">
                            <div className="absolute inset-0 bg-blue-500/20 rounded-full animate-ping"></div>
                            <div className="relative flex items-center justify-center w-full h-full bg-blue-600 rounded-xl shadow-lg shadow-blue-500/30">
                                <BoltIcon className="w-4 h-4 text-white" />
                            </div>
                        </div>
                        <div>
                            <p className="text-[10px] font-bold text-black dark:text-white uppercase leading-none">Lab Active</p>
                            <p className="text-[8px] font-bold text-blue-500 uppercase tracking-widest mt-1">Uplink 11.2</p>
                        </div>
                    </div>
                </header>

                <div className="grid grid-cols-2 md:grid-cols-5 gap-2">
                    {tools.map(tool => (
                        <button 
                            key={tool.id} 
                            onClick={() => { setActiveTool(tool.id as any); setResult(''); setInput(''); setSelectedImage(null); }}
                            className={`flex flex-col items-start gap-1 p-4 rounded-xl border-2 transition-all text-left
                                ${activeTool === tool.id 
                                    ? 'border-black bg-slate-50 dark:bg-slate-800 shadow-sm' 
                                    : 'bg-white dark:bg-slate-900 border-slate-100 dark:border-slate-800 hover:border-slate-300'}
                            `}
                        >
                            <p className={`text-[13px] font-bold tracking-tight leading-none ${activeTool === tool.id ? 'text-black dark:text-white' : 'text-slate-800 dark:text-slate-300'}`}>
                                {tool.label}
                            </p>
                            <p className="text-[8px] text-slate-500 font-bold uppercase tracking-widest">
                                {tool.desc}
                            </p>
                        </button>
                    ))}
                </div>

                <div className="max-w-xl mx-auto space-y-6">
                    <div className="p-6 rounded-[2.5rem] border border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900 shadow-sm space-y-4 transition-all focus-within:border-blue-500">
                        {activeTool === 'scanner' && (
                            <div className="mb-4">
                                <button onClick={() => fileRef.current?.click()} className="w-full py-8 border-2 border-dashed border-slate-200 dark:border-slate-800 rounded-2xl flex flex-col items-center justify-center gap-3 transition-all group hover:bg-slate-50 dark:hover:bg-slate-950">
                                    {selectedImage ? <img src={`data:${selectedImage.mimeType};base64,${selectedImage.data}`} className="w-20 h-20 rounded-xl object-cover shadow-lg border-2 border-white dark:border-slate-700" alt="Scan Asset" /> : <ImageIcon className="w-8 h-8 text-slate-400" />}
                                    <span className="text-[9px] font-bold uppercase tracking-widest">Inject Asset</span>
                                    <input type="file" ref={fileRef} className="hidden" accept="image/*" onChange={(e) => {
                                        const f = e.target.files?.[0];
                                        if (f) {
                                            const r = new FileReader();
                                            r.onloadend = () => setSelectedImage({ data: (r.result as string).split(',')[1], mimeType: f.type });
                                            r.readAsDataURL(f);
                                        }
                                    }} />
                                </button>
                            </div>
                        )}
                        <textarea 
                            value={input} 
                            onChange={(e) => setInput(e.target.value)} 
                            placeholder="Provide context..." 
                            className="w-full p-4 h-32 rounded-2xl bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 outline-none text-black dark:text-white text-sm font-medium focus:border-blue-500 transition-all resize-none shadow-inner" 
                        />
                        <button onClick={runTool} disabled={loading || (!input.trim() && !selectedImage)} className="w-full py-4 rounded-2xl font-bold text-[10px] uppercase tracking-[0.3em] text-white bg-black dark:bg-white dark:text-black hover:opacity-90 disabled:opacity-20 active:scale-95 transition-all shadow-md">
                            {loading ? 'Synthesizing...' : `Execute ${activeTool.toUpperCase()}`}
                        </button>
                    </div>
                    {result && (
                        <div className="p-6 sm:p-8 rounded-[2.5rem] bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-800 animate-slide-up relative shadow-sm overflow-hidden">
                            <button onClick={() => navigator.clipboard.writeText(result)} className="absolute top-4 right-4 p-2 bg-white dark:bg-slate-800 rounded-lg border border-slate-200 dark:border-slate-700 transition-all active:scale-90 hover:text-blue-600"><CopyIcon className="w-4 h-4" /></button>
                            <div className="max-w-none text-black dark:text-white font-medium leading-relaxed text-sm whitespace-pre-wrap">{result}</div>
                        </div>
                    )}
                </div>
            </div>
            <p className="text-center py-10 text-[10px] font-bold text-slate-400 uppercase tracking-[0.4em] select-none">Persistent Intelligence Layer 11.2</p>
        </div>
    );
};

