import React from 'react';
import type { ChatSession, Mode } from '../types';
import { BotIcon, CoreChatIcon, LabIcon, CollectiveIcon } from './Icons';

interface SidebarProps {
  chatHistory: ChatSession[];
  activeChatId: string | null;
  mode: Mode;
  onSetMode: (mode: Mode) => void;
  onSelectChat: (id: string) => void;
  onNewChat: () => void;
  onDeleteChat: (id: string) => void;
  isSidebarOpen: boolean;
  isSidebarCollapsed: boolean;
  onToggleCollapse: () => void;
  onClose: () => void;
}

export const Sidebar: React.FC<SidebarProps> = ({ 
  chatHistory, activeChatId, mode, onSetMode, onSelectChat, onNewChat, isSidebarOpen, isSidebarCollapsed, onClose 
}) => {

  const NavItem: React.FC<{ m: Mode, icon: React.ReactNode, label: string }> = ({ m, icon, label }) => {
    const isActive = mode === m;
    return (
      <button
          onClick={() => { onSetMode(m); if(window.innerWidth < 1024) onClose(); }}
          className={`w-full flex items-center gap-4 px-4 py-2.5 rounded-xl transition-all duration-200
              ${isActive 
                  ? 'bg-black text-white' 
                  : 'text-[#64748b] hover:text-black hover:bg-slate-50'}
          `}
      >
          <span className="shrink-0">
            {React.isValidElement(icon) ? React.cloneElement(icon as React.ReactElement<any>, { className: 'w-5 h-5' }) : icon}
          </span>
          {!isSidebarCollapsed && <span className="text-[14px] font-bold tracking-tight">{label}</span>}
      </button>
    );
  };

  return (
    <>
      {isSidebarOpen && (
        <div className="fixed inset-0 bg-black/10 z-[60] lg:hidden" onClick={onClose} />
      )}
      <aside className={`fixed lg:static inset-y-0 left-0 z-[70] transition-all duration-300 h-full bg-white border-r border-slate-100 flex flex-col
        ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}
        ${isSidebarCollapsed ? 'w-20' : 'w-[280px]'}
      `}>
        <div className="p-6 flex flex-col h-full">
           <div className="flex items-center gap-3 mb-10 px-2">
              <BotIcon className="w-8 h-8" />
              {!isSidebarCollapsed && (
                <h2 className="text-[18px] font-bold tracking-tight text-black">CognixAI</h2>
              )}
           </div>

           <div className="space-y-2 mb-8">
              <nav className="space-y-1">
                <NavItem m="chat" icon={<CoreChatIcon />} label="Core Chat" />
                <NavItem m="toolbox" icon={<LabIcon />} label="Cognix Lab" />
                <NavItem m="community" icon={<CollectiveIcon />} label="Collective" />
              </nav>
           </div>

           <button 
             onClick={() => { onNewChat(); if(window.innerWidth < 1024) onClose(); }}
             className={`w-full flex items-center justify-center py-4 bg-[#f1f5f9] text-black rounded-2xl font-bold text-[14px] transition-all hover:bg-[#e2e8f0] mb-10`}
           >
             {!isSidebarCollapsed ? "New Pulse" : "+"}
           </button>

           {!isSidebarCollapsed && (
             <div className="flex-1 flex flex-col min-h-0">
                <div className="px-2 mb-4">
                  <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Recent Pulses</h3>
                </div>
                <div className="flex-1 overflow-y-auto space-y-1 pr-1 custom-scrollbar pb-6">
                  {chatHistory.map((chat) => (
                    <button 
                      key={chat.id}
                      onClick={() => { onSelectChat(chat.id); onSetMode('chat'); if(window.innerWidth < 1024) onClose(); }}
                      className={`w-full text-left px-4 py-3 rounded-xl transition-all flex items-center justify-between
                        ${activeChatId === chat.id && mode === 'chat' 
                          ? 'bg-slate-100 text-black font-semibold' 
                          : 'text-slate-500 hover:text-black hover:bg-slate-50'}
                      `}
                    >
                      <span className="text-[13px] truncate">{chat.title}</span>
                    </button>
                  ))}
                </div>
             </div>
           )}

           <div className={`pt-4 border-t border-slate-100 mt-auto ${isSidebarCollapsed ? 'hidden' : ''}`}>
              <div className="flex items-center justify-between p-3 rounded-2xl bg-[#f8fafc]">
                <div className="flex items-center gap-3">
                  <div className="w-2 h-2 rounded-full bg-blue-500 shadow-[0_0_8px_rgba(59,130,246,0.6)]"></div>
                  <span className="text-[10px] font-bold text-[#64748b] uppercase tracking-widest">Neural Link</span>
                </div>
                <span className="text-[10px] font-bold text-slate-400">11.2</span>
              </div>
           </div>
        </div>
      </aside>
    </>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { ChatView } from './components/ChatView';
import { LiveView } from './components/LiveView';
import { Sidebar } from './components/Sidebar';
import { CommunityView } from './components/CommunityView';
import { ToolboxView } from './components/ToolboxView';
import { MenuIcon, BotIcon, UserIcon, MicrophoneIcon } from './components/Icons';
import { SettingsModal } from './components/SettingsModal';
import type { ChatMessage, ChatSession, Mode, ThemeColors, ModelType, MemoryFact } from './types';

const THEME: ThemeColors = {
    primary: 'bg-black',
    primaryHover: 'hover:opacity-90',
    text: 'text-black',
    textDark: 'text-white',
    bgSoft: 'bg-slate-50',
    darkBgSoft: 'dark:bg-slate-900',
    border: 'border-slate-200',
    ring: 'focus:ring-black',
    gradient: 'bg-black'
};

const App: React.FC = () => {
  const [mode, setMode] = useState<Mode>('chat');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [activeModel, setActiveModel] = useState<ModelType>('cognix-rv2');
  const [systemInstruction, setSystemInstruction] = useState("I am CognixAi. Use plain text only. No bolding. Use emojis.");

  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [chatHistory, setChatHistory] = useState<ChatSession[]>([]);
  const [activeChatId, setActiveChatId] = useState<string | null>(null);
  const [memories, setMemories] = useState<MemoryFact[]>([]);

  const currentChat = useMemo(() => chatHistory.find(c => c.id === activeChatId), [chatHistory, activeChatId]);

  useEffect(() => {
    const savedHistory = localStorage.getItem('cognix_v8_history');
    if (savedHistory) setChatHistory(JSON.parse(savedHistory));
  }, []);

  const handleUpdateMessages = (updater: (prev: ChatMessage[]) => ChatMessage[]) => {
    setMessages(prev => {
      const next = updater(prev);
      if (activeChatId) {
        setChatHistory(h => h.map(c => c.id === activeChatId ? { ...c, messages: next } : c));
      } else if (next.length > 0) {
        const newId = Date.now().toString();
        const firstUserMsg = next.find(m => m.role === 'user');
        const titleText = firstUserMsg?.parts.find(p => p.text)?.text || 'New Pulse';
        setChatHistory([{ id: newId, title: titleText.slice(0, 30), messages: next, participants: ['You'] }, ...chatHistory]);
        setActiveChatId(newId);
      }
      return next;
    });
  };

  const handleNewChat = () => {
    setActiveChatId(null);
    setMessages([]);
    setMode('chat');
  };

  return (
    <div className="h-full w-full flex bg-white font-sans text-slate-900 overflow-hidden">
      <Sidebar 
        chatHistory={chatHistory} 
        activeChatId={activeChatId} 
        mode={mode}
        onSetMode={setMode}
        onSelectChat={(id) => { setActiveChatId(id); setMode('chat'); }}
        onNewChat={handleNewChat}
        onDeleteChat={() => {}}
        isSidebarOpen={isSidebarOpen}
        isSidebarCollapsed={isSidebarCollapsed}
        onToggleCollapse={() => setIsSidebarCollapsed(!isSidebarCollapsed)}
        onClose={() => setIsSidebarOpen(false)}
      />

      <div className="flex-1 flex flex-col h-full relative overflow-hidden">
        <header className="h-[80px] flex items-center justify-between px-10 border-b border-slate-50 bg-white shrink-0">
          <div className="flex items-center gap-6">
            <button onClick={() => setIsSidebarOpen(true)} className="p-2 -ml-2 text-black lg:hidden">
              <MenuIcon className="w-5 h-5"/>
            </button>
            <div className="flex items-center gap-4">
              <BotIcon className="w-8 h-8" />
              <div className="flex flex-col">
                <span className="text-[15px] font-bold text-black leading-none mb-1">CognixAi</span>
                <span className="text-[9px] font-bold text-[#94a3b8] uppercase tracking-widest leading-none">
                  {mode === 'chat' ? 'CORE CHAT MODE' : `${mode.toUpperCase()} MODE`}
                </span>
              </div>
            </div>
          </div>

          <div className="flex items-center gap-3">
            <button className="w-10 h-10 flex items-center justify-center rounded-full border border-slate-100 text-[#94a3b8] hover:text-black hover:bg-slate-50 transition-all">
              <MicrophoneIcon className="w-5 h-5" />
            </button>
            <button onClick={() => setIsSettingsOpen(true)} className="w-10 h-10 flex items-center justify-center rounded-full border border-slate-100 text-[#94a3b8] hover:text-black hover:bg-slate-50 transition-all">
              <UserIcon className="w-5 h-5" />
            </button>
          </div>
        </header>

        <main className="flex-1 relative overflow-hidden bg-white">
           {mode === 'chat' && (
              <ChatView 
                messages={messages} 
                setMessages={(val) => {
                  if (typeof val === 'function') handleUpdateMessages(val as any);
                  else handleUpdateMessages(() => val as any);
                }} 
                systemInstruction={systemInstruction} 
                model={activeModel} 
                setActiveModel={setActiveModel} 
                participants={['You']}
                onAddParticipant={() => {}}
                currentChat={currentChat}
                isSidebarCollapsed={isSidebarCollapsed}
                memories={memories}
              />
           )}
           {mode === 'toolbox' && <ToolboxView theme={THEME} model={activeModel} />}
           {mode === 'community' && <CommunityView theme={THEME} model={activeModel} />}
        </main>
      </div>

      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)} 
        isDarkMode={false}
        setIsDarkMode={() => {}}
        systemInstruction={systemInstruction} 
        setSystemInstruction={setSystemInstruction}
        memories={memories}
        setMemories={setMemories}
        onClearHistory={() => {}}
      />
    </div>
  );
}

export default App;

import React, { useState, useRef, useEffect, useCallback } from 'react';
import type { ChatMessage, ChatPart, ModelType, ChatSession, MemoryFact } from '../types';
import { GoogleGenAI } from "@google/genai";
import { SendIcon, AttachmentPlusIcon, BotIcon, UserIcon, BoltIcon } from './Icons';

interface ChatViewProps {
  messages: ChatMessage[];
  setMessages: React.Dispatch<React.SetStateAction<ChatMessage[]>>;
  systemInstruction: string;
  model: ModelType;
  setActiveModel: (m: ModelType) => void;
  participants: string[];
  onAddParticipant: (name: string) => void;
  currentChat?: ChatSession;
  isSidebarCollapsed?: boolean;
  memories?: MemoryFact[];
}

export const ChatView: React.FC<ChatViewProps> = ({ 
  messages, setMessages, systemInstruction, model, setActiveModel, currentChat, memories = []
}) => {
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [selectedImage, setSelectedImage] = useState<{ data: string; mimeType: string } | null>(null);

  const containerRef = useRef<HTMLDivElement>(null);
  const fileRef = useRef<HTMLInputElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  const hasMessages = messages.length > 0;

  useEffect(() => {
    if (containerRef.current) {
      containerRef.current.scrollTop = containerRef.current.scrollHeight;
    }
  }, [messages, isLoading]);

  const handleSend = useCallback(async () => {
    const trimmedInput = input.trim();
    if ((!trimmedInput && !selectedImage) || isLoading) return;

    const parts: ChatPart[] = [];
    if (selectedImage) parts.push({ inlineData: { mimeType: selectedImage.mimeType, data: selectedImage.data } });
    if (trimmedInput) parts.push({ text: trimmedInput });

    const userMsg: ChatMessage = { id: Date.now().toString(), role: 'user', parts };
    const botMsgId = (Date.now() + 1).toString();
    const botPlaceholder: ChatMessage = { id: botMsgId, role: 'model', parts: [{ text: '' }] };

    setMessages(prev => [...prev, userMsg, botPlaceholder]);
    setInput('');
    setSelectedImage(null);
    setIsLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const history = messages.slice(-6).map(m => ({
        role: m.role,
        parts: m.parts.map(p => p.text ? { text: p.text } : { inlineData: p.inlineData })
      }));

      const res = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: [...history, { role: 'user', parts: parts as any }],
        config: { systemInstruction }
      });

      const resText = res.text || "No output generated.";
      setMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, parts: [{ text: resText }] } : m));
    } catch (e) {
      setMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, parts: [{ text: "Neural link timeout. Please retry." }] } : m));
    } finally {
      setIsLoading(false);
    }
  }, [input, selectedImage, isLoading, messages, systemInstruction, setMessages]);

  return (
    <div className="h-full flex flex-col bg-white relative">
      <div 
        ref={containerRef} 
        className="flex-1 overflow-y-auto px-6 sm:px-12 md:px-24 lg:px-48 pb-64 pt-10 scroll-smooth custom-scrollbar"
      >
        {!hasMessages ? (
          <div className="h-full flex flex-col items-center justify-center select-none">
            <h2 className="text-[44px] font-bold text-[#0f172a] tracking-tight mb-2">How can I help you?</h2>
            <p className="text-[11px] font-bold text-[#94a3b8] uppercase tracking-[0.2em]">CognixAi Uplink Active</p>
          </div>
        ) : (
          <div className="max-w-4xl mx-auto space-y-12">
            {messages.map((m) => (
              <div key={m.id} className={`flex gap-6 ${m.role === 'user' ? 'flex-row-reverse' : 'flex-row'} animate-slide-up`}>
                <div className={`w-10 h-10 shrink-0 rounded-2xl flex items-center justify-center transition-all ${m.role === 'user' ? 'bg-[#0f172a]' : 'bg-slate-50 border border-slate-100 shadow-sm'}`}>
                   {m.role === 'user' ? <UserIcon className="w-5 h-5 text-white"/> : <BotIcon className="w-6 h-6 p-0.5"/>}
                </div>
                <div className={`flex flex-col gap-2 max-w-[85%] ${m.role === 'user' ? 'items-end' : 'items-start'}`}>
                  {m.parts.map((p, i) => (
                    <div key={i} className={`px-6 py-4 text-[16px] leading-[1.6] ${m.role === 'user' ? 'bg-[#f1f5f9] text-black rounded-3xl rounded-tr-sm' : 'bg-transparent text-[#334155] font-medium'}`}>
                      {p.text && <div className="whitespace-pre-wrap">{p.text}</div>}
                      {p.inlineData && <img src={`data:${p.inlineData.mimeType};base64,${p.inlineData.data}`} className="max-w-full h-auto rounded-2xl shadow-md border border-slate-100 mt-2" />}
                    </div>
                  ))}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* INPUT SYSTEM PILL */}
      <div className="absolute bottom-12 left-0 right-0 px-6 sm:px-12 md:px-24 lg:px-48 pointer-events-none">
        <div className="max-w-4xl mx-auto pointer-events-auto">
          <div className="relative bg-white border-[2px] border-blue-500 rounded-[3.5rem] p-4 shadow-[0_20px_60px_-15px_rgba(59,130,246,0.18)] flex flex-col gap-2 transition-all focus-within:shadow-[0_20px_60px_-15px_rgba(59,130,246,0.25)]">

            <div className="flex items-center gap-4 px-3 mb-1">
               <div className="flex items-center gap-1.5 px-2 py-0.5 rounded text-[10px] font-black text-[#64748b] uppercase tracking-widest cursor-pointer hover:bg-slate-50 transition-all">
                  <BoltIcon className="w-3.5 h-3.5"/>
                  COGNIXRV2
                  <span className="text-[8px] opacity-30">▾</span>
               </div>
               <div className="text-[10px] font-bold text-[#cbd5e1] uppercase tracking-widest">Live Search</div>
            </div>

            <div className="flex items-center gap-4 px-2">
                <button onClick={() => fileRef.current?.click()} className="w-10 h-10 shrink-0 flex items-center justify-center text-[#94a3b8] hover:text-blue-500 transition-all">
                    <AttachmentPlusIcon className="w-7 h-7" />
                    <input type="file" ref={fileRef} className="hidden" accept="image/*" onChange={(e) => {
                      const f = e.target.files?.[0];
                      if (f) {
                        const r = new FileReader();
                        r.onloadend = () => setSelectedImage({ data: (r.result as string).split(',')[1], mimeType: f.type });
                        r.readAsDataURL(f);
                      }
                    }} />
                </button>
                <textarea 
                  ref={textareaRef}
                  value={input} 
                  onChange={e => setInput(e.target.value)} 
                  onKeyDown={e => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSend())}
                  placeholder="Message CognixAi..." 
                  className="flex-1 bg-transparent border-none outline-none resize-none py-1 text-[18px] text-[#0f172a] placeholder-[#94a3b8] font-bold max-h-[120px] leading-tight" 
                  rows={1} 
                />
                <button 
                  onClick={handleSend}
                  disabled={isLoading || (!input.trim() && !selectedImage)}
                  className={`w-12 h-12 flex items-center justify-center rounded-full transition-all bg-[#dbeafe] text-blue-600 hover:bg-blue-600 hover:text-white disabled:opacity-20`}
                >
                  <SendIcon className="w-6 h-6 transform -rotate-15 ml-0.5" />
                </button>
            </div>

            {selectedImage && (
              <div className="px-14 pb-2">
                <div className="relative w-16 h-16 rounded-2xl overflow-hidden border-2 border-blue-500 shadow-md animate-fade-in">
                  <img src={`data:${selectedImage.mimeType};base64,${selectedImage.data}`} className="w-full h-full object-cover" />
                  <button onClick={() => setSelectedImage(null)} className="absolute top-0 right-0 bg-red-500 text-white w-5 h-5 flex items-center justify-center text-[10px] font-bold">×</button>
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

