import React from 'react';
import type { ChatSession, Mode } from '../types';
import { BotIcon, CoreChatIcon, LabIcon, CollectiveIcon } from './Icons';

interface SidebarProps {
  chatHistory: ChatSession[];
  activeChatId: string | null;
  mode: Mode;
  onSetMode: (mode: Mode) => void;
  onSelectChat: (id: string) => void;
  onNewChat: () => void;
  onDeleteChat: (id: string) => void;
  isSidebarOpen: boolean;
  isSidebarCollapsed: boolean;
  onToggleCollapse: () => void;
  onClose: () => void;
}

export const Sidebar: React.FC<SidebarProps> = ({ 
  chatHistory, activeChatId, mode, onSetMode, onSelectChat, onNewChat, isSidebarOpen, isSidebarCollapsed, onClose 
}) => {

  const NavItem: React.FC<{ m: Mode, icon: React.ReactNode, label: string }> = ({ m, icon, label }) => {
    const isActive = mode === m;
    return (
      <button
          onClick={() => { onSetMode(m); if(window.innerWidth < 1024) onClose(); }}
          className={`w-full flex items-center gap-4 px-4 py-2.5 rounded-xl transition-all duration-200
              ${isActive 
                  ? 'bg-black text-white' 
                  : 'text-[#64748b] hover:text-black hover:bg-slate-50'}
          `}
      >
          <span className="shrink-0">
            {React.isValidElement(icon) ? React.cloneElement(icon as React.ReactElement<any>, { className: 'w-5 h-5' }) : icon}
          </span>
          {!isSidebarCollapsed && <span className="text-[14px] font-bold tracking-tight">{label}</span>}
      </button>
    );
  };

  return (
    <>
      {isSidebarOpen && (
        <div className="fixed inset-0 bg-black/5 z-[60] lg:hidden" onClick={onClose} />
      )}
      <aside className={`fixed lg:static inset-y-0 left-0 z-[70] transition-all duration-300 h-full bg-white border-r border-slate-100 flex flex-col
        ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}
        ${isSidebarCollapsed ? 'w-20' : 'w-[280px]'}
      `}>
        <div className="p-6 flex flex-col h-full">
           <div className="flex items-center gap-3 mb-10 px-2 select-none">
              <BotIcon className="w-8 h-8" />
              {!isSidebarCollapsed && (
                <h2 className="text-[20px] font-bold tracking-tight text-black">CognixAi</h2>
              )}
           </div>

           <div className="space-y-2 mb-10">
              <nav className="space-y-1">
                <NavItem m="chat" icon={<CoreChatIcon />} label="Core Chat" />
                <NavItem m="toolbox" icon={<LabIcon />} label="Cognix Lab" />
                <NavItem m="community" icon={<CollectiveIcon />} label="Collective" />
              </nav>
           </div>

           <button 
             onClick={() => { onNewChat(); if(window.innerWidth < 1024) onClose(); }}
             className={`w-full flex items-center justify-center py-4 bg-[#f1f5f9] text-black rounded-2xl font-bold text-[14px] transition-all hover:bg-[#e2e8f0] mb-12`}
           >
             {!isSidebarCollapsed ? "New Pulse" : "+"}
           </button>

           {!isSidebarCollapsed && (
             <div className="flex-1 flex flex-col min-h-0">
                <div className="px-2 mb-4">
                  <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Recent Pulses</h3>
                </div>
                <div className="flex-1 overflow-y-auto space-y-1 pr-1 custom-scrollbar pb-6">
                  {chatHistory.map((chat) => (
                    <button 
                      key={chat.id}
                      onClick={() => { onSelectChat(chat.id); onSetMode('chat'); if(window.innerWidth < 1024) onClose(); }}
                      className={`w-full text-left px-4 py-2.5 rounded-xl transition-all flex items-center justify-between
                        ${activeChatId === chat.id && mode === 'chat' 
                          ? 'bg-[#f8fafc] text-black font-semibold border border-slate-100' 
                          : 'text-[#64748b] hover:text-black hover:bg-slate-50'}
                      `}
                    >
                      <span className="text-[13px] truncate">{chat.title}</span>
                    </button>
                  ))}
                </div>
             </div>
           )}

           <div className={`pt-4 border-t border-slate-100 mt-auto ${isSidebarCollapsed ? 'hidden' : ''}`}>
              <div className="flex items-center justify-between p-3 rounded-2xl bg-[#f8fafc] border border-slate-100">
                <div className="flex items-center gap-3">
                  <div className="w-2 h-2 rounded-full bg-blue-500 shadow-[0_0_8px_rgba(59,130,246,0.6)]"></div>
                  <span className="text-[10px] font-bold text-[#64748b] uppercase tracking-widest">Neural Link</span>
                </div>
                <span className="text-[10px] font-bold text-slate-400">11.2</span>
              </div>
           </div>
        </div>
      </aside>
    </>
  );
};

import React, { useState, useRef, useEffect, useCallback } from 'react';
import type { ChatMessage, ChatPart, ModelType, ChatSession, MemoryFact } from '../types';
import { GoogleGenAI } from "@google/genai";
import { SendIcon, AttachmentPlusIcon, BotIcon, UserIcon, BoltIcon } from './Icons';

interface ChatViewProps {
  messages: ChatMessage[];
  setMessages: React.Dispatch<React.SetStateAction<ChatMessage[]>>;
  systemInstruction: string;
  model: ModelType;
  setActiveModel: (m: ModelType) => void;
  participants: string[];
  onAddParticipant: (name: string) => void;
  currentChat?: ChatSession;
  isSidebarCollapsed?: boolean;
  memories?: MemoryFact[];
}

export const ChatView: React.FC<ChatViewProps> = ({ 
  messages, setMessages, systemInstruction, model, setActiveModel, currentChat, memories = []
}) => {
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [selectedImage, setSelectedImage] = useState<{ data: string; mimeType: string } | null>(null);

  const containerRef = useRef<HTMLDivElement>(null);
  const fileRef = useRef<HTMLInputElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  const hasMessages = messages.length > 0;

  useEffect(() => {
    if (containerRef.current) {
      containerRef.current.scrollTop = containerRef.current.scrollHeight;
    }
  }, [messages, isLoading]);

  const handleSend = useCallback(async () => {
    const trimmedInput = input.trim();
    if ((!trimmedInput && !selectedImage) || isLoading) return;

    const parts: ChatPart[] = [];
    if (selectedImage) parts.push({ inlineData: { mimeType: selectedImage.mimeType, data: selectedImage.data } });
    if (trimmedInput) parts.push({ text: trimmedInput });

    const userMsg: ChatMessage = { id: Date.now().toString(), role: 'user', parts };
    const botMsgId = (Date.now() + 1).toString();
    const botPlaceholder: ChatMessage = { id: botMsgId, role: 'model', parts: [{ text: '' }] };

    setMessages(prev => [...prev, userMsg, botPlaceholder]);
    setInput('');
    setSelectedImage(null);
    setIsLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const history = messages.slice(-10).map(m => ({
        role: m.role,
        parts: m.parts.map(p => p.text ? { text: p.text } : { inlineData: p.inlineData })
      }));

      const res = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: [...history, { role: 'user', parts: parts as any }],
        config: { systemInstruction }
      });

      const resText = res.text || "No response received.";
      setMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, parts: [{ text: resText }] } : m));
    } catch (e) {
      setMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, parts: [{ text: "Neural link timeout. Please retry." }] } : m));
    } finally {
      setIsLoading(false);
    }
  }, [input, selectedImage, isLoading, messages, systemInstruction, setMessages]);

  return (
    <div className="h-full flex flex-col bg-white relative">
      <div 
        ref={containerRef} 
        className="flex-1 overflow-y-auto px-6 sm:px-12 md:px-24 lg:px-48 pb-64 pt-10 scroll-smooth custom-scrollbar"
      >
        {!hasMessages ? (
          <div className="h-full flex flex-col items-center justify-center select-none">
            <h2 className="text-[44px] font-bold text-[#0f172a] tracking-tight mb-2">How can I help you?</h2>
            <p className="text-[11px] font-bold text-[#94a3b8] uppercase tracking-[0.2em]">CognixAi Uplink Active</p>
          </div>
        ) : (
          <div className="max-w-4xl mx-auto space-y-12">
            {messages.map((m) => (
              <div key={m.id} className={`flex gap-6 ${m.role === 'user' ? 'flex-row-reverse' : 'flex-row'} items-start animate-slide-up`}>
                <div className={`w-10 h-10 shrink-0 rounded-2xl flex items-center justify-center transition-all ${m.role === 'user' ? 'bg-[#0f172a]' : 'bg-white border border-slate-100 shadow-sm'}`}>
                   {m.role === 'user' ? <UserIcon className="w-5 h-5 text-white"/> : <BotIcon className="w-7 h-7 p-0.5"/>}
                </div>
                <div className={`flex flex-col gap-2 max-w-[85%] ${m.role === 'user' ? 'items-end' : 'items-start'}`}>
                  {m.parts.map((p, i) => (
                    <div key={i} className={`${m.role === 'user' ? 'bg-[#f1f5f9] text-[#1e293b] rounded-3xl px-6 py-3 font-semibold text-[15px]' : 'text-[#334155] font-medium text-[16px] leading-relaxed pt-2'}`}>
                      {p.text && <div className="whitespace-pre-wrap">{p.text}</div>}
                      {p.inlineData && <img src={`data:${p.inlineData.mimeType};base64,${p.inlineData.data}`} className="max-w-full h-auto rounded-3xl shadow-sm border border-slate-100 mt-3" />}
                    </div>
                  ))}
                </div>
              </div>
            ))}
            {isLoading && messages[messages.length-1]?.role === 'user' && (
              <div className="flex gap-6 animate-pulse">
                <div className="w-10 h-10 shrink-0 rounded-2xl bg-white border border-slate-100 flex items-center justify-center">
                  <BotIcon className="w-7 h-7 opacity-30"/>
                </div>
                <div className="flex items-center gap-1.5 py-4">
                  <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce"></div>
                  <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce delay-100"></div>
                  <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce delay-200"></div>
                </div>
              </div>
            )}
          </div>
        )}
      </div>

      {/* REFINED INPUT SYSTEM PILL */}
      <div className="absolute bottom-10 left-0 right-0 px-6 sm:px-12 md:px-24 lg:px-48 pointer-events-none">
        <div className="max-w-4xl mx-auto pointer-events-auto">
          <div className="relative bg-white border-[2px] border-[#3b82f6] rounded-[3.5rem] px-5 py-4 shadow-[0_20px_70px_-20px_rgba(59,130,246,0.2)] flex flex-col gap-3 transition-all focus-within:shadow-[0_20px_70px_-20px_rgba(59,130,246,0.3)]">

            {/* Top Row: Functional Controls */}
            <div className="flex items-center gap-5 px-3">
               <div className="flex items-center gap-2 px-3 py-1.5 bg-white border border-[#f1f5f9] rounded-xl text-[10px] font-black text-[#64748b] uppercase tracking-widest cursor-pointer hover:bg-slate-50 transition-all shadow-sm group">
                  <CoreChatIcon className="w-4 h-4 text-slate-300 group-hover:text-blue-500" />
                  <span>CLORAV1</span>
                  <span className="text-[10px] text-slate-300 ml-1">▾</span>
               </div>
               <div className="flex items-center gap-3">
                  <div className="text-[10px] font-black text-[#bfdbfe] uppercase tracking-[0.2em] py-1.5 border-b-2 border-[#bfdbfe]">LIVE SEARCH</div>
               </div>
            </div>

            {/* Bottom Row: Message Input */}
            <div className="flex items-center gap-4">
                <button onClick={() => fileRef.current?.click()} className="w-10 h-10 shrink-0 flex items-center justify-center text-[#94a3b8] hover:text-blue-500 transition-all">
                    <AttachmentPlusIcon className="w-8 h-8 opacity-70" />
                    <input type="file" ref={fileRef} className="hidden" accept="image/*" onChange={(e) => {
                      const f = e.target.files?.[0];
                      if (f) {
                        const r = new FileReader();
                        r.onloadend = () => setSelectedImage({ data: (r.result as string).split(',')[1], mimeType: f.type });
                        r.readAsDataURL(f);
                      }
                    }} />
                </button>
                <textarea 
                  ref={textareaRef}
                  value={input} 
                  onChange={e => {
                    setInput(e.target.value);
                    e.target.style.height = 'auto';
                    e.target.style.height = Math.min(e.target.scrollHeight, 120) + 'px';
                  }} 
                  onKeyDown={e => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSend())}
                  placeholder="Message CognixAi..." 
                  className="flex-1 bg-transparent border-none outline-none resize-none py-2 text-[19px] text-[#1e293b] placeholder-[#94a3b8] font-semibold max-h-[120px] leading-snug" 
                  rows={1} 
                />
                <button 
                  onClick={handleSend}
                  disabled={isLoading || (!input.trim() && !selectedImage)}
                  className={`w-[52px] h-[52px] flex items-center justify-center rounded-full transition-all bg-[#eef4ff] text-[#3b82f6] hover:bg-[#3b82f6] hover:text-white disabled:opacity-20 active:scale-95 shadow-sm`}
                >
                  <SendIcon className="w-7 h-7" />
                </button>
            </div>

            {selectedImage && (
              <div className="px-14 pb-2">
                <div className="relative w-16 h-16 rounded-2xl overflow-hidden border-2 border-blue-500 shadow-md animate-fade-in">
                  <img src={`data:${selectedImage.mimeType};base64,${selectedImage.data}`} className="w-full h-full object-cover" />
                  <button onClick={() => setSelectedImage(null)} className="absolute top-0 right-0 bg-red-500 text-white w-5 h-5 flex items-center justify-center text-[10px] font-bold">×</button>
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

