import React from 'react';
import type { ChatSession, Mode } from '../types';
import { BotIcon, CoreChatIcon, LabIcon, CollectiveIcon } from './Icons';

interface SidebarProps {
  chatHistory: ChatSession[];
  activeChatId: string | null;
  mode: Mode;
  onSetMode: (mode: Mode) => void;
  onSelectChat: (id: string) => void;
  onNewChat: () => void;
  onDeleteChat: (id: string) => void;
  isSidebarOpen: boolean;
  isSidebarCollapsed: boolean;
  onToggleCollapse: () => void;
  onClose: () => void;
}

export const Sidebar: React.FC<SidebarProps> = ({ 
  chatHistory, activeChatId, mode, onSetMode, onSelectChat, onNewChat, isSidebarOpen, isSidebarCollapsed, onClose 
}) => {

  const NavItem: React.FC<{ m: Mode, icon: React.ReactNode, label: string }> = ({ m, icon, label }) => {
    const isActive = mode === m;
    return (
      <button
          onClick={() => { onSetMode(m); if(window.innerWidth < 1024) onClose(); }}
          className={`w-full flex items-center gap-4 px-4 py-2.5 rounded-xl transition-all duration-200
              ${isActive 
                  ? 'bg-black text-white' 
                  : 'text-[#64748b] hover:text-black hover:bg-slate-50'}
          `}
      >
          <span className="shrink-0">
            {React.isValidElement(icon) ? React.cloneElement(icon as React.ReactElement<any>, { className: 'w-5 h-5' }) : icon}
          </span>
          {!isSidebarCollapsed && <span className="text-[14px] font-bold tracking-tight">{label}</span>}
      </button>
    );
  };

  return (
    <>
      {isSidebarOpen && (
        <div className="fixed inset-0 bg-black/5 z-[60] lg:hidden" onClick={onClose} />
      )}
      <aside className={`fixed lg:static inset-y-0 left-0 z-[70] transition-all duration-300 h-full bg-white border-r border-slate-100 flex flex-col
        ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}
        ${isSidebarCollapsed ? 'w-20' : 'w-[280px]'}
      `}>
        <div className="p-6 flex flex-col h-full">
           <div className="flex items-center gap-3 mb-10 px-2 select-none">
              <BotIcon className="w-10 h-10" />
              {!isSidebarCollapsed && (
                <h2 className="text-[20px] font-bold tracking-tight text-black">CognixAi</h2>
              )}
           </div>

           <div className="space-y-2 mb-10">
              <nav className="space-y-1">
                <NavItem m="chat" icon={<CoreChatIcon />} label="Core Chat" />
                <NavItem m="toolbox" icon={<LabIcon />} label="Cognix Lab" />
                <NavItem m="community" icon={<CollectiveIcon />} label="Collective" />
              </nav>
           </div>

           <button 
             onClick={() => { onNewChat(); if(window.innerWidth < 1024) onClose(); }}
             className={`w-full flex items-center justify-center py-4 bg-[#f1f5f9] text-black rounded-2xl font-bold text-[14px] transition-all hover:bg-[#e2e8f0] mb-12`}
           >
             {!isSidebarCollapsed ? "New Pulse" : "+"}
           </button>

           {!isSidebarCollapsed && (
             <div className="flex-1 flex flex-col min-h-0">
                <div className="px-2 mb-4">
                  <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Recent Pulses</h3>
                </div>
                <div className="flex-1 overflow-y-auto space-y-1 pr-1 custom-scrollbar pb-6">
                  {chatHistory.map((chat) => (
                    <button 
                      key={chat.id}
                      onClick={() => { onSelectChat(chat.id); onSetMode('chat'); if(window.innerWidth < 1024) onClose(); }}
                      className={`w-full text-left px-4 py-2.5 rounded-xl transition-all flex items-center justify-between
                        ${activeChatId === chat.id && mode === 'chat' 
                          ? 'bg-[#f8fafc] text-black font-semibold border border-slate-100' 
                          : 'text-[#64748b] hover:text-black hover:bg-slate-50'}
                      `}
                    >
                      <span className="text-[13px] truncate">{chat.title}</span>
                    </button>
                  ))}
                </div>
             </div>
           )}

           <div className={`pt-4 border-t border-slate-100 mt-auto ${isSidebarCollapsed ? 'hidden' : ''}`}>
              <div className="flex items-center justify-between p-3 rounded-2xl bg-[#f8fafc] border border-slate-100">
                <div className="flex items-center gap-3">
                  <div className="w-2 h-2 rounded-full bg-blue-500 shadow-[0_0_8px_rgba(59,130,246,0.6)]"></div>
                  <span className="text-[10px] font-bold text-[#64748b] uppercase tracking-widest">Neural Link</span>
                </div>
                <span className="text-[10px] font-bold text-slate-400">11.2</span>
              </div>
           </div>
        </div>
      </aside>
    </>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { ChatView } from './components/ChatView';
import { LiveView } from './components/LiveView';
import { Sidebar } from './components/Sidebar';
import { CommunityView } from './components/CommunityView';
import { ToolboxView } from './components/ToolboxView';
import { MenuIcon, BotIcon, UserIcon, MicrophoneIcon } from './components/Icons';
import { SettingsModal } from './components/SettingsModal';
import type { ChatMessage, ChatSession, Mode, ThemeColors, ModelType, MemoryFact } from './types';

const THEME: ThemeColors = {
    primary: 'bg-black',
    primaryHover: 'hover:opacity-90',
    text: 'text-black',
    textDark: 'text-white',
    bgSoft: 'bg-slate-50',
    darkBgSoft: 'dark:bg-slate-900',
    border: 'border-slate-200',
    ring: 'focus:ring-black',
    gradient: 'bg-black'
};

const App: React.FC = () => {
  const [mode, setMode] = useState<Mode>('chat');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [activeModel, setActiveModel] = useState<ModelType>('cognix-rv2');
  const [systemInstruction, setSystemInstruction] = useState("Hello there! I am CognixAi, a high-performance assistant created by Shashwat Ranjan Jha. Use plain text mostly, no excessive bolding, and friendly emojis. I am sleek, private, and powered by Gemini 3 series intelligence.");

  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [chatHistory, setChatHistory] = useState<ChatSession[]>([]);
  const [activeChatId, setActiveChatId] = useState<string | null>(null);
  const [memories, setMemories] = useState<MemoryFact[]>([]);

  const currentChat = useMemo(() => chatHistory.find(c => c.id === activeChatId), [chatHistory, activeChatId]);

  useEffect(() => {
    const savedHistory = localStorage.getItem('cognix_v8_history');
    if (savedHistory) setChatHistory(JSON.parse(savedHistory));
  }, []);

  const handleUpdateMessages = (updater: (prev: ChatMessage[]) => ChatMessage[]) => {
    setMessages(prev => {
      const next = updater(prev);
      if (activeChatId) {
        setChatHistory(h => h.map(c => c.id === activeChatId ? { ...c, messages: next } : c));
      } else if (next.length > 0) {
        const newId = Date.now().toString();
        const firstUserMsg = next.find(m => m.role === 'user');
        const titleText = firstUserMsg?.parts.find(p => p.text)?.text || 'New Pulse';
        setChatHistory([{ id: newId, title: titleText.slice(0, 30), messages: next, participants: ['You'] }, ...chatHistory]);
        setActiveChatId(newId);
      }
      return next;
    });
  };

  const handleNewChat = () => {
    setActiveChatId(null);
    setMessages([]);
    setMode('chat');
  };

  return (
    <div className="h-full w-full flex bg-white font-sans text-slate-900 overflow-hidden">
      <Sidebar 
        chatHistory={chatHistory} 
        activeChatId={activeChatId} 
        mode={mode}
        onSetMode={setMode}
        onSelectChat={(id) => { setActiveChatId(id); setMode('chat'); }}
        onNewChat={handleNewChat}
        onDeleteChat={() => {}}
        isSidebarOpen={isSidebarOpen}
        isSidebarCollapsed={isSidebarCollapsed}
        onToggleCollapse={() => setIsSidebarCollapsed(!isSidebarCollapsed)}
        onClose={() => setIsSidebarOpen(false)}
      />

      <div className="flex-1 flex flex-col h-full relative overflow-hidden">
        <header className="h-[80px] flex items-center justify-between px-10 border-b border-slate-50 bg-white shrink-0">
          <div className="flex items-center gap-6">
            <button onClick={() => setIsSidebarOpen(true)} className="p-2 -ml-2 text-black lg:hidden">
              <MenuIcon className="w-5 h-5"/>
            </button>
            <div className="flex items-center gap-4">
              <BotIcon className="w-10 h-10" />
              <div className="flex flex-col">
                <span className="text-[15px] font-bold text-black leading-none mb-1">CognixAi</span>
                <span className="text-[9px] font-bold text-[#94a3b8] uppercase tracking-widest leading-none">
                  {mode === 'chat' ? 'CORE CHAT MODE' : `${mode.toUpperCase()} MODE`}
                </span>
              </div>
            </div>
          </div>

          <div className="flex items-center gap-3">
            <button className="w-10 h-10 flex items-center justify-center rounded-full border border-slate-100 text-[#94a3b8] hover:text-black hover:bg-slate-50 transition-all">
              <MicrophoneIcon className="w-5 h-5" />
            </button>
            <button onClick={() => setIsSettingsOpen(true)} className="w-10 h-10 flex items-center justify-center rounded-full border border-slate-100 text-[#94a3b8] hover:text-black hover:bg-slate-50 transition-all">
              <UserIcon className="w-5 h-5" />
            </button>
          </div>
        </header>

        <main className="flex-1 relative overflow-hidden bg-white">
           {mode === 'chat' && (
              <ChatView 
                messages={messages} 
                setMessages={(val) => {
                  if (typeof val === 'function') handleUpdateMessages(val as any);
                  else handleUpdateMessages(() => val as any);
                }} 
                systemInstruction={systemInstruction} 
                model={activeModel} 
                setActiveModel={setActiveModel} 
                participants={['You']}
                onAddParticipant={() => {}}
                currentChat={currentChat}
                isSidebarCollapsed={isSidebarCollapsed}
                memories={memories}
              />
           )}
           {mode === 'toolbox' && <ToolboxView theme={THEME} model={activeModel} />}
           {mode === 'community' && <CommunityView theme={THEME} model={activeModel} />}
        </main>
      </div>

      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)} 
        isDarkMode={false}
        setIsDarkMode={() => {}}
        systemInstruction={systemInstruction} 
        setSystemInstruction={setSystemInstruction}
        memories={memories}
        setMemories={setMemories}
        onClearHistory={() => {}}
      />
    </div>
  );
}

export default App;

