export type Mode = 'chat' | 'live' | 'toolbox' | 'community';
export type UIStyle = 'modern' | 'glass' | 'brutal' | 'retro';
export type AccentColor = 'blue' | 'violet' | 'emerald' | 'rose' | 'amber';
export type FontSize = 'small' | 'normal' | 'large';

export type ModelType = 
  | 'cognix-rv2'      // gemini-3-flash-preview (Fast/Friendly)
  | 'clora-v1'       // gemini-3-pro-preview (Reasoning)
  | 'clorea-v2.5'    // gemini-flash-lite-latest (Lightweight)
  | 'arctic-x';       // gemini-3-pro-preview (Coding)

export interface Friend {
  id: string;
  name: string;
  avatar: string;
  status: 'online' | 'offline' | 'busy' | 'away';
}

export interface Deployment {
  id: string;
  title: string;
  code: string;
  timestamp: number;
}

export interface CommunityPost {
    id: string;
    author: string;
    authorId: string;
    content: string;
    timestamp: number;
    likedBy: string[];
    replies: any[];
    type: 'text' | 'image' | 'code';
}

export interface MemoryFact {
    id: string;
    category: 'preference' | 'project' | 'personal' | 'work';
    content: string;
    timestamp: string;
}

export interface ThemeColors {
    primary: string;
    primaryHover: string;
    text: string;
    textDark: string;
    bgSoft: string;
    darkBgSoft: string;
    border: string;
    ring: string;
    gradient: string;
}

export interface ChatPart {
  text?: string;
  inlineData?: {
    mimeType: string;
    data: string;
  };
  searchResults?: any[];
}

export interface ChatMessage {
  id: string;
  role: 'user' | 'model';
  parts: ChatPart[];
  isSearching?: boolean;
}

export interface ChatSession {
  id:string;
  title: string;
  messages: ChatMessage[];
  participants: string[]; 
}

import React, { useState, useEffect, useMemo } from 'react';
import { ChatView } from './components/ChatView';
import { LiveView } from './components/LiveView';
import { Sidebar } from './components/Sidebar';
import { CommunityView } from './components/CommunityView';
import { ToolboxView } from './components/ToolboxView';
import { MenuIcon, BotIcon, UserIcon, MicrophoneIcon } from './components/Icons';
import { SettingsModal } from './components/SettingsModal';
import type { ChatMessage, ChatSession, Mode, ThemeColors, ModelType, MemoryFact } from './types';

const THEME: ThemeColors = {
    primary: 'bg-black',
    primaryHover: 'hover:opacity-90',
    text: 'text-black',
    textDark: 'text-white',
    bgSoft: 'bg-slate-50',
    darkBgSoft: 'dark:bg-slate-900',
    border: 'border-slate-200',
    ring: 'focus:ring-black',
    gradient: 'bg-black'
};

const App: React.FC = () => {
  const [mode, setMode] = useState<Mode>('chat');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [activeModel, setActiveModel] = useState<ModelType>('cognix-rv2');
  const [systemInstruction, setSystemInstruction] = useState("Hello there! I am CognixAi, a high-performance assistant created by Shashwat Ranjan Jha. Use plain text mostly, no excessive bolding, and friendly emojis. I am sleek, private, and powered by Gemini 3 series intelligence.");

  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [chatHistory, setChatHistory] = useState<ChatSession[]>([]);
  const [activeChatId, setActiveChatId] = useState<string | null>(null);
  const [memories, setMemories] = useState<MemoryFact[]>([]);

  const currentChat = useMemo(() => chatHistory.find(c => c.id === activeChatId), [chatHistory, activeChatId]);

  useEffect(() => {
    const savedHistory = localStorage.getItem('cognix_v8_history');
    if (savedHistory) setChatHistory(JSON.parse(savedHistory));
  }, []);

  const handleUpdateMessages = (updater: (prev: ChatMessage[]) => ChatMessage[]) => {
    setMessages(prev => {
      const next = updater(prev);
      if (activeChatId) {
        setChatHistory(h => h.map(c => c.id === activeChatId ? { ...c, messages: next } : c));
      } else if (next.length > 0) {
        const newId = Date.now().toString();
        const firstUserMsg = next.find(m => m.role === 'user');
        const titleText = firstUserMsg?.parts.find(p => p.text)?.text || 'New Pulse';
        setChatHistory([{ id: newId, title: titleText.slice(0, 30), messages: next, participants: ['You'] }, ...chatHistory]);
        setActiveChatId(newId);
      }
      return next;
    });
  };

  const handleNewChat = () => {
    setActiveChatId(null);
    setMessages([]);
    setMode('chat');
  };

  return (
    <div className="h-full w-full flex bg-white font-sans text-slate-900 overflow-hidden">
      <Sidebar 
        chatHistory={chatHistory} 
        activeChatId={activeChatId} 
        mode={mode}
        onSetMode={setMode}
        onSelectChat={(id) => { setActiveChatId(id); setMode('chat'); }}
        onNewChat={handleNewChat}
        onDeleteChat={() => {}}
        isSidebarOpen={isSidebarOpen}
        isSidebarCollapsed={isSidebarCollapsed}
        onToggleCollapse={() => setIsSidebarCollapsed(!isSidebarCollapsed)}
        onClose={() => setIsSidebarOpen(false)}
      />

      <div className="flex-1 flex flex-col h-full relative overflow-hidden">
        <header className="h-[80px] flex items-center justify-between px-10 border-b border-slate-50 bg-white shrink-0">
          <div className="flex items-center gap-6">
            <button onClick={() => setIsSidebarOpen(true)} className="p-2 -ml-2 text-black lg:hidden">
              <MenuIcon className="w-5 h-5"/>
            </button>
            <div className="flex items-center gap-4">
              <BotIcon className="w-10 h-10" />
              <div className="flex flex-col">
                <span className="text-[13px] font-bold text-black leading-none mb-1">CognixAi</span>
                <span className="text-[9px] font-bold text-[#94a3b8] uppercase tracking-widest leading-none">
                  {mode === 'chat' ? 'CORE CHAT MODE' : `${mode.toUpperCase()} MODE`}
                </span>
              </div>
            </div>
          </div>

          <div className="flex items-center gap-3">
            <button className="w-10 h-10 flex items-center justify-center rounded-full border border-slate-100 text-[#94a3b8] hover:text-black hover:bg-slate-50 transition-all">
              <MicrophoneIcon className="w-5 h-5" />
            </button>
            <button onClick={() => setIsSettingsOpen(true)} className="w-10 h-10 flex items-center justify-center rounded-full border border-slate-100 text-[#94a3b8] hover:text-black hover:bg-slate-50 transition-all">
              <UserIcon className="w-5 h-5" />
            </button>
          </div>
        </header>

        <main className="flex-1 relative overflow-hidden bg-white">
           {mode === 'chat' && (
              <ChatView 
                messages={messages} 
                setMessages={(val) => {
                  if (typeof val === 'function') handleUpdateMessages(val as any);
                  else handleUpdateMessages(() => val as any);
                }} 
                systemInstruction={systemInstruction} 
                model={activeModel} 
                setActiveModel={setActiveModel} 
                participants={['You']}
                onAddParticipant={() => {}}
                currentChat={currentChat}
                isSidebarCollapsed={isSidebarCollapsed}
                memories={memories}
              />
           )}
           {mode === 'toolbox' && <ToolboxView theme={THEME} model={activeModel} />}
           {mode === 'community' && <CommunityView theme={THEME} model={activeModel} />}
        </main>
      </div>

      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)} 
        isDarkMode={false}
        setIsDarkMode={() => {}}
        systemInstruction={systemInstruction} 
        setSystemInstruction={setSystemInstruction}
        memories={memories}
        setMemories={setMemories}
        onClearHistory={() => {}}
      />
    </div>
  );
}

export default App;

import React, { useState, useRef, useEffect, useCallback } from 'react';
import type { ChatMessage, ChatPart, ModelType, ChatSession, MemoryFact } from '../types';
import { GoogleGenAI } from "@google/genai";
import { SendIcon, AttachmentPlusIcon, BotIcon, UserIcon, CoreChatIcon, SearchIcon, SparklesIcon } from './Icons';

interface ChatViewProps {
  messages: ChatMessage[];
  setMessages: React.Dispatch<React.SetStateAction<ChatMessage[]>>;
  systemInstruction: string;
  model: ModelType;
  setActiveModel: (m: ModelType) => void;
  participants: string[];
  onAddParticipant: (name: string) => void;
  currentChat?: ChatSession;
  isSidebarCollapsed?: boolean;
  memories?: MemoryFact[];
}

const MODEL_MAP: Record<ModelType, string> = {
  'cognix-rv2': 'gemini-3-flash-preview',
  'clora-v1': 'gemini-3-pro-preview',
  'clorea-v2.5': 'gemini-flash-lite-latest',
  'arctic-x': 'gemini-3-pro-preview'
};

const MODEL_LABELS: Record<ModelType, string> = {
  'cognix-rv2': 'COGNIX R-V2',
  'clora-v1': 'CLORA V1',
  'clorea-v2.5': 'CLOREA V2.5',
  'arctic-x': 'ARCTIC X'
};

export const ChatView: React.FC<ChatViewProps> = ({ 
  messages, setMessages, systemInstruction, model, setActiveModel, currentChat, memories = []
}) => {
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isSearchEnabled, setIsSearchEnabled] = useState(false);
  const [selectedImage, setSelectedImage] = useState<{ data: string; mimeType: string } | null>(null);
  const [showModelMenu, setShowModelMenu] = useState(false);

  const containerRef = useRef<HTMLDivElement>(null);
  const fileRef = useRef<HTMLInputElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  const hasMessages = messages.length > 0;

  useEffect(() => {
    if (containerRef.current) {
      containerRef.current.scrollTop = containerRef.current.scrollHeight;
    }
  }, [messages, isLoading]);

  const handleSend = useCallback(async () => {
    const trimmedInput = input.trim();
    if ((!trimmedInput && !selectedImage) || isLoading) return;

    const parts: ChatPart[] = [];
    if (selectedImage) parts.push({ inlineData: { mimeType: selectedImage.mimeType, data: selectedImage.data } });
    if (trimmedInput) parts.push({ text: trimmedInput });

    const userMsg: ChatMessage = { id: Date.now().toString(), role: 'user', parts };
    const botMsgId = (Date.now() + 1).toString();
    const botPlaceholder: ChatMessage = { id: botMsgId, role: 'model', parts: [{ text: '' }] };

    setMessages(prev => [...prev, userMsg, botPlaceholder]);
    setInput('');
    setSelectedImage(null);
    setIsLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const history = messages.slice(-10).map(m => ({
        role: m.role,
        parts: m.parts.map(p => p.text ? { text: p.text } : { inlineData: p.inlineData })
      }));

      const tools: any[] = [];
      if (isSearchEnabled) {
        tools.push({ googleSearch: {} });
      }

      const res = await ai.models.generateContent({
        model: MODEL_MAP[model] || 'gemini-3-flash-preview',
        contents: [...history, { role: 'user', parts: parts as any }],
        config: { 
          systemInstruction: systemInstruction + (model === 'arctic-x' ? " Focus heavily on code output." : ""),
          tools: tools.length > 0 ? tools : undefined
        }
      });

      const resText = res.text || "No response received.";
      const groundingChunks = res.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
      const sources = groundingChunks
        .filter((chunk: any) => chunk.web)
        .map((chunk: any) => ({ uri: chunk.web.uri, title: chunk.web.title }));

      setMessages(prev => prev.map(m => m.id === botMsgId ? { 
        ...m, 
        parts: [{ 
          text: resText,
          searchResults: sources.length > 0 ? sources : undefined
        }] 
      } : m));
    } catch (e) {
      setMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, parts: [{ text: "Neural link timeout. Please retry." }] } : m));
    } finally {
      setIsLoading(false);
    }
  }, [input, selectedImage, isLoading, messages, systemInstruction, setMessages, model, isSearchEnabled]);

  return (
    <div className="h-full flex flex-col bg-white relative">
      <div 
        ref={containerRef} 
        className="flex-1 overflow-y-auto px-6 sm:px-12 md:px-24 lg:px-48 pb-64 pt-10 scroll-smooth custom-scrollbar"
      >
        {!hasMessages ? (
          <div className="h-full flex flex-col items-center justify-center select-none">
            <h2 className="text-[34px] font-bold text-[#0f172a] tracking-tight mb-2">How can I help you?</h2>
            <p className="text-[10px] font-bold text-[#94a3b8] uppercase tracking-[0.2em]">CognixAi Neural Link Active</p>
          </div>
        ) : (
          <div className="max-w-4xl mx-auto space-y-8">
            {messages.map((m) => (
              <div key={m.id} className={`flex gap-4 ${m.role === 'user' ? 'flex-row-reverse' : 'flex-row'} items-start animate-slide-up`}>
                <div className={`w-10 h-10 shrink-0 rounded-2xl flex items-center justify-center transition-all ${m.role === 'user' ? 'bg-[#0f172a]' : 'bg-white border border-slate-100 shadow-sm'}`}>
                   {m.role === 'user' ? <UserIcon className="w-5 h-5 text-white"/> : <BotIcon className="w-8 h-8 p-0.5"/>}
                </div>
                <div className={`flex flex-col gap-1.5 max-w-[85%] ${m.role === 'user' ? 'items-end' : 'items-start'}`}>
                  {m.parts.map((p, i) => (
                    <div key={i} className={`${m.role === 'user' ? 'bg-[#f1f5f9] text-[#1e293b] rounded-2xl px-5 py-2.5 font-semibold text-[14px]' : 'text-[#334155] font-medium text-[14px] leading-relaxed pt-1'}`}>
                      {p.text && <div className="whitespace-pre-wrap">{p.text}</div>}
                      {p.inlineData && <img src={`data:${p.inlineData.mimeType};base64,${p.inlineData.data}`} className="max-w-full h-auto rounded-2xl shadow-sm border border-slate-100 mt-2" />}

                      {p.searchResults && p.searchResults.length > 0 && (
                        <div className="mt-3 flex flex-wrap gap-2">
                          <p className="w-full text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-1 flex items-center gap-1">
                            <SearchIcon className="w-3 h-3" /> Grounded Sources
                          </p>
                          {p.searchResults.map((source: any, idx: number) => (
                            <a 
                              key={idx} 
                              href={source.uri} 
                              target="_blank" 
                              rel="noopener noreferrer"
                              className="px-2.5 py-1 bg-slate-50 border border-slate-200 rounded-lg text-[10px] font-bold text-blue-600 hover:bg-blue-50 transition-colors flex items-center gap-1"
                            >
                              {source.title || "Reference"}
                              <svg className="w-2.5 h-2.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6M15 3h6v6M10 14L21 3" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"/></svg>
                            </a>
                          ))}
                        </div>
                      )}
                    </div>
                  ))}
                </div>
              </div>
            ))}
            {isLoading && messages[messages.length-1]?.role === 'user' && (
              <div className="flex gap-4 animate-pulse">
                <div className="w-10 h-10 shrink-0 rounded-2xl bg-white border border-slate-100 flex items-center justify-center">
                  <BotIcon className="w-8 h-8 opacity-30"/>
                </div>
                <div className="flex items-center gap-1 py-3">
                  <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce"></div>
                  <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce delay-100"></div>
                  <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce delay-200"></div>
                </div>
              </div>
            )}
          </div>
        )}
      </div>

      <div className="absolute bottom-10 left-0 right-0 px-6 sm:px-12 md:px-24 lg:px-48 pointer-events-none">
        <div className="max-w-4xl mx-auto pointer-events-auto">
          <div className="relative bg-white border-[2px] border-[#3b82f6] rounded-[2.5rem] px-5 py-3 shadow-[0_20px_70px_-20px_rgba(59,130,246,0.2)] flex flex-col gap-2 transition-all focus-within:shadow-[0_20px_70px_-20px_rgba(59,130,246,0.3)]">

            <div className="flex items-center gap-4 px-2">
               {/* Model Switcher */}
               <div className="relative">
                 <button 
                  onClick={() => setShowModelMenu(!showModelMenu)}
                  className="flex items-center gap-2 px-3 py-1 bg-slate-50 border border-slate-100 rounded-xl text-[9px] font-black text-[#64748b] uppercase tracking-widest cursor-pointer hover:bg-blue-50 hover:text-blue-600 transition-all shadow-sm group"
                 >
                    <CoreChatIcon className="w-3.5 h-3.5 opacity-60 group-hover:text-blue-500" />
                    <span>{MODEL_LABELS[model]}</span>
                    <span className="text-[9px] text-slate-300 ml-1">▾</span>
                 </button>

                 {showModelMenu && (
                   <div className="absolute bottom-full mb-2 left-0 w-48 bg-white border border-slate-200 rounded-2xl shadow-2xl py-2 z-50 animate-slide-up">
                      {(Object.keys(MODEL_MAP) as ModelType[]).map((m) => (
                        <button 
                          key={m}
                          onClick={() => { setActiveModel(m); setShowModelMenu(false); }}
                          className={`w-full text-left px-4 py-2 text-[10px] font-bold uppercase tracking-widest hover:bg-blue-50 transition-colors ${model === m ? 'text-blue-600' : 'text-slate-500'}`}
                        >
                          {MODEL_LABELS[m]}
                        </button>
                      ))}
                   </div>
                 )}
               </div>

               {/* Search Grounding Toggle */}
               <button 
                onClick={() => setIsSearchEnabled(!isSearchEnabled)}
                className={`flex items-center gap-2 px-3 py-1 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all shadow-sm border ${isSearchEnabled ? 'bg-blue-600 text-white border-blue-600' : 'bg-slate-50 border-slate-100 text-[#64748b] hover:bg-slate-100'}`}
               >
                  <SearchIcon className="w-3.5 h-3.5" />
                  <span>Deep Search</span>
                  {isSearchEnabled && <div className="w-1 h-1 rounded-full bg-white ml-1 animate-pulse" />}
               </button>
            </div>

            <div className="flex items-center gap-3">
                <button onClick={() => fileRef.current?.click()} className="w-9 h-9 shrink-0 flex items-center justify-center text-[#94a3b8] hover:text-blue-500 transition-all">
                    <AttachmentPlusIcon className="w-7 h-7 opacity-70" />
                    <input type="file" ref={fileRef} className="hidden" accept="image/*" onChange={(e) => {
                      const f = e.target.files?.[0];
                      if (f) {
                        const r = new FileReader();
                        r.onloadend = () => setSelectedImage({ data: (r.result as string).split(',')[1], mimeType: f.type });
                        r.readAsDataURL(f);
                      }
                    }} />
                </button>
                <textarea 
                  ref={textareaRef}
                  value={input} 
                  onChange={e => {
                    setInput(e.target.value);
                    e.target.style.height = 'auto';
                    e.target.style.height = Math.min(e.target.scrollHeight, 120) + 'px';
                  }} 
                  onKeyDown={e => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSend())}
                  placeholder="Message CognixAi..." 
                  className="flex-1 bg-transparent border-none outline-none resize-none py-2 text-[13px] text-[#1e293b] placeholder-[#94a3b8] font-semibold max-h-[120px] leading-snug" 
                  rows={1} 
                />
                <button 
                  onClick={handleSend}
                  disabled={isLoading || (!input.trim() && !selectedImage)}
                  className={`w-[44px] h-[44px] flex items-center justify-center rounded-full transition-all ${input.trim() || selectedImage ? 'bg-[#3b82f6] text-white' : 'bg-[#f1f5f9] text-[#94a3b8]'} active:scale-95`}
                >
                  <SendIcon className="w-6 h-6" />
                </button>
            </div>

            {selectedImage && (
              <div className="px-12 pb-2">
                <div className="relative w-14 h-14 rounded-xl overflow-hidden border-2 border-blue-500 shadow-md animate-fade-in group">
                  <img src={`data:${selectedImage.mimeType};base64,${selectedImage.data}`} className="w-full h-full object-cover" />
                  <button onClick={() => setSelectedImage(null)} className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 flex items-center justify-center text-white font-bold transition-opacity">×</button>
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { GoogleGenAI } from "@google/genai";
import { CodeIcon, CopyIcon, ImageIcon, SparklesIcon, SendIcon, BoltIcon } from './Icons';
import type { ThemeColors, ModelType } from '../types';

export const ToolboxView: React.FC<{ theme: ThemeColors, model: ModelType }> = ({ theme, model }) => {
    const [activeTool, setActiveTool] = useState<'summarizer' | 'scanner' | 'writer' | 'enhancer' | 'dev'>('summarizer');
    const [input, setInput] = useState('');
    const [result, setResult] = useState('');
    const [loading, setLoading] = useState(false);
    const [viewMode, setViewMode] = useState<'preview' | 'code'>('preview');
    const [mobileDevTab, setMobileDevTab] = useState<'editor' | 'view'>('editor');
    const [publishedUrl, setPublishedUrl] = useState<string | null>(null);
    const [selectedImage, setSelectedImage] = useState<{ data: string, mimeType: string } | null>(null);
    const [devLogs, setDevLogs] = useState<string[]>([]);
    const fileRef = useRef<HTMLInputElement>(null);

    const logActivity = (msg: string) => {
        setDevLogs(prev => [...prev.slice(-4), msg]);
    };

    const runTool = async () => {
        if (!input.trim() && !selectedImage) return;
        setLoading(true);
        if (activeTool !== 'dev') setResult('');
        setPublishedUrl(null);
        setDevLogs([]);

        try {
            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
            let instruction = "";
            let targetModelName: string = "";

            switch(model) {
                case 'cognix-rv2': targetModelName = 'gemini-3-flash-preview'; break;
                case 'clora-v1': targetModelName = 'gemini-3-pro-preview'; break;
                case 'clorea-v2.5': targetModelName = 'gemini-flash-lite-latest'; break;
                case 'arctic-x': targetModelName = 'gemini-3-pro-preview'; break;
                default: targetModelName = 'gemini-3-flash-preview';
            }

            if (activeTool === 'dev') {
                logActivity("Initializing Neural Architecture...");
                setTimeout(() => logActivity("Analyzing UI Requirements..."), 1000);
            }

            switch(activeTool) {
                case 'summarizer': instruction = "Summarize the following into elite bullet points."; break;
                case 'scanner': instruction = "Analyze this image in high detail."; targetModelName = 'gemini-3-flash-preview'; break;
                case 'writer': instruction = "Write professional engaging content."; break;
                case 'enhancer': instruction = "Engineer a high-fidelity prompt from this input."; break;
                case 'dev': instruction = "ACT AS A SENIOR FRONTEND ENGINEER. Build a modern, mobile-responsive single-file landing page using Tailwind CSS. OUTPUT RAW HTML ONLY starting with <!DOCTYPE html>. No commentary."; break;
            }

            const parts: any[] = [{ text: `${instruction}\n\nINPUT: "${input}"` }];
            if (selectedImage && activeTool === 'scanner') {
                parts.push({ inlineData: { data: selectedImage.data, mimeType: selectedImage.mimeType } });
            }

            const response = await ai.models.generateContent({
                model: targetModelName,
                contents: [{ parts }],
            });

            if (activeTool === 'dev') {
                logActivity("Synthesis Complete. Assembler Finalized.");
                setMobileDevTab('view'); // Auto switch to view on success for mobile
            }
            setResult(response.text || '');
        } catch (e) {
            setResult('Uplink failed. Try again.');
        } finally {
            setLoading(false);
        }
    };

    const handlePublish = () => {
        if (!result) return;
        try {
            const b64 = btoa(unescape(encodeURIComponent(result)));
            const url = `${window.location.origin}${window.location.pathname}?deployment=${b64}`;
            setPublishedUrl(url);
        } catch(e) { console.error("Publish failed", e); }
    };

    const tools = [
        { id: 'summarizer', label: 'Summarizer', desc: 'CONDENSER' },
        { id: 'scanner', label: 'Scanner', desc: 'VISION' },
        { id: 'writer', label: 'Writer', desc: 'CONTENT' },
        { id: 'enhancer', label: 'Enhancer', desc: 'PROMPT' },
        { id: 'dev', label: 'Dev Studio', desc: 'UI ARCHITECT' }
    ];

    if (activeTool === 'dev') {
        return (
            <div className="h-full bg-white dark:bg-[#020617] flex flex-col animate-fade-in overflow-hidden">
                <header className="px-4 sm:px-6 py-4 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between">
                    <div className="flex items-center gap-3">
                        <button onClick={() => setActiveTool('summarizer')} className="text-xs font-bold text-slate-500 hover:text-black dark:hover:text-white uppercase tracking-widest">← Back</button>
                        <h2 className="text-sm font-bold tracking-tight uppercase px-3 py-1 bg-black text-white dark:bg-white dark:text-black rounded-lg hidden sm:block">Dev Studio Node</h2>
                    </div>
                    <div className="flex sm:hidden bg-slate-100 dark:bg-slate-900 p-1 rounded-xl">
                        <button onClick={() => setMobileDevTab('editor')} className={`px-4 py-1.5 rounded-lg text-[10px] font-bold uppercase transition-all ${mobileDevTab === 'editor' ? 'bg-white dark:bg-slate-800 shadow-sm' : 'text-slate-500'}`}>Editor</button>
                        <button onClick={() => setMobileDevTab('view')} className={`px-4 py-1.5 rounded-lg text-[10px] font-bold uppercase transition-all ${mobileDevTab === 'view' ? 'bg-white dark:bg-slate-800 shadow-sm' : 'text-slate-500'}`}>Preview</button>
                    </div>
                    {result && (
                        <div className="hidden sm:flex bg-slate-100 dark:bg-slate-900 p-1 rounded-xl">
                            <button onClick={() => setViewMode('preview')} className={`px-4 py-1.5 rounded-lg text-[10px] font-bold uppercase transition-all ${viewMode === 'preview' ? 'bg-white dark:bg-slate-800 shadow-sm' : 'text-slate-500'}`}>Preview</button>
                            <button onClick={() => setViewMode('code')} className={`px-4 py-1.5 rounded-lg text-[10px] font-bold uppercase transition-all ${viewMode === 'code' ? 'bg-white dark:bg-slate-800 shadow-sm' : 'text-slate-500'}`}>Code</button>
                        </div>
                    )}
                </header>

                <div className="flex-1 flex flex-col sm:flex-row overflow-hidden">
                    {/* Editor Pane */}
                    <div className={`${mobileDevTab === 'editor' ? 'flex' : 'hidden'} sm:flex w-full sm:w-[400px] border-r border-slate-100 dark:border-slate-800 flex-col p-4 sm:p-6 space-y-4 overflow-y-auto`}>
                        <textarea 
                            value={input}
                            onChange={(e) => setInput(e.target.value)}
                            placeholder="Describe your UI vision (e.g., 'A modern travel landing page with hero section and feature cards')..."
                            className="flex-1 p-4 bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl text-sm font-medium outline-none resize-none focus:border-blue-500 transition-all min-h-[200px]"
                        />

                        {loading && devLogs.length > 0 && (
                            <div className="bg-slate-50 dark:bg-slate-900/50 p-4 rounded-xl border border-slate-200 dark:border-slate-800">
                                <p className="text-[9px] font-bold uppercase tracking-widest text-slate-400 mb-2">Neural Status</p>
                                <div className="space-y-1">
                                    {devLogs.map((log, i) => (
                                        <p key={i} className={`text-[10px] font-mono ${i === devLogs.length - 1 ? 'text-blue-500 font-bold' : 'text-slate-500 opacity-60'}`}>{`> ${log}`}</p>
                                    ))}
                                </div>
                            </div>
                        )}

                        <button 
                            onClick={runTool}
                            disabled={loading || !input.trim()}
                            className="w-full py-4 bg-black dark:bg-white text-white dark:text-black rounded-2xl font-bold text-[10px] uppercase tracking-[0.2em] shadow-lg active:scale-95 disabled:opacity-30 transition-all"
                        >
                            {loading ? 'Synthesizing...' : 'Build UI Asset'}
                        </button>
                    </div>

                    {/* Preview Pane */}
                    <div className={`${mobileDevTab === 'view' ? 'flex' : 'hidden'} sm:flex flex-1 bg-slate-50 dark:bg-[#01040a] relative flex-col overflow-hidden`}>
                        {!result ? (
                            <div className="flex-1 flex flex-col items-center justify-center text-slate-400 opacity-50 p-10 text-center">
                                <CodeIcon className="w-12 h-12 mb-4" />
                                <p className="text-xs font-bold uppercase tracking-widest leading-loose">Blueprint Ready.<br/>Generate a vision to start previewing.</p>
                            </div>
                        ) : viewMode === 'preview' ? (
                            <div className="flex-1 flex flex-col">
                                <div className="flex items-center justify-between px-6 py-2 bg-white dark:bg-slate-900 border-b border-slate-200 dark:border-slate-800">
                                    <span className="text-[10px] font-bold uppercase tracking-widest text-slate-500">Live Workspace</span>
                                    <button onClick={handlePublish} className="text-[10px] font-bold text-blue-600 hover:text-blue-700 uppercase tracking-widest transition-colors">Publish</button>
                                </div>
                                {publishedUrl && (
                                    <div className="p-3 bg-blue-50 dark:bg-blue-900/20 border-b border-blue-200 dark:border-blue-800 flex items-center justify-between gap-4 animate-slide-up">
                                        <p className="text-[9px] font-mono truncate text-blue-800 dark:text-blue-300">DEPLOYED: {publishedUrl}</p>
                                        <button onClick={() => { navigator.clipboard.writeText(publishedUrl); setPublishedUrl(null); }} className="px-3 py-1 bg-blue-600 text-white rounded-lg text-[9px] font-bold uppercase hover:bg-blue-700 transition-colors">Copy</button>
                                    </div>
                                )}
                                <iframe srcDoc={result} className="flex-1 w-full border-none bg-white" title="UI Preview" />
                            </div>
                        ) : (
                            <div className="flex-1 p-4 sm:p-6 overflow-hidden flex flex-col">
                                <div className="flex justify-between mb-4">
                                     <span className="text-[10px] font-bold uppercase tracking-widest text-slate-500">Raw Source</span>
                                     <button onClick={() => navigator.clipboard.writeText(result)} className="p-2 bg-white dark:bg-slate-800 rounded-lg border border-slate-200 dark:border-slate-700 hover:scale-105 transition-all active:scale-95"><CopyIcon className="w-4 h-4"/></button>
                                </div>
                                <pre className="flex-1 p-4 sm:p-6 bg-slate-900 text-slate-100 rounded-2xl text-[11px] overflow-auto custom-scrollbar font-mono leading-relaxed">
                                    {result}
                                </pre>
                            </div>
                        )}
                    </div>
                </div>
            </div>
        );
    }

    return (
        <div className="h-full overflow-y-auto bg-white dark:bg-[#020617] p-4 sm:p-10 animate-fade-in custom-scrollbar">
            <div className="max-w-6xl mx-auto space-y-10 pb-20">
