                        <textarea 
                            value={input} 
                            onChange={(e) => setInput(e.target.value)} 
                            placeholder="Provide context..." 
                            className="w-full p-4 h-32 rounded-2xl bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 outline-none text-black dark:text-white text-sm font-medium focus:border-blue-500 transition-all resize-none shadow-inner" 
                        />
