import React, { useState, useRef, useEffect, useCallback } from 'react';
import type { ChatMessage, ChatPart, ModelType, ChatSession, MemoryFact } from '../types';
import { GoogleGenAI } from "@google/genai";
import { SendIcon, AttachmentPlusIcon, BotIcon, UserIcon, CoreChatIcon, SearchIcon, SparklesIcon, BoltIcon, SparkleDotsIcon, ShieldIcon, CodeIcon } from './Icons';

interface ChatViewProps {
  messages: ChatMessage[];
  setMessages: React.Dispatch<React.SetStateAction<ChatMessage[]>>;
  systemInstruction: string;
  model: ModelType;
  setActiveModel: (m: ModelType) => void;
  participants: string[];
  onAddParticipant: (name: string) => void;
  currentChat?: ChatSession;
  isSidebarCollapsed?: boolean;
  memories?: MemoryFact[];
}

const MODEL_MAP: Record<ModelType, string> = {
  'cognix-rv2': 'gemini-3-flash-preview',
  'clora-v1': 'gemini-3-pro-preview',
  'clorea-v2.5': 'gemini-flash-lite-latest',
  'arctic-x': 'gemini-3-pro-preview'
};

const MODEL_LABELS: Record<ModelType, string> = {
  'cognix-rv2': 'CognixRv2',
  'clora-v1': 'CloraV1',
  'clorea-v2.5': 'CloreaV2.5',
  'arctic-x': 'ArcticX'
};

interface ModelConfig {
  id: ModelType;
  name: string;
  badge: string;
  desc: string;
  icon: React.ReactNode;
  instruction: string;
}

const MODELS_CONFIG: ModelConfig[] = [
  {
    id: 'cognix-rv2',
    name: 'CognixRv2',
    badge: 'DEFAULT',
    desc: 'Fast and reliable',
    icon: <BoltIcon className="w-4 h-4" />,
    instruction: "You are CognixRv2. Be fast, reliable, and concise. Ideal for daily tasks and general inquiries."
  },
  {
    id: 'clora-v1',
    name: 'CloraV1',
    badge: 'PRO',
    desc: 'Reasoning engine',
    icon: <SparkleDotsIcon className="w-4 h-4" />,
    instruction: "You are CloraV1, a deep reasoning engine. Provide detailed, step-by-step thinking for complex problems and nuanced creative tasks."
  },
  {
    id: 'clorea-v2.5',
    name: 'CloreaV2.5',
    badge: 'LITE',
    desc: 'Lightweight and fast',
    icon: <ShieldIcon className="w-4 h-4" />,
    instruction: "You are CloreaV2.5. Provide ultra-fast, brief, and efficient responses. Focus on speed and directness."
  },
  {
    id: 'arctic-x',
    name: 'ArcticX',
    badge: 'DEV',
    desc: 'Technical specialist',
    icon: <CodeIcon className="w-4 h-4" />,
    instruction: "You are ArcticX, a technical specialist. Focus heavily on clean, efficient code, documentation, and logical debugging. Prioritize technical accuracy above all."
  }
];

export const ChatView: React.FC<ChatViewProps> = ({ 
  messages, setMessages, systemInstruction, model, setActiveModel, currentChat, memories = []
}) => {
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isSearchEnabled, setIsSearchEnabled] = useState(false);
  const [selectedImage, setSelectedImage] = useState<{ data: string; mimeType: string } | null>(null);
  const [showModelMenu, setShowModelMenu] = useState(false);

  const containerRef = useRef<HTMLDivElement>(null);
  const fileRef = useRef<HTMLInputElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const menuRef = useRef<HTMLDivElement>(null);

  const hasMessages = messages.length > 0;

  useEffect(() => {
    if (containerRef.current) {
      containerRef.current.scrollTop = containerRef.current.scrollHeight;
    }
  }, [messages, isLoading]);

  // Click outside listener for model menu
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setShowModelMenu(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  const handleSend = useCallback(async () => {
    const trimmedInput = input.trim();
    if ((!trimmedInput && !selectedImage) || isLoading) return;

    const parts: ChatPart[] = [];
    if (selectedImage) parts.push({ inlineData: { mimeType: selectedImage.mimeType, data: selectedImage.data } });
    if (trimmedInput) parts.push({ text: trimmedInput });

    const userMsg: ChatMessage = { id: Date.now().toString(), role: 'user', parts };
    const botMsgId = (Date.now() + 1).toString();
    const botPlaceholder: ChatMessage = { id: botMsgId, role: 'model', parts: [{ text: '' }] };

    setMessages(prev => [...prev, userMsg, botPlaceholder]);
    setInput('');
    setSelectedImage(null);
    setIsLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const history = messages.slice(-10).map(m => ({
        role: m.role,
        parts: m.parts.map(p => p.text ? { text: p.text } : { inlineData: p.inlineData })
      }));

      const tools: any[] = [];
      if (isSearchEnabled) {
        tools.push({ googleSearch: {} });
      }

      const activeConfig = MODELS_CONFIG.find(c => c.id === model) || MODELS_CONFIG[0];

      const res = await ai.models.generateContent({
        model: MODEL_MAP[model] || 'gemini-3-flash-preview',
        contents: [...history, { role: 'user', parts: parts as any }],
        config: { 
          systemInstruction: systemInstruction + "\n\n" + activeConfig.instruction,
          tools: tools.length > 0 ? tools : undefined
        }
      });

      const resText = res.text || "No response received.";
      const groundingChunks = res.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
      const sources = groundingChunks
        .filter((chunk: any) => chunk.web)
        .map((chunk: any) => ({ uri: chunk.web.uri, title: chunk.web.title }));

      setMessages(prev => prev.map(m => m.id === botMsgId ? { 
        ...m, 
        parts: [{ 
          text: resText,
          searchResults: sources.length > 0 ? sources : undefined
        }] 
      } : m));
    } catch (e) {
      setMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, parts: [{ text: "Neural link timeout. Please retry." }] } : m));
    } finally {
      setIsLoading(false);
    }
  }, [input, selectedImage, isLoading, messages, systemInstruction, setMessages, model, isSearchEnabled]);

  const activeModelConfig = MODELS_CONFIG.find(c => c.id === model) || MODELS_CONFIG[0];

  return (
    <div className="h-full flex flex-col bg-white relative">
      <div 
        ref={containerRef} 
        className="flex-1 overflow-y-auto px-6 sm:px-12 md:px-24 lg:px-48 pb-64 pt-10 scroll-smooth custom-scrollbar"
      >
        {!hasMessages ? (
          <div className="h-full flex flex-col items-center justify-center select-none">
            <h2 className="text-[34px] font-bold text-[#0f172a] tracking-tight mb-2">How can I help you?</h2>
            <p className="text-[10px] font-bold text-[#94a3b8] uppercase tracking-[0.2em]">CognixAi Neural Link Active</p>
          </div>
        ) : (
          <div className="max-w-3xl mx-auto space-y-8">
            {messages.map((m) => (
              <div key={m.id} className={`flex gap-4 ${m.role === 'user' ? 'flex-row-reverse' : 'flex-row'} items-start animate-slide-up`}>
                <div className={`w-10 h-10 shrink-0 rounded-2xl flex items-center justify-center transition-all ${m.role === 'user' ? 'bg-[#0f172a]' : 'bg-white border border-slate-100 shadow-sm'}`}>
                   {m.role === 'user' ? <UserIcon className="w-5 h-5 text-white"/> : <BotIcon className="w-8 h-8 p-0.5"/>}
                </div>
                <div className={`flex flex-col gap-1.5 max-w-[85%] ${m.role === 'user' ? 'items-end' : 'items-start'}`}>
                  {m.parts.map((p, i) => (
                    <div key={i} className={`${m.role === 'user' ? 'bg-[#f1f5f9] text-[#1e293b] rounded-2xl px-5 py-2.5 font-semibold text-[14px]' : 'text-[#334155] font-medium text-[14px] leading-relaxed pt-1'}`}>
                      {p.text && <div className="whitespace-pre-wrap">{p.text}</div>}
                      {p.inlineData && <img src={`data:${p.inlineData.mimeType};base64,${p.inlineData.data}`} className="max-w-full h-auto rounded-2xl shadow-sm border border-slate-100 mt-2" />}

                      {p.searchResults && p.searchResults.length > 0 && (
                        <div className="mt-3 flex flex-wrap gap-2">
                          <p className="w-full text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-1 flex items-center gap-1">
                            <SearchIcon className="w-3 h-3" /> Grounded Sources
                          </p>
                          {p.searchResults.map((source: any, idx: number) => (
                            <a 
                              key={idx} 
                              href={source.uri} 
                              target="_blank" 
                              rel="noopener noreferrer"
                              className="px-2.5 py-1 bg-slate-50 border border-slate-200 rounded-lg text-[10px] font-bold text-blue-600 hover:bg-blue-50 transition-colors flex items-center gap-1"
                            >
                              {source.title || "Reference"}
                              <svg className="w-2.5 h-2.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6M15 3h6v6M10 14L21 3" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"/></svg>
                            </a>
                          ))}
                        </div>
                      )}
                    </div>
                  ))}
                </div>
              </div>
            ))}
            {isLoading && messages[messages.length-1]?.role === 'user' && (
              <div className="flex gap-4 animate-pulse">
                <div className="w-10 h-10 shrink-0 rounded-2xl bg-white border border-slate-100 flex items-center justify-center">
                  <BotIcon className="w-8 h-8 opacity-30"/>
                </div>
                <div className="flex items-center gap-1 py-3">
                  <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce"></div>
                  <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce delay-100"></div>
                  <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce delay-200"></div>
                </div>
              </div>
            )}
          </div>
        )}
      </div>

      <div className="absolute bottom-10 left-0 right-0 px-6 sm:px-12 md:px-24 lg:px-48 pointer-events-none">
        <div className="max-w-2xl mx-auto pointer-events-auto">
          <div className="relative bg-white border-[2px] border-[#3b82f6] rounded-[2.5rem] px-5 py-3 shadow-[0_20px_70px_-20px_rgba(59,130,246,0.2)] flex flex-col gap-2 transition-all focus-within:shadow-[0_20px_70px_-20px_rgba(59,130,246,0.3)]">

            <div className="flex items-center gap-4 px-2">
               {/* Model Switcher */}
               <div className="relative" ref={menuRef}>
                 <button 
                  onClick={() => setShowModelMenu(!showModelMenu)}
                  className="flex items-center gap-2 px-3 py-1 bg-slate-50 border border-slate-100 rounded-xl text-[9px] font-black text-[#64748b] uppercase tracking-widest cursor-pointer hover:bg-blue-50 hover:text-blue-600 transition-all shadow-sm group"
                 >
                    {activeModelConfig.icon}
                    <span>{activeModelConfig.name}</span>
                    <span className="text-[9px] text-slate-300 ml-1">▾</span>
                 </button>

                 {showModelMenu && (
                   <div className="absolute bottom-full mb-3 left-0 w-[280px] bg-white border border-slate-200 rounded-[2rem] shadow-2xl py-3 z-50 animate-slide-up overflow-hidden">
                      {MODELS_CONFIG.map((m) => (
                        <button 
                          key={m.id}
                          onClick={() => { setActiveModel(m.id); setShowModelMenu(false); }}
                          className={`w-full text-left px-5 py-3 flex items-start gap-4 transition-all hover:bg-slate-50 ${model === m.id ? 'bg-blue-50/50' : ''}`}
                        >
                          <div className={`w-10 h-10 shrink-0 rounded-2xl flex items-center justify-center transition-all ${model === m.id ? 'bg-blue-100 text-blue-600' : 'bg-slate-100 text-slate-400'}`}>
                             {m.icon}
                          </div>
                          <div className="flex-1">
                             <div className="flex items-center gap-2 mb-0.5">
                                <span className={`text-[13px] font-bold ${model === m.id ? 'text-blue-600' : 'text-slate-900'}`}>{m.name}</span>
                                <span className="px-1.5 py-0.5 bg-slate-100 text-slate-500 rounded-md text-[8px] font-black tracking-widest">{m.badge}</span>
                             </div>
                             <p className="text-[11px] text-slate-500 font-medium leading-tight">{m.desc}</p>
                          </div>
                        </button>
                      ))}
                   </div>
                 )}
               </div>

               {/* Search Grounding Toggle */}
               <button 
                onClick={() => setIsSearchEnabled(!isSearchEnabled)}
                className={`flex items-center gap-2 px-3 py-1 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all shadow-sm border ${isSearchEnabled ? 'bg-blue-600 text-white border-blue-600' : 'bg-slate-50 border-slate-100 text-[#64748b] hover:bg-slate-100'}`}
               >
                  <SearchIcon className="w-3.5 h-3.5" />
                  <span>Deep Search</span>
                  {isSearchEnabled && <div className="w-1 h-1 rounded-full bg-white ml-1 animate-pulse" />}
               </button>
            </div>

            <div className="flex items-center gap-3">
                <button onClick={() => fileRef.current?.click()} className="w-9 h-9 shrink-0 flex items-center justify-center text-[#94a3b8] hover:text-blue-500 transition-all">
                    <AttachmentPlusIcon className="w-7 h-7 opacity-70" />
                    <input type="file" ref={fileRef} className="hidden" accept="image/*" onChange={(e) => {
                      const f = e.target.files?.[0];
                      if (f) {
                        const r = new FileReader();
                        r.onloadend = () => setSelectedImage({ data: (r.result as string).split(',')[1], mimeType: f.type });
                        r.readAsDataURL(f);
                      }
                    }} />
                </button>
                <textarea 
                  ref={textareaRef}
                  value={input} 
                  onChange={e => {
                    setInput(e.target.value);
                    e.target.style.height = 'auto';
                    e.target.style.height = Math.min(e.target.scrollHeight, 120) + 'px';
                  }} 
                  onKeyDown={e => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSend())}
                  placeholder="Message CognixAi..." 
                  className="flex-1 bg-transparent border-none outline-none resize-none py-2 text-[13px] text-[#1e293b] placeholder-[#94a3b8] font-semibold max-h-[120px] leading-snug" 
                  rows={1} 
                />
                <button 
                  onClick={handleSend}
                  disabled={isLoading || (!input.trim() && !selectedImage)}
                  className={`w-[44px] h-[44px] flex items-center justify-center rounded-full transition-all ${input.trim() || selectedImage ? 'bg-[#3b82f6] text-white' : 'bg-[#f1f5f9] text-[#94a3b8]'} active:scale-95`}
                >
                  <SendIcon className="w-6 h-6" />
                </button>
            </div>

            {selectedImage && (
              <div className="px-12 pb-2">
                <div className="relative w-14 h-14 rounded-xl overflow-hidden border-2 border-blue-500 shadow-md animate-fade-in group">
                  <img src={`data:${selectedImage.mimeType};base64,${selectedImage.data}`} className="w-full h-full object-cover" />
                  <button onClick={() => setSelectedImage(null)} className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 flex items-center justify-center text-white font-bold transition-opacity">×</button>
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

